--
-- Estrutura para tabela `wp_userposts`
--

CREATE TABLE `wp_userposts` (
  `ID` bigint(20) UNSIGNED NOT NULL,
  `post_author` bigint(20) UNSIGNED NOT NULL DEFAULT 0,
  `post_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_date_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content` longtext NOT NULL,
  `post_title` text NOT NULL,
  `post_excerpt` text NOT NULL,
  `post_status` varchar(20) NOT NULL DEFAULT 'publish',
  `comment_status` varchar(20) NOT NULL DEFAULT 'open',
  `ping_status` varchar(20) NOT NULL DEFAULT 'open',
  `post_password` varchar(255) NOT NULL DEFAULT '',
  `post_name` varchar(200) NOT NULL DEFAULT '',
  `to_ping` text NOT NULL,
  `pinged` text NOT NULL,
  `post_modified` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_modified_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content_filtered` longtext NOT NULL,
  `post_parent` bigint(20) UNSIGNED NOT NULL DEFAULT 0,
  `guid` varchar(255) NOT NULL DEFAULT '',
  `menu_order` int(11) NOT NULL DEFAULT 0,
  `post_type` varchar(20) NOT NULL DEFAULT 'post',
  `post_mime_type` varchar(100) NOT NULL DEFAULT '',
  `comment_count` bigint(20) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;

--
-- Despejando dados para a tabela `wp_userposts`
--

INSERT INTO `wp_userposts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1, 1, '2026-09-09 13:07:36', '2026-09-09 16:07:36', '<!-- wp:paragraph -->\n<p>Boas-vindas ao WordPress. Esse é o seu primeiro post. Edite-o ou exclua-o, e então comece a escrever!</p>\n<!-- /wp:paragraph -->', 'Olá, mundo!', '', 'publish', 'open', 'open', '', 'ola-mundo', '', '', '2026-09-09 13:07:36', '2026-09-09 16:07:36', '', 0, 'http://localhost/faramcia_SL/wordpress/?p=1', 0, 'post', '', 1),
(3, 1, '2026-09-09 13:07:36', '2026-09-09 16:07:36', '<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Quem somos</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>O endereço do nosso site é: http://localhost/faramcia_SL/wordpress.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comentários</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>Quando os visitantes deixam comentários no site, coletamos os dados mostrados no formulário de comentários, além do endereço de IP e de dados do navegador do visitante, para auxiliar na detecção de spam.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Uma sequência anonimizada de caracteres criada a partir do seu e-mail (também chamada de hash) poderá ser enviada para o Gravatar para verificar se você usa o serviço. A política de privacidade do Gravatar está disponível aqui: https://automattic.com/privacy/. Depois da aprovação do seu comentário, a foto do seu perfil fica visível publicamente junto de seu comentário.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Mídia</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>Se você envia imagens para o site, evite enviar as que contenham dados de localização incorporados (EXIF GPS). Visitantes podem baixar estas imagens do site e extrair delas seus dados de localização.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>Ao deixar um comentário no site, você poderá optar por salvar seu nome, e-mail e site nos cookies. Isso visa seu conforto, assim você não precisará preencher seus  dados novamente quando fizer outro comentário. Estes cookies duram um ano.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Se você tem uma conta e acessa este site, um cookie temporário será criado para determinar se seu navegador aceita cookies. Ele não contém nenhum dado pessoal e será descartado quando você fechar seu navegador.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Quando você acessa sua conta no site, também criamos vários cookies para salvar os dados da sua conta e suas escolhas de exibição de tela. Cookies de login são mantidos por dois dias e cookies de opções de tela por um ano. Se você selecionar &quot;Lembrar-me&quot;, seu acesso será mantido por duas semanas. Se você se desconectar da sua conta, os cookies de login serão removidos.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Se você editar ou publicar um artigo, um cookie adicional será salvo no seu navegador. Este cookie não inclui nenhum dado pessoal e simplesmente indica o ID do post referente ao artigo que você acabou de editar. Ele expira depois de 1 dia.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Mídia incorporada de outros sites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>Artigos neste site podem incluir conteúdo incorporado como, por exemplo, vídeos, imagens, artigos, etc. Conteúdos incorporados de outros sites se comportam exatamente da mesma forma como se o visitante estivesse visitando o outro site.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Estes sites podem coletar dados sobre você, usar cookies, incorporar rastreamento adicional de terceiros e monitorar sua interação com este conteúdo incorporado, incluindo sua interação com o conteúdo incorporado se você tem uma conta e está conectado com o site.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Com quem compartilhamos seus dados</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>Se você solicitar uma redefinição de senha, seu endereço de IP será incluído no e-mail de redefinição de senha.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Por quanto tempo mantemos os seus dados</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>Se você deixar um comentário, o comentário e os seus metadados são conservados indefinidamente. Fazemos isso para que seja possível reconhecer e aprovar automaticamente qualquer comentário posterior ao invés de retê-lo para moderação.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Para usuários que se registram no nosso site (se houver), também guardamos as informações pessoais que fornecem no seu perfil de usuário. Todos os usuários podem ver, editar ou excluir suas informações pessoais a qualquer momento (só não é possível alterar o seu username). Os administradores de sites também podem ver e editar estas informações.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Quais os seus direitos sobre seus dados</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>Se você tiver uma conta neste site ou se tiver deixado comentários, pode solicitar um arquivo exportado dos dados pessoais que mantemos sobre você, inclusive quaisquer dados que nos tenha fornecido. Também pode solicitar que removamos qualquer dado pessoal que mantemos sobre você. Isto não inclui nenhuns dados que somos obrigados a manter para propósitos administrativos, legais ou de segurança.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Para onde seus dados são enviados</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>Comentários de visitantes podem ser marcados por um serviço automático de detecção de spam.</p>\n<!-- /wp:paragraph -->\n', 'Política de privacidade', '', 'draft', 'closed', 'open', '', 'politica-de-privacidade', '', '', '2026-09-09 13:07:36', '2026-09-09 16:07:36', '', 0, 'http://localhost/faramcia_SL/wordpress/?page_id=3', 0, 'page', '', 0),
(4, 0, '2026-09-09 13:07:40', '2026-09-09 16:07:40', '<!-- wp:page-list /-->', 'Navegação', '', 'publish', 'closed', 'closed', '', 'navigation', '', '', '2026-09-09 13:07:40', '2026-09-09 16:07:40', '', 0, 'http://localhost/faramcia_SL/wordpress/2026/09/09/navigation/', 0, 'wp_navigation', '', 0);
INSERT INTO `wp_userposts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(6, 1, '2026-09-09 13:11:34', '0000-00-00 00:00:00', '<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Farmácia Hospitalar · Hospital Santa Lúcia Bauru</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Serif:wght@400;500;600;700&family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n\n/* ===================================================================\n   TOKENS — Identidade visual do Hospital Santa Lúcia Bauru\n   =================================================================== */\n:root{\n  /* paleta institucional (fixa pelo briefing) */\n  --red: #A80F14;\n  --red-deep: #7A0B0F;\n  --red-tint: #FBEAEA;\n  --gray: #666666;\n  --white: #FFFFFF;\n  --gray-light: #F5F5F5;\n\n  /* derivados de apoio — tons de \"papel\" e tinta, não decorativos */\n  --paper: #FBFAF8;\n  --ink: #262321;\n  --line: #E2DDD7;\n  --line-soft: #EEEAE5;\n\n  /* cores funcionais — usadas só para status/segurança, nunca decoração */\n  --amber: #92600A;\n  --amber-bg: #FBF1DF;\n  --green: #2E6B40;\n  --green-bg: #E9F2EA;\n\n  /* tipografia */\n  --f-display: \"IBM Plex Serif\", Georgia, serif;\n  --f-body: \"IBM Plex Sans\", -apple-system, Segoe UI, sans-serif;\n  --f-mono: \"IBM Plex Mono\", \"SFMono-Regular\", monospace;\n\n  --radius: 3px;\n  --shadow-card: 0 1px 2px rgba(38,35,33,0.06), 0 1px 1px rgba(38,35,33,0.04);\n  --shadow-pop: 0 8px 24px rgba(38,35,33,0.12);\n\n  --sidebar-w: 248px;\n}\n\n*{ box-sizing: border-box; }\nhtml{ scroll-behavior: smooth; }\nbody{\n  margin:0;\n  font-family: var(--f-body);\n  color: var(--ink);\n  background: var(--gray-light);\n  -webkit-font-smoothing: antialiased;\n}\nh1,h2,h3,h4{ font-family: var(--f-display); margin:0; line-height:1.2; font-weight:600; }\np{ margin:0; }\na{ color: var(--red); text-decoration: none; }\nbutton{ font-family: var(--f-body); cursor:pointer; }\n:focus-visible{ outline: 2px solid var(--red); outline-offset: 2px; }\n.mono{ font-family: var(--f-mono); }\n\n@media (prefers-reduced-motion: reduce){\n  *{ animation-duration: 0.001ms !important; transition-duration: 0.001ms !important; scroll-behavior:auto !important; }\n}\n\n/* ===================================================================\n   SELO — elemento de assinatura visual do portal\n   Inspirado no carimbo oficial de validação de documentos hospitalares.\n   =================================================================== */\n.selo{\n  --size: 92px;\n  width: var(--size); height: var(--size);\n  border-radius: 50%;\n  border: 2px solid currentColor;\n  display:flex; align-items:center; justify-content:center;\n  position: relative;\n  transform: rotate(-9deg);\n  flex-shrink:0;\n  color: var(--red);\n}\n.selo::before{\n  content:\"\";\n  position:absolute; inset:6px;\n  border: 1px dashed currentColor;\n  border-radius:50%;\n  opacity:0.55;\n}\n.selo-texto{\n  font-family: var(--f-mono);\n  font-size: 8.5px;\n  font-weight:600;\n  letter-spacing: 0.5px;\n  text-align:center;\n  text-transform: uppercase;\n  line-height:1.25;\n  padding: 0 10px;\n}\n.selo.selo-sm{ --size: 44px; }\n.selo.selo-sm .selo-texto{ font-size: 5.6px; padding:0 5px; }\n.selo.selo-ghost{ color: var(--gray); opacity:0.65; }\n\n/* ===================================================================\n   LAYOUT GERAL\n   =================================================================== */\n.app{\n  display:flex;\n  min-height:100vh;\n}\n\n/* ---------- SIDEBAR ---------- */\n.sidebar{\n  width: var(--sidebar-w);\n  flex-shrink:0;\n  background: var(--ink);\n  color: var(--white);\n  display:flex;\n  flex-direction:column;\n  position: fixed;\n  top:0; left:0; bottom:0;\n  z-index: 40;\n  transition: transform .25s ease;\n}\n.sidebar-brand{\n  padding: 22px 20px 18px;\n  border-bottom: 1px solid rgba(255,255,255,0.12);\n  display:flex; align-items:center; gap:12px;\n}\n.sidebar-brand .selo{ color: var(--white); }\n.sidebar-brand-text{ font-family: var(--f-display); line-height:1.25; }\n.sidebar-brand-text strong{ display:block; font-size:14.5px; font-weight:600; }\n.sidebar-brand-text span{ display:block; font-size:11px; color: rgba(255,255,255,0.6); font-family: var(--f-body); margin-top:2px; }\n\n.nav{ flex:1; padding: 10px 12px; display:flex; flex-direction:column; gap:2px; overflow-y:auto; }\n.nav-item{\n  display:flex; align-items:center; gap:11px;\n  padding: 10px 12px;\n  border-radius: var(--radius);\n  color: rgba(255,255,255,0.72);\n  font-size: 13.5px;\n  font-weight:500;\n  background:none; border:none; text-align:left; width:100%;\n  transition: background .15s, color .15s;\n}\n.nav-item svg{ width:17px; height:17px; flex-shrink:0; opacity:0.9; }\n.nav-item:hover{ background: rgba(255,255,255,0.07); color: var(--white); }\n.nav-item.active{ background: var(--red); color: var(--white); }\n.nav-item .badge{\n  margin-left:auto;\n  font-family: var(--f-mono);\n  font-size: 10px;\n  background: rgba(255,255,255,0.14);\n  padding: 1px 6px;\n  border-radius: 10px;\n}\n.nav-item.active .badge{ background: rgba(255,255,255,0.25); }\n\n.sidebar-foot{\n  padding: 14px 20px 18px;\n  border-top: 1px solid rgba(255,255,255,0.12);\n  font-size: 11px;\n  color: rgba(255,255,255,0.5);\n  line-height:1.6;\n}\n\n/* ---------- TOPBAR (mobile) ---------- */\n.topbar{\n  display:none;\n  position: sticky; top:0; z-index:30;\n  background: var(--ink); color:var(--white);\n  align-items:center; gap:12px;\n  padding: 13px 16px;\n}\n.topbar button{\n  background:none; border:none; color:var(--white);\n  width:32px;height:32px; display:flex; align-items:center; justify-content:center;\n}\n.topbar .selo{ --size:32px; color:var(--white); }\n.topbar .selo .selo-texto{ font-size:4px; }\n.topbar-title{ font-family: var(--f-display); font-size:14px; font-weight:600; }\n\n.sidebar-scrim{ display:none; }\n\n/* ---------- MAIN ---------- */\n.main{\n  margin-left: var(--sidebar-w);\n  flex:1;\n  min-width:0;\n  display:flex; flex-direction:column;\n}\n.topstrip{\n  background: var(--white);\n  border-bottom: 1px solid var(--line);\n  padding: 16px 36px;\n  display:flex; align-items:center; gap:18px;\n  position: sticky; top:0; z-index:20;\n}\n.search{\n  flex:1; max-width: 480px;\n  display:flex; align-items:center; gap:9px;\n  background: var(--gray-light);\n  border:1px solid var(--line);\n  border-radius: var(--radius);\n  padding: 9px 13px;\n}\n.search svg{ width:15px; height:15px; color: var(--gray); flex-shrink:0; }\n.search input{\n  border:none; background:none; outline:none; width:100%;\n  font-size:13.5px; font-family:var(--f-body); color:var(--ink);\n}\n.topstrip-meta{\n  margin-left:auto;\n  display:flex; align-items:center; gap:16px;\n  font-size:12.5px; color:var(--gray);\n}\n.pill-status{\n  display:flex; align-items:center; gap:6px;\n  font-family: var(--f-mono); font-size:11.5px;\n  color: var(--green);\n  background: var(--green-bg);\n  padding: 5px 10px; border-radius: 20px;\n}\n.pill-status::before{ content:\"\"; width:6px;height:6px;border-radius:50%; background:currentColor; }\n\n.content{\n  flex:1;\n  padding: 32px 36px 64px;\n  max-width: 1180px;\n}\n\n.view{ display:none; animation: fadein .35s ease; }\n.view.active{ display:block; }\n@keyframes fadein{ from{opacity:0; transform:translateY(4px);} to{opacity:1; transform:translateY(0);} }\n\n.page-head{\n  display:flex; align-items:flex-end; justify-content:space-between; gap:20px;\n  margin-bottom: 28px;\n  padding-bottom: 18px;\n  border-bottom: 1px solid var(--line);\n}\n.page-head .eyebrow{\n  font-family: var(--f-mono); font-size:11px; letter-spacing:1px;\n  color: var(--red); text-transform:uppercase; margin-bottom:6px; display:block;\n}\n.page-head h1{ font-size: 26px; }\n.page-head p{ color: var(--gray); font-size: 13.5px; margin-top:6px; max-width:560px; }\n\n/* ===================================================================\n   COMPONENTES REUTILIZÁVEIS\n   =================================================================== */\n.card{\n  background: var(--white);\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  box-shadow: var(--shadow-card);\n}\n.grid{ display:grid; gap:18px; }\n.grid-2{ grid-template-columns: repeat(2,1fr); }\n.grid-3{ grid-template-columns: repeat(3,1fr); }\n.grid-4{ grid-template-columns: repeat(4,1fr); }\n\n.section-title{\n  display:flex; align-items:center; gap:9px;\n  font-size: 14px; font-weight:600; font-family: var(--f-display);\n  margin-bottom:14px;\n}\n.section-title svg{ width:16px;height:16px; color:var(--red); }\n.section-title .ver-tudo{\n  margin-left:auto; font-family:var(--f-body); font-size:12px; font-weight:500; color:var(--red);\n}\n\n.tag{\n  display:inline-flex; align-items:center; gap:5px;\n  font-size: 10.5px; font-weight:600; text-transform:uppercase; letter-spacing:.4px;\n  padding: 3px 8px; border-radius: 20px;\n  font-family: var(--f-body);\n}\n.tag-protocolo{ background:var(--red-tint); color:var(--red-deep); }\n.tag-padronizacao{ background:var(--green-bg); color:var(--green); }\n.tag-desabastecimento{ background:var(--amber-bg); color:var(--amber); }\n.tag-alerta{ background:#2A2A2A; color:#fff; }\n.tag-orientacao{ background:var(--gray-light); color:var(--gray); border:1px solid var(--line); }\n\n.btn{\n  display:inline-flex; align-items:center; gap:7px;\n  font-size:12.5px; font-weight:600;\n  padding: 8px 14px; border-radius: var(--radius);\n  border: 1px solid var(--line);\n  background: var(--white); color: var(--ink);\n  transition: border-color .15s, background .15s;\n}\n.btn svg{ width:13px;height:13px; }\n.btn:hover{ border-color: var(--gray); }\n.btn-primary{ background: var(--red); border-color:var(--red); color:var(--white); }\n.btn-primary:hover{ background: var(--red-deep); border-color:var(--red-deep); }\n.btn-block{ width:100%; justify-content:center; }\n.btn-ghost{ border-color:transparent; padding-left:4px; padding-right:4px; }\n\n.empty{\n  text-align:center; padding: 38px 20px; color: var(--gray); font-size:13px;\n}\n\n/* ===================================================================\n   DASHBOARD\n   =================================================================== */\n.hero-stamp{\n  display:flex; align-items:center; gap:22px;\n  background: var(--ink);\n  color: var(--white);\n  border-radius: var(--radius);\n  padding: 26px 30px;\n  margin-bottom: 26px;\n  position:relative;\n  overflow:hidden;\n}\n.hero-stamp::after{\n  content:\"\";\n  position:absolute; right:-40px; top:-60px;\n  width:220px; height:220px;\n  border:1px dashed rgba(255,255,255,0.08);\n  border-radius:50%;\n}\n.hero-stamp .selo{ color:var(--white); --size:78px; }\n.hero-stamp-text .eyebrow{ font-family:var(--f-mono); font-size:11px; letter-spacing:1px; color:#E7A6A8; text-transform:uppercase; }\n.hero-stamp-text h1{ font-size:21px; margin-top:6px; }\n.hero-stamp-text p{ font-size:13px; color:rgba(255,255,255,0.68); margin-top:7px; max-width:520px; }\n\n.kpi-row{ margin-bottom:26px; }\n.kpi{ padding: 16px 18px; }\n.kpi .kpi-num{ font-family:var(--f-display); font-size:25px; font-weight:600; }\n.kpi .kpi-label{ font-size:11.5px; color:var(--gray); margin-top:4px; line-height:1.4; }\n.kpi .kpi-trend{ font-family:var(--f-mono); font-size:10.5px; margin-top:8px; display:inline-block; padding:2px 7px; border-radius:10px; }\n.trend-up{ background:var(--green-bg); color:var(--green); }\n.trend-flat{ background:var(--gray-light); color:var(--gray); }\n.trend-warn{ background:var(--amber-bg); color:var(--amber); }\n\n.dash-grid{ display:grid; grid-template-columns: 1.3fr 1fr; gap:20px; margin-bottom:20px; }\n.dash-col{ display:flex; flex-direction:column; gap:20px; }\n\n.list-item{\n  display:flex; gap:13px; padding: 13px 16px;\n  border-bottom: 1px solid var(--line-soft);\n}\n.list-item:last-child{ border-bottom:none; }\n.list-item-icon{\n  width:30px;height:30px; border-radius:50%; flex-shrink:0;\n  display:flex; align-items:center; justify-content:center;\n  background: var(--red-tint); color:var(--red);\n}\n.list-item-icon svg{ width:14px;height:14px; }\n.list-item-body{ flex:1; min-width:0; }\n.list-item-title{ font-size:13px; font-weight:600; line-height:1.35; }\n.list-item-meta{ font-size:11px; color:var(--gray); margin-top:4px; display:flex; gap:8px; align-items:center; flex-wrap:wrap; }\n\n.alert-row{\n  display:flex; gap:12px; align-items:flex-start;\n  padding: 13px 16px;\n  border-left: 3px solid var(--amber);\n  background: var(--amber-bg);\n  border-radius: 0 var(--radius) var(--radius) 0;\n  margin-bottom:10px;\n}\n.alert-row.crit{ border-left-color: var(--red); background: var(--red-tint); }\n.alert-row svg{ width:16px;height:16px; flex-shrink:0; margin-top:1px; color:var(--amber); }\n.alert-row.crit svg{ color:var(--red); }\n.alert-row-title{ font-size:12.5px; font-weight:600; }\n.alert-row-text{ font-size:11.5px; color:var(--gray); margin-top:3px; line-height:1.45; }\n\n/* ===================================================================\n   COMUNICADOS\n   =================================================================== */\n.filter-row{ display:flex; gap:8px; margin-bottom:20px; flex-wrap:wrap; align-items:center; }\n.chip{\n  font-size:12px; font-weight:500; padding:7px 13px;\n  border-radius:20px; border:1px solid var(--line); background:var(--white); color:var(--gray);\n}\n.chip.active{ background: var(--ink); border-color:var(--ink); color:var(--white); }\n\n.com-card{ padding: 18px 20px; margin-bottom:14px; cursor:pointer; }\n.com-card-top{ display:flex; align-items:center; gap:10px; margin-bottom:8px; flex-wrap:wrap; }\n.com-card-date{ font-family:var(--f-mono); font-size:11px; color:var(--gray); }\n.com-card h3{ font-size:15px; margin-bottom:6px; }\n.com-card p{ font-size:13px; color:var(--gray); line-height:1.55; }\n.com-card-foot{ margin-top:12px; display:flex; align-items:center; gap:14px; }\n.anexo-link{ display:flex; align-items:center; gap:6px; font-size:12px; font-weight:600; color:var(--red); }\n.anexo-link svg{ width:13px;height:13px; }\n\n.com-detail-body{ font-size:13.5px; line-height:1.7; color:var(--ink); }\n.com-detail-body p{ margin-bottom:12px; }\n\n/* ===================================================================\n   POPs — biblioteca em formato de \"ficha de documento\"\n   =================================================================== */\n.lib-toolbar{ display:flex; gap:10px; margin-bottom:18px; flex-wrap:wrap; }\n.lib-toolbar .search{ max-width:340px; }\n\n.pop-card{\n  display:flex; gap:0; overflow:hidden; margin-bottom:12px;\n}\n.pop-card-tab{\n  width:6px; background: var(--red); flex-shrink:0;\n}\n.pop-card-body{ padding:16px 18px; flex:1; display:flex; gap:16px; align-items:flex-start; }\n.pop-card-code{\n  font-family:var(--f-mono); font-size:12px; color:var(--gray);\n  background:var(--gray-light); padding:8px 10px; border-radius:var(--radius);\n  text-align:center; flex-shrink:0; min-width:108px;\n}\n.pop-card-code .ver{ display:block; margin-top:4px; font-weight:600; color:var(--red); }\n.pop-card-main{ flex:1; min-width:0; }\n.pop-card-main h3{ font-size:14.5px; margin-bottom:5px; }\n.pop-card-main-meta{ font-size:11.5px; color:var(--gray); display:flex; gap:12px; flex-wrap:wrap; margin-top:6px; }\n.pop-card-actions{ display:flex; gap:8px; flex-shrink:0; align-self:center; }\n\n/* ===================================================================\n   TREINAMENTOS\n   =================================================================== */\n.train-card{ overflow:hidden; }\n.train-thumb{\n  height: 108px;\n  background: linear-gradient(135deg, var(--ink), #3a3431);\n  display:flex; align-items:center; justify-content:center;\n  position:relative;\n}\n.train-thumb svg{ width:30px; height:30px; color: rgba(255,255,255,0.85); }\n.train-thumb .dur{\n  position:absolute; bottom:8px; right:10px;\n  font-family:var(--f-mono); font-size:10.5px; color:#fff;\n  background: rgba(0,0,0,0.45); padding:2px 7px; border-radius:10px;\n}\n.train-body{ padding:16px 18px; }\n.train-body h3{ font-size:14px; margin-bottom:7px; }\n.train-body p{ font-size:12.5px; color:var(--gray); line-height:1.55; margin-bottom:12px; }\n.train-audience{ font-size:11px; color:var(--gray); margin-bottom:14px; display:flex; gap:6px; align-items:center; }\n.train-actions{ display:flex; gap:8px; flex-wrap:wrap; }\n.train-actions .btn{ flex:1; justify-content:center; }\n\n/* ===================================================================\n   PADRONIZAÇÃO\n   =================================================================== */\n.table-wrap{ overflow-x:auto; }\ntable.std-table{ width:100%; border-collapse:collapse; font-size:13px; }\ntable.std-table th{\n  text-align:left; font-size:11px; text-transform:uppercase; letter-spacing:.4px;\n  color:var(--gray); padding:11px 16px; border-bottom:1px solid var(--line); font-weight:600;\n}\ntable.std-table td{ padding:13px 16px; border-bottom:1px solid var(--line-soft); }\ntable.std-table tr:last-child td{ border-bottom:none; }\n.status-dot{ display:inline-flex; align-items:center; gap:6px; font-size:12px; font-weight:600; }\n.status-dot::before{ content:\"\"; width:7px;height:7px;border-radius:50%; }\n.status-padronizado::before{ background:var(--green); }\n.status-padronizado{ color:var(--green); }\n.status-alternativa::before{ background:var(--amber); }\n.status-alternativa{ color:var(--amber); }\n\n/* ===================================================================\n   SEGURANÇA DO PACIENTE\n   =================================================================== */\n.lasa-pair{\n  display:flex; align-items:center; gap:14px; padding:15px 18px; margin-bottom:10px;\n}\n.lasa-word{ font-family:var(--f-display); font-weight:700; font-size:16px; }\n.lasa-word .hl{ background: #FCE4A6; padding:0 2px; border-radius:2px; }\n.lasa-vs{ font-family:var(--f-mono); font-size:11px; color:var(--gray); }\n.lasa-note{ margin-left:auto; font-size:11.5px; color:var(--gray); max-width:280px; text-align:right; }\n\n.vigilancia-grid{ display:grid; grid-template-columns:repeat(2,1fr); gap:10px; }\n.vigilancia-item{\n  display:flex; align-items:center; gap:10px; padding:13px 15px;\n  border-left:3px solid var(--red);\n}\n.vigilancia-item svg{ width:16px;height:16px; color:var(--red); flex-shrink:0; }\n.vigilancia-item span{ font-size:13px; font-weight:600; }\n\n.check-steps{ display:flex; flex-direction:column; gap:0; }\n.check-step{ display:flex; gap:14px; padding:14px 0; border-bottom:1px solid var(--line-soft); }\n.check-step:last-child{ border-bottom:none; }\n.check-step-num{\n  font-family:var(--f-mono); font-weight:600; font-size:12px;\n  width:26px; height:26px; border-radius:50%; background:var(--ink); color:#fff;\n  display:flex; align-items:center; justify-content:center; flex-shrink:0;\n}\n.check-step-text strong{ display:block; font-size:13px; margin-bottom:2px; }\n.check-step-text span{ font-size:12px; color:var(--gray); }\n\n/* ===================================================================\n   FLUXOS — diagramas em sequência (numerados, pois SÃO sequências reais)\n   =================================================================== */\n.flow-acc{ margin-bottom:12px; }\n.flow-acc-head{\n  display:flex; align-items:center; gap:13px; padding:16px 20px;\n  width:100%; background:none; border:none; text-align:left;\n}\n.flow-acc-head .num{ font-family:var(--f-mono); font-size:12px; color:var(--gray); }\n.flow-acc-head h3{ font-size:14.5px; flex:1; }\n.flow-acc-head svg{ width:15px;height:15px; color:var(--gray); transition:transform .2s; flex-shrink:0; }\n.flow-acc.open .flow-acc-head svg{ transform: rotate(180deg); }\n.flow-acc-body{ display:none; padding: 0 22px 20px 22px; }\n.flow-acc.open .flow-acc-body{ display:block; }\n\n.flow-steps{ display:flex; gap:0; overflow-x:auto; padding-top:6px; padding-bottom:8px; }\n.flow-step{ display:flex; align-items:flex-start; flex-shrink:0; min-width:168px; }\n.flow-step-inner{ padding-right:18px; }\n.flow-step-num{\n  font-family:var(--f-mono); font-size:11px; color:var(--white); background:var(--red);\n  width:22px; height:22px; border-radius:50%; display:flex; align-items:center; justify-content:center; margin-bottom:8px;\n}\n.flow-step-title{ font-size:12.5px; font-weight:600; line-height:1.4; }\n.flow-step-text{ font-size:11.5px; color:var(--gray); margin-top:4px; line-height:1.45; }\n.flow-arrow{ color:var(--line); margin: 0 4px; padding-top:5px; flex-shrink:0; }\n.flow-arrow svg{ width:16px;height:16px; }\n\n/* ===================================================================\n   CONTATO\n   =================================================================== */\n.contact-grid{ display:grid; grid-template-columns: 1.4fr 1fr; gap:22px; }\n.form-card{ padding:24px; }\n.field{ margin-bottom:16px; }\n.field label{ display:block; font-size:12px; font-weight:600; margin-bottom:6px; }\n.field input, .field select, .field textarea{\n  width:100%; padding:10px 12px; border:1px solid var(--line); border-radius:var(--radius);\n  font-family:var(--f-body); font-size:13px; background:var(--white); color:var(--ink);\n}\n.field textarea{ resize:vertical; min-height:90px; }\n.field input:focus, .field select:focus, .field textarea:focus{ outline:2px solid var(--red); outline-offset:0; border-color:var(--red); }\n.field-row{ display:grid; grid-template-columns:1fr 1fr; gap:14px; }\n\n.contact-info-item{ display:flex; gap:12px; padding:15px 0; border-bottom:1px solid var(--line-soft); }\n.contact-info-item:last-child{ border-bottom:none; }\n.contact-info-item svg{ width:16px;height:16px; color:var(--red); flex-shrink:0; margin-top:2px; }\n.contact-info-item strong{ display:block; font-size:12.5px; margin-bottom:2px; }\n.contact-info-item span{ font-size:12px; color:var(--gray); line-height:1.5; }\n\n.confirm-box{\n  display:none; align-items:flex-start; gap:12px;\n  background:var(--green-bg); border-left:3px solid var(--green);\n  padding:14px 16px; border-radius:0 var(--radius) var(--radius) 0; margin-bottom:16px;\n}\n.confirm-box.show{ display:flex; }\n.confirm-box svg{ width:17px;height:17px; color:var(--green); flex-shrink:0; margin-top:1px; }\n.confirm-box strong{ font-size:13px; display:block; }\n.confirm-box span{ font-size:12px; color:var(--gray); }\n\n/* ===================================================================\n   MODAL (detalhe de comunicado)\n   =================================================================== */\n.modal-scrim{\n  position:fixed; inset:0; background:rgba(38,35,33,0.55); z-index:60;\n  display:none; align-items:center; justify-content:center; padding:24px;\n}\n.modal-scrim.show{ display:flex; }\n.modal-box{\n  background:var(--white); border-radius:var(--radius); max-width:560px; width:100%;\n  max-height:85vh; overflow-y:auto; box-shadow: var(--shadow-pop);\n}\n.modal-head{ padding:22px 24px 16px; border-bottom:1px solid var(--line); display:flex; gap:16px; align-items:flex-start; }\n.modal-head h2{ font-size:17px; flex:1; }\n.modal-close{ background:none; border:none; color:var(--gray); width:28px; height:28px; flex-shrink:0; }\n.modal-close svg{ width:18px;height:18px; }\n.modal-body{ padding:20px 24px 26px; }\n\n/* ===================================================================\n   RESPONSIVO\n   =================================================================== */\n@media (max-width: 980px){\n  .grid-4{ grid-template-columns: repeat(2,1fr); }\n  .grid-3{ grid-template-columns: repeat(2,1fr); }\n  .dash-grid{ grid-template-columns: 1fr; }\n  .contact-grid{ grid-template-columns: 1fr; }\n}\n\n@media (max-width: 760px){\n  .sidebar{ transform: translateX(-100%); width: 270px; }\n  .sidebar.open{ transform: translateX(0); box-shadow: var(--shadow-pop); }\n  .main{ margin-left:0; }\n  .topbar{ display:flex; }\n  .topstrip{ padding:14px 18px; }\n  .topstrip-meta .pill-status span{ display:none; }\n  .content{ padding: 22px 18px 50px; }\n  .grid-2, .grid-3, .grid-4{ grid-template-columns: 1fr; }\n  .vigilancia-grid{ grid-template-columns:1fr; }\n  .field-row{ grid-template-columns:1fr; }\n  .hero-stamp{ flex-direction:column; align-items:flex-start; text-align:left; }\n  .pop-card-body{ flex-direction:column; gap:12px; }\n  .pop-card-actions{ align-self:flex-start; }\n  .sidebar-scrim.show{\n    display:block; position:fixed; inset:0; background:rgba(0,0,0,0.4); z-index:35;\n  }\n  .page-head{ flex-direction:column; align-items:flex-start; }\n}\n</style>\n</head>\n<body>\n\n<div class=\"app\">\n\n  <!-- ============================ SIDEBAR ============================ -->\n  <aside class=\"sidebar\" id=\"sidebar\">\n    <div class=\"sidebar-brand\">\n      <div class=\"selo selo-sm\"><span class=\"selo-texto\">Farmácia · Uso Seguro</span></div>\n      <div class=\"sidebar-brand-text\">\n        <strong>Farmácia Hospitalar</strong>\n        <span>Hospital Santa Lúcia Bauru</span>\n      </div>\n    </div>\n    <nav class=\"nav\" id=\"nav\"></nav>\n    <div class=\"sidebar-foot\">\n      Portal de uso interno.<br>Conteúdo de exemplo — substitua pelos dados oficiais da unidade.\n    </div>\n  </aside>\n  <div class=\"sidebar-scrim\" id=\"sidebarScrim\"></div>\n\n  <div class=\"main\">\n    <!-- ============================ TOPBAR (mobile) ============================ -->\n    <div class=\"topbar\">\n      <button id=\"menuBtn\" aria-label=\"Abrir menu\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M3 6h18M3 12h18M3 18h18\"/></svg>\n      </button>\n      <div class=\"selo\"><span class=\"selo-texto\">Farmácia</span></div>\n      <span class=\"topbar-title\">Farmácia Hospitalar</span>\n    </div>\n\n    <!-- ============================ TOPSTRIP ============================ -->\n    <div class=\"topstrip\">\n      <div class=\"search\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n        <input id=\"globalSearch\" placeholder=\"Buscar POPs, comunicados, medicamentos…\" autocomplete=\"off\">\n      </div>\n      <div class=\"topstrip-meta\">\n        <span class=\"pill-status\"><span>Sistemas operacionais</span></span>\n      </div>\n    </div>\n\n    <!-- ============================ CONTEÚDO ============================ -->\n    <div class=\"content\" id=\"content\"><!-- views injetadas via JS --></div>\n  </div>\n</div>\n\n<!-- ============================ MODAL COMUNICADO ============================ -->\n<div class=\"modal-scrim\" id=\"modalScrim\">\n  <div class=\"modal-box\">\n    <div class=\"modal-head\">\n      <h2 id=\"modalTitle\"></h2>\n      <button class=\"modal-close\" id=\"modalClose\" aria-label=\"Fechar\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M18 6L6 18M6 6l12 12\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\" id=\"modalBody\"></div>\n  </div>\n</div>\n\n<script>\n/* =====================================================================\n   ÍCONES — glifos simples e consistentes (24x24, stroke), sem dependência externa\n   ===================================================================== */\nconst ICONS = {\n  home: \'<path d=\"M4 11.5L12 4l8 7.5\"/><path d=\"M6 10v9h12v-9\"/><path d=\"M10 19v-5h4v5\"/>\',\n  megaphone: \'<path d=\"M3 11v3a1 1 0 001 1h2l4 4V6L6 10H4a1 1 0 00-1 1z\"/><path d=\"M10 7l8-3v17l-8-3\"/><path d=\"M19 10.5a3 3 0 010 4\"/>\',\n  book: \'<path d=\"M4 19.5A2.5 2.5 0 016.5 17H20\"/><path d=\"M4 5.5A2.5 2.5 0 016.5 3H20v17H6.5A2.5 2.5 0 014 17.5v-12z\"/>\',\n  cap: \'<path d=\"M2 9l10-4 10 4-10 4-10-4z\"/><path d=\"M6 11.5V16c0 1.5 3 3 6 3s6-1.5 6-3v-4.5\"/>\',\n  pill: \'<path d=\"M5 13.5L13.5 5a4.5 4.5 0 016.36 6.36L11.36 19.86A4.5 4.5 0 015 13.5z\"/><path d=\"M9 9l6 6\"/>\',\n  shield: \'<path d=\"M12 3l8 3v6c0 5-3.5 7.5-8 9-4.5-1.5-8-4-8-9V6l8-3z\"/><path d=\"M9 12l2.2 2.2L15.5 9.5\"/>\',\n  flow: \'<circle cx=\"5\" cy=\"6\" r=\"2.2\"/><circle cx=\"19\" cy=\"6\" r=\"2.2\"/><circle cx=\"12\" cy=\"18\" r=\"2.2\"/><path d=\"M7 7l3.5 9M17 7l-3.5 9\"/>\',\n  mail: \'<path d=\"M4 6h16v12H4z\"/><path d=\"M4 7l8 6 8-6\"/>\',\n  chev: \'<path d=\"M6 9l6 6 6-6\"/>\',\n  paperclip: \'<path d=\"M8 12l6-6a3 3 0 014.2 4.2l-8 8a5 5 0 01-7-7l7-7\"/>\',\n  alert: \'<path d=\"M12 3l9 16H3l9-16z\"/><path d=\"M12 10v4\"/><circle cx=\"12\" cy=\"17\" r=\"0.6\"/>\',\n  check: \'<path d=\"M5 13l4 4L19 7\"/>\',\n  bell: \'<path d=\"M9 18a3 3 0 006 0\"/><path d=\"M6 11a6 6 0 1112 0v3.5l1.5 2.5h-15L6 14.5V11z\"/>\',\n  download: \'<path d=\"M12 4v11\"/><path d=\"M7 11l5 5 5-5\"/><path d=\"M5 19h14\"/>\',\n  film: \'<path d=\"M4 5h16v14H4z\"/><path d=\"M4 9h16M4 15h16M9 5v4M9 15v4\"/>\',\n  pin: \'<path d=\"M12 21s7-6.2 7-11.5A7 7 0 105 9.5C5 14.8 12 21 12 21z\"/><circle cx=\"12\" cy=\"9.5\" r=\"2.3\"/>\',\n  phone: \'<path d=\"M5 4h3l2 5-2.5 2a11 11 0 005.5 5.5l2-2.5 5 2v3a1 1 0 01-1 1A16 16 0 014 5a1 1 0 011-1z\"/>\',\n  clock: \'<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3.5 2\"/>\',\n  send: \'<path d=\"M3 11l18-8-8 18-2.5-7L3 11z\"/>\'\n};\nfunction ic(name, cls=\'\'){ return `<svg class=\"${cls}\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\">${ICONS[name]||\'\'}</svg>`; }\n\n/* =====================================================================\n   CONTEÚDO — substitua estes dados pelos materiais oficiais da farmácia.\n   Tudo o que aparece no portal vem destes objetos; não é necessário\n   editar HTML/CSS para atualizar comunicados, POPs, treinamentos etc.\n   ===================================================================== */\n\nconst NAV_ITEMS = [\n  { id:\'home\', label:\'Início\', icon:\'home\' },\n  { id:\'comunicados\', label:\'Comunicados\', icon:\'megaphone\', badge:()=>COMUNICADOS.length },\n  { id:\'pops\', label:\'POPs e Protocolos\', icon:\'book\', badge:()=>POPS.length },\n  { id:\'treinamentos\', label:\'Treinamentos\', icon:\'cap\' },\n  { id:\'padronizacao\', label:\'Padronização\', icon:\'pill\' },\n  { id:\'seguranca\', label:\'Segurança do Paciente\', icon:\'shield\' },\n  { id:\'fluxos\', label:\'Fluxos e Processos\', icon:\'flow\' },\n  { id:\'contato\', label:\'Contato\', icon:\'mail\' },\n];\n\nconst COMUNICADOS = [\n  {\n    id:\'c1\', cat:\'padronizacao\', catLabel:\'Padronização\',\n    titulo:\'Atualização da Lista de Medicamentos Padronizados — Junho/2026\',\n    data:\'24/06/2026\',\n    resumo:\'Inclusão de 3 itens e substituição de apresentação de 2 antimicrobianos na lista vigente, após avaliação da Comissão de Farmácia e Terapêutica (CFT).\',\n    corpo:\'A Comissão de Farmácia e Terapêutica aprovou, em reunião ordinária, a atualização da lista de medicamentos padronizados para o mês de junho. As principais alterações envolvem a inclusão de novas apresentações para adequação às boas práticas de fracionamento e a substituição de itens com restrição de fornecimento pelo distribuidor.\\n\\nAs unidades assistenciais devem observar a nova lista a partir de 01/07/2026. Estoques remanescentes dos itens substituídos poderão ser utilizados até o esgotamento, mediante orientação da farmácia clínica.\\n\\nDúvidas podem ser encaminhadas pelo canal de solicitações da farmácia.\',\n    anexo:\'Lista_Padronizacao_Jun2026.pdf\'\n  },\n  {\n    id:\'c2\', cat:\'desabastecimento\', catLabel:\'Desabastecimento\',\n    titulo:\'Desabastecimento temporário — Cloridrato de Vancomicina 500mg\',\n    data:\'21/06/2026\',\n    resumo:\'Fornecedor informou indisponibilidade pontual. Estoque de segurança garante cobertura prevista de 12 dias; alternativa terapêutica orientada para novas prescrições.\',\n    corpo:\'Em razão de instabilidade na cadeia de fornecimento, a Vancomicina 500mg pó para solução injetável encontra-se com fornecimento irregular. A farmácia mantém estoque estratégico para atendimento das prescrições em curso.\\n\\nPara novas prescrições, recomenda-se contato prévio com a farmácia clínica para avaliação de alternativa terapêutica e ajuste posológico, conforme nota técnica anexa.\\n\\nA situação será reavaliada semanalmente e novas atualizações serão publicadas neste canal.\',\n    anexo:\'Nota_Tecnica_Vancomicina.pdf\'\n  },\n  {\n    id:\'c3\', cat:\'protocolo\', catLabel:\'Protocolo\',\n    titulo:\'Novo fluxo de solicitação de medicamentos não padronizados\',\n    data:\'18/06/2026\',\n    resumo:\'A solicitação passa a ser feita exclusivamente pelo formulário eletrônico da farmácia, com prazo de resposta de até 4 horas em dias úteis.\',\n    corpo:\'A partir desta data, solicitações de medicamentos não padronizados deverão ser registradas pelo canal eletrônico da farmácia (seção \"Fluxos e Processos\" deste portal), substituindo o formulário em papel.\\n\\nO novo fluxo prevê: registro da solicitação justificada pelo médico assistente, análise farmacêutica de pertinência clínica e disponibilidade, e retorno em até 4 horas em dias úteis (8 horas em finais de semana e feriados).\\n\\nCasos de urgência devem ser comunicados também por telefone ao ramal da farmácia central.\',\n    anexo:\'Fluxo_Medicamento_Nao_Padronizado.pdf\'\n  },\n  {\n    id:\'c4\', cat:\'alerta\', catLabel:\'Alerta sanitário\',\n    titulo:\'Alerta ANVISA — recolhimento de lote de Insulina Regular\',\n    data:\'15/06/2026\',\n    resumo:\'Recolhimento preventivo de lote específico por desvio de qualidade. Farmácia já realizou conferência de estoque; nenhum frasco do lote identificado na unidade.\',\n    corpo:\'Em atenção ao alerta da ANVISA, a farmácia realizou conferência imediata do estoque de Insulina Regular. Não foram localizados frascos pertencentes ao lote objeto do recolhimento nesta unidade.\\n\\nAinda assim, recomenda-se que a equipe assistencial confira o número de lote de frascos já distribuídos para os setores antes da administração, conforme rotina padrão de checagem dupla para medicamentos de alta vigilância.\\n\\nEm caso de identificação do lote, suspender o uso e notificar a farmácia imediatamente.\',\n    anexo:\'Alerta_Anvisa_Insulina.pdf\'\n  },\n  {\n    id:\'c5\', cat:\'orientacao\', catLabel:\'Orientação institucional\',\n    titulo:\'Horário de funcionamento da Farmácia Central — feriado\',\n    data:\'10/06/2026\',\n    resumo:\'Atendimento em horário reduzido no feriado, com plantão para urgências mantido em regime 24h.\',\n    corpo:\'No feriado do próximo dia 24, a Farmácia Central funcionará em horário reduzido (8h às 14h) para dispensação de rotina. O plantão farmacêutico para urgências e setores críticos permanece em regime de 24 horas, conforme escala afixada no mural da farmácia.\\n\\nSolicitações de medicamentos não padronizados serão analisadas no primeiro dia útil subsequente, exceto em caráter de urgência clínica.\',\n    anexo:null\n  },\n];\n\nconst POPS = [\n  { codigo:\'POP-FAR-001\', versao:\'v4.0\', titulo:\'Dispensação de medicamentos em unidades de internação\', cat:\'dispensacao\', catLabel:\'Dispensação\', data:\'12/05/2026\' },\n  { codigo:\'POP-FAR-014\', versao:\'v2.1\', titulo:\'Armazenamento de medicamentos termolábeis (cadeia fria)\', cat:\'cadeia-fria\', catLabel:\'Cadeia fria\', data:\'03/04/2026\' },\n  { codigo:\'POP-FAR-022\', versao:\'v3.2\', titulo:\'Manejo de medicamentos de alta vigilância\', cat:\'alta-vigilancia\', catLabel:\'Alta vigilância\', data:\'28/05/2026\' },\n  { codigo:\'POP-FAR-030\', versao:\'v2.0\', titulo:\'Dispensação e controle de antimicrobianos\', cat:\'antimicrobianos\', catLabel:\'Antimicrobianos\', data:\'15/02/2026\' },\n  { codigo:\'POP-FAR-045\', versao:\'v1.3\', titulo:\'Fracionamento de formas sólidas orais\', cat:\'fracionamento\', catLabel:\'Fracionamento\', data:\'20/01/2026\' },\n  { codigo:\'POP-FAR-052\', versao:\'v2.4\', titulo:\'Manipulação de nutrição parenteral\', cat:\'farmacotecnica\', catLabel:\'Farmacotécnica hospitalar\', data:\'09/06/2026\' },\n  { codigo:\'POP-FAR-007\', versao:\'v3.0\', titulo:\'Armazenamento geral de medicamentos e correlatos\', cat:\'armazenamento\', catLabel:\'Armazenamento\', data:\'02/03/2026\' },\n  { codigo:\'POP-FAR-038\', versao:\'v1.1\', titulo:\'Reconstituição e diluição de antimicrobianos injetáveis\', cat:\'antimicrobianos\', catLabel:\'Antimicrobianos\', data:\'11/11/2025\' },\n];\n\nconst POP_CATEGORIAS = [\n  { id:\'todas\', label:\'Todas\' },\n  { id:\'dispensacao\', label:\'Dispensação\' },\n  { id:\'armazenamento\', label:\'Armazenamento\' },\n  { id:\'cadeia-fria\', label:\'Cadeia fria\' },\n  { id:\'alta-vigilancia\', label:\'Alta vigilância\' },\n  { id:\'antimicrobianos\', label:\'Antimicrobianos\' },\n  { id:\'fracionamento\', label:\'Fracionamento\' },\n  { id:\'farmacotecnica\', label:\'Farmacotécnica\' },\n];\n\nconst TREINAMENTOS = [\n  { titulo:\'Uso seguro de medicamentos de alta vigilância\', publico:\'Enfermagem e Farmácia\', duracao:\'25 min\', desc:\'Identificação, dupla checagem e boas práticas no manuseio de medicamentos com risco aumentado de dano.\' },\n  { titulo:\'Armazenamento correto de termolábeis e cadeia fria\', publico:\'Enfermagem, Farmácia e Almoxarifado\', duracao:\'18 min\', desc:\'Faixas de temperatura, rotina de monitoramento e conduta em caso de desvio térmico.\' },\n  { titulo:\'Erros de medicação: identificação e prevenção\', publico:\'Toda equipe assistencial\', duracao:\'30 min\', desc:\'Os \"5 certos\" da administração de medicamentos e como notificar eventos adversos.\' },\n  { titulo:\'Antimicrobianos e stewardship hospitalar\', publico:\'Médicos e Farmácia Clínica\', duracao:\'40 min\', desc:\'Princípios do uso racional de antimicrobianos e papel da farmácia no programa institucional.\' },\n];\n\nconst MEDICAMENTOS_PADRONIZADOS = [\n  { nome:\'Dipirona sódica\', classe:\'Analgésico/Antitérmico\', apresentacao:\'500mg/mL — solução injetável\', status:\'padronizado\' },\n  { nome:\'Ceftriaxona sódica\', classe:\'Antimicrobiano\', apresentacao:\'1g — pó p/ solução injetável\', status:\'padronizado\' },\n  { nome:\'Enoxaparina sódica\', classe:\'Anticoagulante\', apresentacao:\'40mg/0,4mL — seringa preenchida\', status:\'padronizado\' },\n  { nome:\'Vancomicina (em desabastecimento)\', classe:\'Antimicrobiano\', apresentacao:\'500mg — pó p/ solução injetável\', status:\'alternativa\' },\n  { nome:\'Omeprazol\', classe:\'Inibidor de bomba de prótons\', apresentacao:\'40mg — pó p/ solução injetável\', status:\'padronizado\' },\n  { nome:\'Midazolam\', classe:\'Sedativo/hipnótico\', apresentacao:\'5mg/mL — solução injetável\', status:\'padronizado\' },\n];\n\nconst ATUALIZACOES_PADRONIZACAO = [\n  { tipo:\'Inclusão\', item:\'Sulfato de magnésio 10% — ampola 10mL\', data:\'24/06/2026\' },\n  { tipo:\'Exclusão\', item:\'Apresentação anterior de Ceftriaxona 250mg (descontinuada pelo fabricante)\', data:\'24/06/2026\' },\n];\n\nconst NOTAS_TECNICAS = [\n  { titulo:\'Nota técnica — manejo de alternativa terapêutica à Vancomicina\', data:\'21/06/2026\' },\n  { titulo:\'Nota técnica — uso de Sulfato de Magnésio em pré-eclâmpsia\', data:\'05/06/2026\' },\n];\n\nconst LASA_PARES = [\n  { a:\'Hidr<span class=\"hl\">ALA</span>zina\', b:\'Hidr<span class=\"hl\">OXI</span>zina\', nota:\'Anti-hipertensivo × anti-histamínico. Confirmar indicação clínica antes da dispensação.\' },\n  { a:\'Clona<span class=\"hl\">ZE</span>pam\', b:\'Clo<span class=\"hl\">BA</span>zam\', nota:\'Ambos anticonvulsivantes/benzodiazepínicos — checar dose e apresentação.\' },\n  { a:\'Insulina <span class=\"hl\">NPH</span>\', b:\'Insulina <span class=\"hl\">Regular</span>\', nota:\'Tempo de ação distinto. Sempre confirmar tipo antes da administração.\' },\n  { a:\'Do<span class=\"hl\">PA</span>mina\', b:\'Do<span class=\"hl\">BU</span>tamina\', nota:\'Aminas vasoativas com mecanismos diferentes — risco elevado em UTI.\' },\n];\n\nconst ALTA_VIGILANCIA = [\'Insulinas (todas as apresentações)\',\'Heparina e demais anticoagulantes\',\'Cloreto de Potássio concentrado\',\'Opioides injetáveis\',\'Quimioterápicos antineoplásicos\',\'Bloqueadores neuromusculares\',\'Soluções concentradas de eletrólitos\',\'Sedativos para sedação profunda\'];\n\nconst CHECAGEM_DUPLA = [\n  { titulo:\'Identificação do paciente\', texto:\'Confirmar nome completo e data de nascimento, conferindo com a pulseira de identificação.\' },\n  { titulo:\'Confirmação do medicamento\', texto:\'Verificar nome, concentração, apresentação e validade do item a ser administrado.\' },\n  { titulo:\'Checagem da prescrição\', texto:\'Confrontar dose, via e horário com a prescrição médica vigente.\' },\n  { titulo:\'Assinatura dos dois profissionais\', texto:\'Ambos os profissionais envolvidos na checagem assinam o registro antes da administração.\' },\n];\n\nconst FLUXOS = [\n  { titulo:\'Solicitação de medicamento não padronizado\', passos:[\n    {t:\'Abertura da solicitação\', d:\'Médico assistente registra a justificativa clínica no formulário eletrônico.\'},\n    {t:\'Triagem farmacêutica\', d:\'Farmácia avalia pertinência clínica e disponibilidade de alternativa padronizada.\'},\n    {t:\'Parecer e aquisição\', d:\'Em caso de aprovação, farmácia inicia processo de aquisição ou empréstimo entre unidades.\'},\n    {t:\'Liberação ao setor\', d:\'Medicamento é liberado e o solicitante é notificado pelo prazo definido em protocolo.\'},\n  ]},\n  { titulo:\'Fluxo de devolução de medicamentos\', passos:[\n    {t:\'Identificação do item\', d:\'Setor separa o medicamento não utilizado, íntegro e dentro da validade.\'},\n    {t:\'Registro da devolução\', d:\'Preenchimento do formulário de devolução com motivo e responsável.\'},\n    {t:\'Conferência farmacêutica\', d:\'Farmácia verifica condições de armazenamento e integridade da embalagem.\'},\n    {t:\'Retorno ao estoque ou descarte\', d:\'Item retorna ao estoque ativo ou é destinado a descarte conforme normas vigentes.\'},\n  ]},\n  { titulo:\'Perdas e ajustes de estoque\', passos:[\n    {t:\'Identificação da divergência\', d:\'Equipe identifica perda, quebra ou divergência no inventário.\'},\n    {t:\'Registro formal\', d:\'Abertura de ocorrência com descrição, quantidade e setor envolvido.\'},\n    {t:\'Análise da farmácia\', d:\'Avaliação da causa raiz e classificação (operacional, técnica ou administrativa).\'},\n    {t:\'Ajuste no sistema\', d:\'Correção do saldo de estoque e arquivamento da documentação de suporte.\'},\n  ]},\n  { titulo:\'Fluxo de emergência\', passos:[\n    {t:\'Acionamento\', d:\'Setor aciona a farmácia pelo ramal de emergência, informando o medicamento necessário.\'},\n    {t:\'Priorização imediata\', d:\'Farmacêutico interrompe atividade de rotina para atendimento prioritário.\'},\n    {t:\'Entrega expressa\', d:\'Medicamento é encaminhado ao setor por mensageiro dedicado ou retirada direta.\'},\n    {t:\'Registro retroativo\', d:\'Documentação formal da dispensação é completada em até 2 horas.\'},\n  ]},\n  { titulo:\'Atendimento a setores críticos\', passos:[\n    {t:\'Padronização específica\', d:\'UTI, centro cirúrgico e emergência possuem kits e padronização própria revisados semestralmente.\'},\n    {t:\'Reposição programada\', d:\'Farmácia realiza checagem e reposição de kits em horários fixos, sem necessidade de solicitação.\'},\n    {t:\'Canal direto\', d:\'Setores críticos possuem ramal direto com farmacêutico de plantão.\'},\n    {t:\'Auditoria periódica\', d:\'Farmácia realiza auditoria mensal de validade e integridade dos kits.\'},\n  ]},\n];\n\nconst KPIS = [\n  { num:\'98,2%\', label:\'Conformidade em auditorias de dispensação\', trend:\'+0,6 p.p. vs mês anterior\', trendType:\'up\' },\n  { num:\'312\', label:\'POPs vigentes na biblioteca\', trend:\'4 revisados este mês\', trendType:\'flat\' },\n  { num:\'47\', label:\'Treinamentos concluídos no mês\', trend:\'+12 vs mês anterior\', trendType:\'up\' },\n  { num:\'1\', label:\'Evento adverso grave notificado no mês\', trend:\'Em análise pela CCIH\', trendType:\'warn\' },\n];\n\n/* =====================================================================\n   ROTEAMENTO E RENDERIZAÇÃO\n   ===================================================================== */\nlet currentView = \'home\';\nlet popFiltro = { cat:\'todas\', q:\'\' };\nlet comFiltro = { cat:\'todas\' };\n\nfunction catTagClass(cat){\n  return {protocolo:\'tag-protocolo\', padronizacao:\'tag-padronizacao\', desabastecimento:\'tag-desabastecimento\', alerta:\'tag-alerta\', orientacao:\'tag-orientacao\'}[cat] || \'tag-orientacao\';\n}\n\nfunction renderNav(){\n  document.getElementById(\'nav\').innerHTML = NAV_ITEMS.map(item => `\n    <button class=\"nav-item ${item.id===currentView?\'active\':\'\'}\" data-view=\"${item.id}\">\n      ${ic(item.icon)}\n      <span>${item.label}</span>\n      ${item.badge ? `<span class=\"badge\">${item.badge()}</span>` : \'\'}\n    </button>\n  `).join(\'\');\n  document.querySelectorAll(\'.nav-item\').forEach(btn=>{\n    btn.addEventListener(\'click\', ()=>{ navigate(btn.dataset.view); closeMobileMenu(); });\n  });\n}\n\nfunction renderHome(){\n  return `\n    <div class=\"page-head\">\n      <div>\n        <span class=\"eyebrow\">Painel principal</span>\n        <h1>Bem-vindo ao portal da Farmácia Hospitalar</h1>\n        <p>Acesso rápido a comunicados, protocolos e indicadores da assistência farmacêutica do Hospital Santa Lúcia Bauru.</p>\n      </div>\n    </div>\n\n    <div class=\"hero-stamp\">\n      <div class=\"selo\"><span class=\"selo-texto\">Farmácia Hospitalar · Uso Seguro de Medicamentos</span></div>\n      <div class=\"hero-stamp-text\">\n        <span class=\"eyebrow\">Compromisso institucional</span>\n        <h1>Uso seguro e racional de medicamentos, em cada etapa da assistência.</h1>\n        <p>Este portal reúne os protocolos, comunicados e materiais de educação continuada da Farmácia Hospitalar para toda a equipe do hospital.</p>\n      </div>\n    </div>\n\n    <div class=\"grid grid-4 kpi-row\">\n      ${KPIS.map(k=>`\n        <div class=\"card kpi\">\n          <div class=\"kpi-num\">${k.num}</div>\n          <div class=\"kpi-label\">${k.label}</div>\n          <span class=\"kpi-trend trend-${k.trendType}\">${k.trend}</span>\n        </div>\n      `).join(\'\')}\n    </div>\n\n    <div class=\"dash-grid\">\n      <div class=\"dash-col\">\n        <div class=\"card\" style=\"padding:18px 18px 8px;\">\n          <div class=\"section-title\">${ic(\'megaphone\')} Comunicados recentes <span class=\"ver-tudo\" data-go=\"comunicados\">Ver todos</span></div>\n          ${COMUNICADOS.slice(0,4).map(c=>`\n            <div class=\"list-item\">\n              <div class=\"list-item-icon\">${ic(\'megaphone\')}</div>\n              <div class=\"list-item-body\">\n                <div class=\"list-item-title\">${c.titulo}</div>\n                <div class=\"list-item-meta\">\n                  <span class=\"tag ${catTagClass(c.cat)}\">${c.catLabel}</span>\n                  <span class=\"mono\">${c.data}</span>\n                </div>\n              </div>\n            </div>\n          `).join(\'\')}\n        </div>\n\n        <div class=\"card\" style=\"padding:18px 18px 8px; margin-top:20px;\">\n          <div class=\"section-title\">${ic(\'book\')} POPs mais acessados <span class=\"ver-tudo\" data-go=\"pops\">Ver biblioteca</span></div>\n          ${POPS.slice(0,4).map(p=>`\n            <div class=\"list-item\">\n              <div class=\"list-item-icon\">${ic(\'book\')}</div>\n              <div class=\"list-item-body\">\n                <div class=\"list-item-title\">${p.titulo}</div>\n                <div class=\"list-item-meta\"><span class=\"mono\">${p.codigo} · ${p.versao}</span><span>${p.catLabel}</span></div>\n              </div>\n            </div>\n          `).join(\'\')}\n        </div>\n      </div>\n\n      <div class=\"dash-col\">\n        <div class=\"card\" style=\"padding:18px;\">\n          <div class=\"section-title\">${ic(\'alert\')} Alertas de segurança medicamentosa</div>\n          <div class=\"alert-row crit\">\n            ${ic(\'alert\')}\n            <div><div class=\"alert-row-title\">Recolhimento de lote — Insulina Regular</div><div class=\"alert-row-text\">Conferir número de lote antes da administração. Ver comunicado completo.</div></div>\n          </div>\n          <div class=\"alert-row\">\n            ${ic(\'alert\')}\n            <div><div class=\"alert-row-title\">Desabastecimento — Vancomicina 500mg</div><div class=\"alert-row-text\">Estoque de segurança garante cobertura de 12 dias.</div></div>\n          </div>\n        </div>\n\n        <div class=\"card\" style=\"padding:18px 18px 8px; margin-top:20px;\">\n          <div class=\"section-title\">${ic(\'cap\')} Treinamentos em destaque <span class=\"ver-tudo\" data-go=\"treinamentos\">Ver todos</span></div>\n          ${TREINAMENTOS.slice(0,2).map(t=>`\n            <div class=\"list-item\">\n              <div class=\"list-item-icon\">${ic(\'cap\')}</div>\n              <div class=\"list-item-body\">\n                <div class=\"list-item-title\">${t.titulo}</div>\n                <div class=\"list-item-meta\"><span class=\"mono\">${t.duracao}</span><span>${t.publico}</span></div>\n              </div>\n            </div>\n          `).join(\'\')}\n        </div>\n\n        <div class=\"card\" style=\"padding:18px 18px 8px; margin-top:20px;\">\n          <div class=\"section-title\">${ic(\'pill\')} Padronização — atualizações</div>\n          ${ATUALIZACOES_PADRONIZACAO.map(a=>`\n            <div class=\"list-item\">\n              <div class=\"list-item-icon\">${ic(\'pill\')}</div>\n              <div class=\"list-item-body\">\n                <div class=\"list-item-title\">${a.tipo}: ${a.item}</div>\n                <div class=\"list-item-meta\"><span class=\"mono\">${a.data}</span></div>\n              </div>\n            </div>\n          `).join(\'\')}\n        </div>\n      </div>\n    </div>\n  `;\n}\n\nfunction renderComunicados(){\n  const cats = [{id:\'todas\',label:\'Todas\'},{id:\'protocolo\',label:\'Protocolo\'},{id:\'padronizacao\',label:\'Padronização\'},{id:\'desabastecimento\',label:\'Desabastecimento\'},{id:\'alerta\',label:\'Alerta sanitário\'},{id:\'orientacao\',label:\'Orientação\'}];\n  const lista = COMUNICADOS.filter(c=> comFiltro.cat===\'todas\' || c.cat===comFiltro.cat);\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Comunicação oficial</span><h1>Comunicados da Farmácia</h1><p>Publicações oficiais sobre protocolos, padronização, desabastecimentos e alertas sanitários.</p></div>\n    </div>\n    <div class=\"filter-row\">\n      ${cats.map(c=>`<button class=\"chip ${comFiltro.cat===c.id?\'active\':\'\'}\" data-comcat=\"${c.id}\">${c.label}</button>`).join(\'\')}\n    </div>\n    <div id=\"comList\">\n      ${lista.length? lista.map(c=>`\n        <div class=\"card com-card\" data-comid=\"${c.id}\">\n          <div class=\"com-card-top\">\n            <span class=\"tag ${catTagClass(c.cat)}\">${c.catLabel}</span>\n            <span class=\"com-card-date mono\">${c.data}</span>\n          </div>\n          <h3>${c.titulo}</h3>\n          <p>${c.resumo}</p>\n          <div class=\"com-card-foot\">\n            <button class=\"btn btn-ghost\" data-comid=\"${c.id}\">Ler comunicado completo →</button>\n            ${c.anexo? `<span class=\"anexo-link\">${ic(\'paperclip\')} ${c.anexo}</span>` : \'\'}\n          </div>\n        </div>\n      `).join(\'\') : `<div class=\"empty\">Nenhum comunicado nesta categoria.</div>`}\n    </div>\n  `;\n}\n\nfunction renderPops(){\n  const lista = POPS.filter(p=>{\n    const matchCat = popFiltro.cat===\'todas\' || p.cat===popFiltro.cat;\n    const q = popFiltro.q.trim().toLowerCase();\n    const matchQ = !q || p.titulo.toLowerCase().includes(q) || p.codigo.toLowerCase().includes(q);\n    return matchCat && matchQ;\n  });\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Documentação técnica</span><h1>Biblioteca de POPs e Protocolos</h1><p>Procedimentos Operacionais Padrão vigentes, organizados por categoria e com controle de versão.</p></div>\n    </div>\n    <div class=\"lib-toolbar\">\n      <div class=\"search\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n        <input id=\"popSearch\" placeholder=\"Buscar por título ou código…\" value=\"${popFiltro.q}\">\n      </div>\n    </div>\n    <div class=\"filter-row\">\n      ${POP_CATEGORIAS.map(c=>`<button class=\"chip ${popFiltro.cat===c.id?\'active\':\'\'}\" data-popcat=\"${c.id}\">${c.label}</button>`).join(\'\')}\n    </div>\n    <div id=\"popList\">\n      ${lista.length? lista.map(p=>`\n        <div class=\"card pop-card\">\n          <div class=\"pop-card-tab\"></div>\n          <div class=\"pop-card-body\">\n            <div class=\"pop-card-code mono\">${p.codigo}<span class=\"ver\">${p.versao}</span></div>\n            <div class=\"pop-card-main\">\n              <h3>${p.titulo}</h3>\n              <div class=\"pop-card-main-meta\">\n                <span class=\"tag tag-orientacao\">${p.catLabel}</span>\n                <span class=\"mono\">Atualizado em ${p.data}</span>\n              </div>\n            </div>\n            <div class=\"pop-card-actions\">\n              <button class=\"btn btn-primary\" onclick=\"alert(\'Download de exemplo — conecte este botão ao arquivo real do POP (PDF).\')\">${ic(\'download\')} PDF</button>\n            </div>\n          </div>\n        </div>\n      `).join(\'\') : `<div class=\"empty\">Nenhum POP encontrado para esta busca.</div>`}\n    </div>\n  `;\n}\n\nfunction renderTreinamentos(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Educação continuada</span><h1>Treinamentos da Farmácia Hospitalar</h1><p>Capacitações sobre uso seguro de medicamentos, com vídeo, material de apoio e avaliação.</p></div>\n    </div>\n    <div class=\"grid grid-2\">\n      ${TREINAMENTOS.map(t=>`\n        <div class=\"card train-card\">\n          <div class=\"train-thumb\">${ic(\'film\')}<span class=\"dur mono\">${t.duracao}</span></div>\n          <div class=\"train-body\">\n            <h3>${t.titulo}</h3>\n            <p>${t.desc}</p>\n            <div class=\"train-audience\">${ic(\'cap\')} Público-alvo: ${t.publico}</div>\n            <div class=\"train-actions\">\n              <button class=\"btn btn-primary\" onclick=\"alert(\'Player de exemplo — incorpore aqui o vídeo do YouTube privado ou Google Drive.\')\">${ic(\'film\')} Assistir</button>\n              <button class=\"btn\" onclick=\"alert(\'Material de apoio em PDF — anexe aqui o arquivo real.\')\">${ic(\'download\')} Material</button>\n              <button class=\"btn\" onclick=\"alert(\'Questionário de avaliação — conecte aqui o Google Forms do treinamento.\')\">${ic(\'check\')} Avaliação</button>\n            </div>\n          </div>\n        </div>\n      `).join(\'\')}\n    </div>\n  `;\n}\n\nfunction renderPadronizacao(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Padronização institucional</span><h1>Padronização de Medicamentos</h1><p>Lista vigente, atualizações recentes e notas técnicas da Comissão de Farmácia e Terapêutica.</p></div>\n    </div>\n    <div class=\"card\" style=\"margin-bottom:20px;\">\n      <div class=\"table-wrap\">\n        <table class=\"std-table\">\n          <thead><tr><th>Medicamento</th><th>Classe</th><th>Apresentação</th><th>Status</th></tr></thead>\n          <tbody>\n            ${MEDICAMENTOS_PADRONIZADOS.map(m=>`\n              <tr>\n                <td><strong>${m.nome}</strong></td>\n                <td>${m.classe}</td>\n                <td>${m.apresentacao}</td>\n                <td><span class=\"status-dot status-${m.status}\">${m.status===\'padronizado\'?\'Padronizado\':\'Alternativa em uso\'}</span></td>\n              </tr>\n            `).join(\'\')}\n          </tbody>\n        </table>\n      </div>\n    </div>\n    <div class=\"grid grid-2\">\n      <div class=\"card\" style=\"padding:18px;\">\n        <div class=\"section-title\">${ic(\'pill\')} Atualizações recentes</div>\n        ${ATUALIZACOES_PADRONIZACAO.map(a=>`\n          <div class=\"list-item\"><div class=\"list-item-icon\">${ic(\'pill\')}</div>\n            <div class=\"list-item-body\"><div class=\"list-item-title\">${a.tipo}</div><div class=\"list-item-meta\">${a.item}<br><span class=\"mono\">${a.data}</span></div></div>\n          </div>\n        `).join(\'\')}\n      </div>\n      <div class=\"card\" style=\"padding:18px;\">\n        <div class=\"section-title\">${ic(\'book\')} Notas técnicas farmacêuticas</div>\n        ${NOTAS_TECNICAS.map(n=>`\n          <div class=\"list-item\"><div class=\"list-item-icon\">${ic(\'book\')}</div>\n            <div class=\"list-item-body\"><div class=\"list-item-title\">${n.titulo}</div><div class=\"list-item-meta\"><span class=\"mono\">${n.data}</span></div></div>\n          </div>\n        `).join(\'\')}\n      </div>\n    </div>\n  `;\n}\n\nfunction renderSeguranca(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Segurança do paciente</span><h1>Segurança do Paciente — Farmácia</h1><p>Conteúdo crítico sobre medicamentos LASA, alta vigilância e prevenção de erros de medicação.</p></div>\n    </div>\n\n    <div class=\"section-title\">${ic(\'alert\')} Medicamentos com nome ou aparência semelhante (LASA)</div>\n    <div style=\"margin-bottom:26px;\">\n      ${LASA_PARES.map(l=>`\n        <div class=\"card lasa-pair\">\n          <span class=\"lasa-word\">${l.a}</span><span class=\"lasa-vs\">vs</span><span class=\"lasa-word\">${l.b}</span>\n          <span class=\"lasa-note\">${l.nota}</span>\n        </div>\n      `).join(\'\')}\n    </div>\n\n    <div class=\"grid grid-2\" style=\"margin-bottom:26px;\">\n      <div>\n        <div class=\"section-title\">${ic(\'shield\')} Medicamentos de alta vigilância</div>\n        <div class=\"vigilancia-grid\">\n          ${ALTA_VIGILANCIA.map(v=>`<div class=\"card vigilancia-item\">${ic(\'alert\')}<span>${v}</span></div>`).join(\'\')}\n        </div>\n      </div>\n      <div>\n        <div class=\"section-title\">${ic(\'check\')} Protocolo de dupla checagem</div>\n        <div class=\"card\" style=\"padding: 6px 20px;\">\n          <div class=\"check-steps\">\n            ${CHECAGEM_DUPLA.map((c,i)=>`\n              <div class=\"check-step\">\n                <div class=\"check-step-num\">${i+1}</div>\n                <div class=\"check-step-text\"><strong>${c.titulo}</strong><span>${c.texto}</span></div>\n              </div>\n            `).join(\'\')}\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\" style=\"padding:20px; display:flex; gap:16px; align-items:center; flex-wrap:wrap;\">\n      <div style=\"flex:1; min-width:220px;\">\n        <div class=\"section-title\" style=\"margin-bottom:6px;\">${ic(\'bell\')} Identificou um erro de medicação ou evento adverso?</div>\n        <p style=\"font-size:12.5px; color:var(--gray);\">A notificação é essencial para a melhoria contínua dos processos. Não é necessário identificar o profissional.</p>\n      </div>\n      <button class=\"btn btn-primary\" data-go=\"contato\">${ic(\'send\')} Notificar evento</button>\n    </div>\n  `;\n}\n\nfunction renderFluxos(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Processos operacionais</span><h1>Fluxos e Processos da Farmácia</h1><p>Etapas padronizadas para solicitações, devoluções, ajustes de estoque e atendimentos especiais.</p></div>\n    </div>\n    <div id=\"flowList\">\n      ${FLUXOS.map((f,i)=>`\n        <div class=\"card flow-acc ${i===0?\'open\':\'\'}\" data-flow=\"${i}\">\n          <button class=\"flow-acc-head\" data-flowtoggle=\"${i}\">\n            <span class=\"num mono\">0${i+1}</span>\n            <h3>${f.titulo}</h3>\n            ${ic(\'chev\')}\n          </button>\n          <div class=\"flow-acc-body\">\n            <div class=\"flow-steps\">\n              ${f.passos.map((p,j)=>`\n                <div class=\"flow-step\">\n                  <div class=\"flow-step-inner\">\n                    <div class=\"flow-step-num mono\">${j+1}</div>\n                    <div class=\"flow-step-title\">${p.t}</div>\n                    <div class=\"flow-step-text\">${p.d}</div>\n                  </div>\n                </div>\n                ${j<f.passos.length-1? `<div class=\"flow-arrow\">${ic(\'chev\')}</div>` : \'\'}\n              `).join(\'\')}\n            </div>\n          </div>\n        </div>\n      `).join(\'\')}\n    </div>\n  `;\n}\n\nfunction renderContato(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Canal direto</span><h1>Contato e Solicitações</h1><p>Solicite medicamentos, tire dúvidas técnicas ou notifique problemas diretamente à Farmácia Hospitalar.</p></div>\n    </div>\n    <div class=\"contact-grid\">\n      <div class=\"card form-card\">\n        <div class=\"confirm-box\" id=\"confirmBox\">\n          ${ic(\'check\')}\n          <div><strong>Solicitação registrada</strong><span>Este é um formulário de demonstração — conecte-o ao seu sistema real de chamados ou e-mail institucional.</span></div>\n        </div>\n        <form id=\"contactForm\">\n          <div class=\"field-row\">\n            <div class=\"field\"><label>Nome completo</label><input required placeholder=\"Seu nome\"></div>\n            <div class=\"field\"><label>Setor</label><input required placeholder=\"Ex.: UTI Adulto\"></div>\n          </div>\n          <div class=\"field\">\n            <label>Tipo de solicitação</label>\n            <select>\n              <option>Solicitação de medicamento não padronizado</option>\n              <option>Dúvida técnica</option>\n              <option>Sugestão</option>\n              <option>Notificação de problema / evento adverso</option>\n            </select>\n          </div>\n          <div class=\"field\"><label>Mensagem</label><textarea required placeholder=\"Descreva sua solicitação com o máximo de detalhes possível…\"></textarea></div>\n          <button class=\"btn btn-primary btn-block\" type=\"submit\">${ic(\'send\')} Enviar solicitação</button>\n        </form>\n      </div>\n      <div class=\"card\" style=\"padding:22px 24px;\">\n        <div class=\"section-title\" style=\"margin-bottom:16px;\">Canais diretos</div>\n        <div class=\"contact-info-item\">${ic(\'phone\')}<div><strong>Ramal da Farmácia Central</strong><span>Ramal 4521 — dias úteis, 7h às 19h</span></div></div>\n        <div class=\"contact-info-item\">${ic(\'mail\')}<div><strong>E-mail institucional</strong><span>farmacia.hospitalar@hospitalsantalucia.exemplo</span></div></div>\n        <div class=\"contact-info-item\">${ic(\'clock\')}<div><strong>Plantão farmacêutico</strong><span>24 horas, todos os dias, via ramal de urgência 4599</span></div></div>\n        <div class=\"contact-info-item\">${ic(\'pin\')}<div><strong>Localização</strong><span>Farmácia Central — Bloco A, térreo</span></div></div>\n      </div>\n    </div>\n  `;\n}\n\nconst RENDERERS = {\n  home: renderHome, comunicados: renderComunicados, pops: renderPops,\n  treinamentos: renderTreinamentos, padronizacao: renderPadronizacao,\n  seguranca: renderSeguranca, fluxos: renderFluxos, contato: renderContato,\n};\n\nfunction navigate(view){\n  if(!RENDERERS[view]) return;\n  currentView = view;\n  document.getElementById(\'content\').innerHTML = `<div class=\"view active\">${RENDERERS[view]()}</div>`;\n  renderNav();\n  bindViewEvents(view);\n  document.getElementById(\'content\').scrollTop = 0;\n  window.scrollTo(0,0);\n}\n\nfunction bindViewEvents(view){\n  document.querySelectorAll(\'[data-go]\').forEach(el=> el.addEventListener(\'click\', ()=> navigate(el.dataset.go)));\n\n  if(view===\'comunicados\'){\n    document.querySelectorAll(\'[data-comcat]\').forEach(el=> el.addEventListener(\'click\', ()=>{ comFiltro.cat = el.dataset.comcat; navigate(\'comunicados\'); }));\n    document.querySelectorAll(\'[data-comid]\').forEach(el=> el.addEventListener(\'click\', ()=> openComunicado(el.dataset.comid)));\n  }\n  if(view===\'pops\'){\n    document.querySelectorAll(\'[data-popcat]\').forEach(el=> el.addEventListener(\'click\', ()=>{ popFiltro.cat = el.dataset.popcat; navigate(\'pops\'); }));\n    const input = document.getElementById(\'popSearch\');\n    if(input){\n      input.addEventListener(\'input\', ()=>{\n        const pos = input.selectionStart;\n        popFiltro.q = input.value;\n        navigate(\'pops\');\n        const newInput = document.getElementById(\'popSearch\');\n        newInput.focus();\n        newInput.setSelectionRange(pos,pos);\n      });\n    }\n  }\n  if(view===\'fluxos\'){\n    document.querySelectorAll(\'[data-flowtoggle]\').forEach(el=>{\n      el.addEventListener(\'click\', ()=>{\n        const card = el.closest(\'.flow-acc\');\n        card.classList.toggle(\'open\');\n      });\n    });\n  }\n  if(view===\'contato\'){\n    const form = document.getElementById(\'contactForm\');\n    form.addEventListener(\'submit\', (e)=>{\n      e.preventDefault();\n      document.getElementById(\'confirmBox\').classList.add(\'show\');\n      form.reset();\n      document.getElementById(\'confirmBox\').scrollIntoView({behavior:\'smooth\', block:\'center\'});\n    });\n  }\n}\n\nfunction openComunicado(id){\n  const c = COMUNICADOS.find(x=>x.id===id);\n  if(!c) return;\n  document.getElementById(\'modalTitle\').textContent = c.titulo;\n  document.getElementById(\'modalBody\').innerHTML = `\n    <div class=\"com-card-top\" style=\"margin-bottom:14px;\">\n      <span class=\"tag ${catTagClass(c.cat)}\">${c.catLabel}</span>\n      <span class=\"com-card-date mono\">${c.data}</span>\n    </div>\n    <div class=\"com-detail-body\">${c.corpo.split(\'\\n\\n\').map(p=>`<p>${p}</p>`).join(\'\')}</div>\n    ${c.anexo? `<div style=\"margin-top:16px;\"><span class=\"anexo-link\">${ic(\'paperclip\')} ${c.anexo}</span></div>` : \'\'}\n  `;\n  document.getElementById(\'modalScrim\').classList.add(\'show\');\n}\n\n/* =====================================================================\n   INTERAÇÕES GLOBAIS — menu mobile, busca global, modal\n   ===================================================================== */\nfunction openMobileMenu(){ document.getElementById(\'sidebar\').classList.add(\'open\'); document.getElementById(\'sidebarScrim\').classList.add(\'show\'); }\nfunction closeMobileMenu(){ document.getElementById(\'sidebar\').classList.remove(\'open\'); document.getElementById(\'sidebarScrim\').classList.remove(\'show\'); }\ndocument.getElementById(\'menuBtn\').addEventListener(\'click\', openMobileMenu);\ndocument.getElementById(\'sidebarScrim\').addEventListener(\'click\', closeMobileMenu);\n\ndocument.getElementById(\'modalClose\').addEventListener(\'click\', ()=> document.getElementById(\'modalScrim\').classList.remove(\'show\'));\ndocument.getElementById(\'modalScrim\').addEventListener(\'click\', (e)=>{ if(e.target.id===\'modalScrim\') document.getElementById(\'modalScrim\').classList.remove(\'show\'); });\ndocument.addEventListener(\'keydown\', (e)=>{ if(e.key===\'Escape\') document.getElementById(\'modalScrim\').classList.remove(\'show\'); });\n\ndocument.getElementById(\'globalSearch\').addEventListener(\'keydown\', (e)=>{\n  if(e.key===\'Enter\'){\n    const q = e.target.value.trim();\n    if(!q) return;\n    popFiltro = { cat:\'todas\', q:q };\n    navigate(\'pops\');\n  }\n});\n\n/* inicialização */\nrenderNav();\nnavigate(\'home\');\n</script>\n</body>\n</html>\n', '', '', 'draft', 'closed', 'closed', '', '', '', '', '2026-09-09 13:11:34', '2026-09-09 16:11:34', '', 0, 'http://localhost/faramcia_SL/wordpress/?page_id=6', 0, 'page', '', 0);
INSERT INTO `wp_userposts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(7, 1, '2026-09-09 13:09:43', '2026-09-09 16:09:43', '{\"version\": 3, \"isGlobalStylesUserThemeJSON\": true }', 'Custom Styles', '', 'publish', 'closed', 'closed', '', 'wp-global-styles-twentytwentyfour', '', '', '2026-09-09 13:09:43', '2026-09-09 16:09:43', '', 0, 'http://localhost/faramcia_SL/wordpress/index.php/2026/09/09/wp-global-styles-twentytwentyfour/', 0, 'wp_global_styles', '', 0);
INSERT INTO `wp_userposts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(8, 1, '2026-09-09 13:11:34', '2026-09-09 16:11:34', '<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Farmácia Hospitalar · Hospital Santa Lúcia Bauru</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Serif:wght@400;500;600;700&family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n\n/* ===================================================================\n   TOKENS — Identidade visual do Hospital Santa Lúcia Bauru\n   =================================================================== */\n:root{\n  /* paleta institucional (fixa pelo briefing) */\n  --red: #A80F14;\n  --red-deep: #7A0B0F;\n  --red-tint: #FBEAEA;\n  --gray: #666666;\n  --white: #FFFFFF;\n  --gray-light: #F5F5F5;\n\n  /* derivados de apoio — tons de \"papel\" e tinta, não decorativos */\n  --paper: #FBFAF8;\n  --ink: #262321;\n  --line: #E2DDD7;\n  --line-soft: #EEEAE5;\n\n  /* cores funcionais — usadas só para status/segurança, nunca decoração */\n  --amber: #92600A;\n  --amber-bg: #FBF1DF;\n  --green: #2E6B40;\n  --green-bg: #E9F2EA;\n\n  /* tipografia */\n  --f-display: \"IBM Plex Serif\", Georgia, serif;\n  --f-body: \"IBM Plex Sans\", -apple-system, Segoe UI, sans-serif;\n  --f-mono: \"IBM Plex Mono\", \"SFMono-Regular\", monospace;\n\n  --radius: 3px;\n  --shadow-card: 0 1px 2px rgba(38,35,33,0.06), 0 1px 1px rgba(38,35,33,0.04);\n  --shadow-pop: 0 8px 24px rgba(38,35,33,0.12);\n\n  --sidebar-w: 248px;\n}\n\n*{ box-sizing: border-box; }\nhtml{ scroll-behavior: smooth; }\nbody{\n  margin:0;\n  font-family: var(--f-body);\n  color: var(--ink);\n  background: var(--gray-light);\n  -webkit-font-smoothing: antialiased;\n}\nh1,h2,h3,h4{ font-family: var(--f-display); margin:0; line-height:1.2; font-weight:600; }\np{ margin:0; }\na{ color: var(--red); text-decoration: none; }\nbutton{ font-family: var(--f-body); cursor:pointer; }\n:focus-visible{ outline: 2px solid var(--red); outline-offset: 2px; }\n.mono{ font-family: var(--f-mono); }\n\n@media (prefers-reduced-motion: reduce){\n  *{ animation-duration: 0.001ms !important; transition-duration: 0.001ms !important; scroll-behavior:auto !important; }\n}\n\n/* ===================================================================\n   SELO — elemento de assinatura visual do portal\n   Inspirado no carimbo oficial de validação de documentos hospitalares.\n   =================================================================== */\n.selo{\n  --size: 92px;\n  width: var(--size); height: var(--size);\n  border-radius: 50%;\n  border: 2px solid currentColor;\n  display:flex; align-items:center; justify-content:center;\n  position: relative;\n  transform: rotate(-9deg);\n  flex-shrink:0;\n  color: var(--red);\n}\n.selo::before{\n  content:\"\";\n  position:absolute; inset:6px;\n  border: 1px dashed currentColor;\n  border-radius:50%;\n  opacity:0.55;\n}\n.selo-texto{\n  font-family: var(--f-mono);\n  font-size: 8.5px;\n  font-weight:600;\n  letter-spacing: 0.5px;\n  text-align:center;\n  text-transform: uppercase;\n  line-height:1.25;\n  padding: 0 10px;\n}\n.selo.selo-sm{ --size: 44px; }\n.selo.selo-sm .selo-texto{ font-size: 5.6px; padding:0 5px; }\n.selo.selo-ghost{ color: var(--gray); opacity:0.65; }\n\n/* ===================================================================\n   LAYOUT GERAL\n   =================================================================== */\n.app{\n  display:flex;\n  min-height:100vh;\n}\n\n/* ---------- SIDEBAR ---------- */\n.sidebar{\n  width: var(--sidebar-w);\n  flex-shrink:0;\n  background: var(--ink);\n  color: var(--white);\n  display:flex;\n  flex-direction:column;\n  position: fixed;\n  top:0; left:0; bottom:0;\n  z-index: 40;\n  transition: transform .25s ease;\n}\n.sidebar-brand{\n  padding: 22px 20px 18px;\n  border-bottom: 1px solid rgba(255,255,255,0.12);\n  display:flex; align-items:center; gap:12px;\n}\n.sidebar-brand .selo{ color: var(--white); }\n.sidebar-brand-text{ font-family: var(--f-display); line-height:1.25; }\n.sidebar-brand-text strong{ display:block; font-size:14.5px; font-weight:600; }\n.sidebar-brand-text span{ display:block; font-size:11px; color: rgba(255,255,255,0.6); font-family: var(--f-body); margin-top:2px; }\n\n.nav{ flex:1; padding: 10px 12px; display:flex; flex-direction:column; gap:2px; overflow-y:auto; }\n.nav-item{\n  display:flex; align-items:center; gap:11px;\n  padding: 10px 12px;\n  border-radius: var(--radius);\n  color: rgba(255,255,255,0.72);\n  font-size: 13.5px;\n  font-weight:500;\n  background:none; border:none; text-align:left; width:100%;\n  transition: background .15s, color .15s;\n}\n.nav-item svg{ width:17px; height:17px; flex-shrink:0; opacity:0.9; }\n.nav-item:hover{ background: rgba(255,255,255,0.07); color: var(--white); }\n.nav-item.active{ background: var(--red); color: var(--white); }\n.nav-item .badge{\n  margin-left:auto;\n  font-family: var(--f-mono);\n  font-size: 10px;\n  background: rgba(255,255,255,0.14);\n  padding: 1px 6px;\n  border-radius: 10px;\n}\n.nav-item.active .badge{ background: rgba(255,255,255,0.25); }\n\n.sidebar-foot{\n  padding: 14px 20px 18px;\n  border-top: 1px solid rgba(255,255,255,0.12);\n  font-size: 11px;\n  color: rgba(255,255,255,0.5);\n  line-height:1.6;\n}\n\n/* ---------- TOPBAR (mobile) ---------- */\n.topbar{\n  display:none;\n  position: sticky; top:0; z-index:30;\n  background: var(--ink); color:var(--white);\n  align-items:center; gap:12px;\n  padding: 13px 16px;\n}\n.topbar button{\n  background:none; border:none; color:var(--white);\n  width:32px;height:32px; display:flex; align-items:center; justify-content:center;\n}\n.topbar .selo{ --size:32px; color:var(--white); }\n.topbar .selo .selo-texto{ font-size:4px; }\n.topbar-title{ font-family: var(--f-display); font-size:14px; font-weight:600; }\n\n.sidebar-scrim{ display:none; }\n\n/* ---------- MAIN ---------- */\n.main{\n  margin-left: var(--sidebar-w);\n  flex:1;\n  min-width:0;\n  display:flex; flex-direction:column;\n}\n.topstrip{\n  background: var(--white);\n  border-bottom: 1px solid var(--line);\n  padding: 16px 36px;\n  display:flex; align-items:center; gap:18px;\n  position: sticky; top:0; z-index:20;\n}\n.search{\n  flex:1; max-width: 480px;\n  display:flex; align-items:center; gap:9px;\n  background: var(--gray-light);\n  border:1px solid var(--line);\n  border-radius: var(--radius);\n  padding: 9px 13px;\n}\n.search svg{ width:15px; height:15px; color: var(--gray); flex-shrink:0; }\n.search input{\n  border:none; background:none; outline:none; width:100%;\n  font-size:13.5px; font-family:var(--f-body); color:var(--ink);\n}\n.topstrip-meta{\n  margin-left:auto;\n  display:flex; align-items:center; gap:16px;\n  font-size:12.5px; color:var(--gray);\n}\n.pill-status{\n  display:flex; align-items:center; gap:6px;\n  font-family: var(--f-mono); font-size:11.5px;\n  color: var(--green);\n  background: var(--green-bg);\n  padding: 5px 10px; border-radius: 20px;\n}\n.pill-status::before{ content:\"\"; width:6px;height:6px;border-radius:50%; background:currentColor; }\n\n.content{\n  flex:1;\n  padding: 32px 36px 64px;\n  max-width: 1180px;\n}\n\n.view{ display:none; animation: fadein .35s ease; }\n.view.active{ display:block; }\n@keyframes fadein{ from{opacity:0; transform:translateY(4px);} to{opacity:1; transform:translateY(0);} }\n\n.page-head{\n  display:flex; align-items:flex-end; justify-content:space-between; gap:20px;\n  margin-bottom: 28px;\n  padding-bottom: 18px;\n  border-bottom: 1px solid var(--line);\n}\n.page-head .eyebrow{\n  font-family: var(--f-mono); font-size:11px; letter-spacing:1px;\n  color: var(--red); text-transform:uppercase; margin-bottom:6px; display:block;\n}\n.page-head h1{ font-size: 26px; }\n.page-head p{ color: var(--gray); font-size: 13.5px; margin-top:6px; max-width:560px; }\n\n/* ===================================================================\n   COMPONENTES REUTILIZÁVEIS\n   =================================================================== */\n.card{\n  background: var(--white);\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  box-shadow: var(--shadow-card);\n}\n.grid{ display:grid; gap:18px; }\n.grid-2{ grid-template-columns: repeat(2,1fr); }\n.grid-3{ grid-template-columns: repeat(3,1fr); }\n.grid-4{ grid-template-columns: repeat(4,1fr); }\n\n.section-title{\n  display:flex; align-items:center; gap:9px;\n  font-size: 14px; font-weight:600; font-family: var(--f-display);\n  margin-bottom:14px;\n}\n.section-title svg{ width:16px;height:16px; color:var(--red); }\n.section-title .ver-tudo{\n  margin-left:auto; font-family:var(--f-body); font-size:12px; font-weight:500; color:var(--red);\n}\n\n.tag{\n  display:inline-flex; align-items:center; gap:5px;\n  font-size: 10.5px; font-weight:600; text-transform:uppercase; letter-spacing:.4px;\n  padding: 3px 8px; border-radius: 20px;\n  font-family: var(--f-body);\n}\n.tag-protocolo{ background:var(--red-tint); color:var(--red-deep); }\n.tag-padronizacao{ background:var(--green-bg); color:var(--green); }\n.tag-desabastecimento{ background:var(--amber-bg); color:var(--amber); }\n.tag-alerta{ background:#2A2A2A; color:#fff; }\n.tag-orientacao{ background:var(--gray-light); color:var(--gray); border:1px solid var(--line); }\n\n.btn{\n  display:inline-flex; align-items:center; gap:7px;\n  font-size:12.5px; font-weight:600;\n  padding: 8px 14px; border-radius: var(--radius);\n  border: 1px solid var(--line);\n  background: var(--white); color: var(--ink);\n  transition: border-color .15s, background .15s;\n}\n.btn svg{ width:13px;height:13px; }\n.btn:hover{ border-color: var(--gray); }\n.btn-primary{ background: var(--red); border-color:var(--red); color:var(--white); }\n.btn-primary:hover{ background: var(--red-deep); border-color:var(--red-deep); }\n.btn-block{ width:100%; justify-content:center; }\n.btn-ghost{ border-color:transparent; padding-left:4px; padding-right:4px; }\n\n.empty{\n  text-align:center; padding: 38px 20px; color: var(--gray); font-size:13px;\n}\n\n/* ===================================================================\n   DASHBOARD\n   =================================================================== */\n.hero-stamp{\n  display:flex; align-items:center; gap:22px;\n  background: var(--ink);\n  color: var(--white);\n  border-radius: var(--radius);\n  padding: 26px 30px;\n  margin-bottom: 26px;\n  position:relative;\n  overflow:hidden;\n}\n.hero-stamp::after{\n  content:\"\";\n  position:absolute; right:-40px; top:-60px;\n  width:220px; height:220px;\n  border:1px dashed rgba(255,255,255,0.08);\n  border-radius:50%;\n}\n.hero-stamp .selo{ color:var(--white); --size:78px; }\n.hero-stamp-text .eyebrow{ font-family:var(--f-mono); font-size:11px; letter-spacing:1px; color:#E7A6A8; text-transform:uppercase; }\n.hero-stamp-text h1{ font-size:21px; margin-top:6px; }\n.hero-stamp-text p{ font-size:13px; color:rgba(255,255,255,0.68); margin-top:7px; max-width:520px; }\n\n.kpi-row{ margin-bottom:26px; }\n.kpi{ padding: 16px 18px; }\n.kpi .kpi-num{ font-family:var(--f-display); font-size:25px; font-weight:600; }\n.kpi .kpi-label{ font-size:11.5px; color:var(--gray); margin-top:4px; line-height:1.4; }\n.kpi .kpi-trend{ font-family:var(--f-mono); font-size:10.5px; margin-top:8px; display:inline-block; padding:2px 7px; border-radius:10px; }\n.trend-up{ background:var(--green-bg); color:var(--green); }\n.trend-flat{ background:var(--gray-light); color:var(--gray); }\n.trend-warn{ background:var(--amber-bg); color:var(--amber); }\n\n.dash-grid{ display:grid; grid-template-columns: 1.3fr 1fr; gap:20px; margin-bottom:20px; }\n.dash-col{ display:flex; flex-direction:column; gap:20px; }\n\n.list-item{\n  display:flex; gap:13px; padding: 13px 16px;\n  border-bottom: 1px solid var(--line-soft);\n}\n.list-item:last-child{ border-bottom:none; }\n.list-item-icon{\n  width:30px;height:30px; border-radius:50%; flex-shrink:0;\n  display:flex; align-items:center; justify-content:center;\n  background: var(--red-tint); color:var(--red);\n}\n.list-item-icon svg{ width:14px;height:14px; }\n.list-item-body{ flex:1; min-width:0; }\n.list-item-title{ font-size:13px; font-weight:600; line-height:1.35; }\n.list-item-meta{ font-size:11px; color:var(--gray); margin-top:4px; display:flex; gap:8px; align-items:center; flex-wrap:wrap; }\n\n.alert-row{\n  display:flex; gap:12px; align-items:flex-start;\n  padding: 13px 16px;\n  border-left: 3px solid var(--amber);\n  background: var(--amber-bg);\n  border-radius: 0 var(--radius) var(--radius) 0;\n  margin-bottom:10px;\n}\n.alert-row.crit{ border-left-color: var(--red); background: var(--red-tint); }\n.alert-row svg{ width:16px;height:16px; flex-shrink:0; margin-top:1px; color:var(--amber); }\n.alert-row.crit svg{ color:var(--red); }\n.alert-row-title{ font-size:12.5px; font-weight:600; }\n.alert-row-text{ font-size:11.5px; color:var(--gray); margin-top:3px; line-height:1.45; }\n\n/* ===================================================================\n   COMUNICADOS\n   =================================================================== */\n.filter-row{ display:flex; gap:8px; margin-bottom:20px; flex-wrap:wrap; align-items:center; }\n.chip{\n  font-size:12px; font-weight:500; padding:7px 13px;\n  border-radius:20px; border:1px solid var(--line); background:var(--white); color:var(--gray);\n}\n.chip.active{ background: var(--ink); border-color:var(--ink); color:var(--white); }\n\n.com-card{ padding: 18px 20px; margin-bottom:14px; cursor:pointer; }\n.com-card-top{ display:flex; align-items:center; gap:10px; margin-bottom:8px; flex-wrap:wrap; }\n.com-card-date{ font-family:var(--f-mono); font-size:11px; color:var(--gray); }\n.com-card h3{ font-size:15px; margin-bottom:6px; }\n.com-card p{ font-size:13px; color:var(--gray); line-height:1.55; }\n.com-card-foot{ margin-top:12px; display:flex; align-items:center; gap:14px; }\n.anexo-link{ display:flex; align-items:center; gap:6px; font-size:12px; font-weight:600; color:var(--red); }\n.anexo-link svg{ width:13px;height:13px; }\n\n.com-detail-body{ font-size:13.5px; line-height:1.7; color:var(--ink); }\n.com-detail-body p{ margin-bottom:12px; }\n\n/* ===================================================================\n   POPs — biblioteca em formato de \"ficha de documento\"\n   =================================================================== */\n.lib-toolbar{ display:flex; gap:10px; margin-bottom:18px; flex-wrap:wrap; }\n.lib-toolbar .search{ max-width:340px; }\n\n.pop-card{\n  display:flex; gap:0; overflow:hidden; margin-bottom:12px;\n}\n.pop-card-tab{\n  width:6px; background: var(--red); flex-shrink:0;\n}\n.pop-card-body{ padding:16px 18px; flex:1; display:flex; gap:16px; align-items:flex-start; }\n.pop-card-code{\n  font-family:var(--f-mono); font-size:12px; color:var(--gray);\n  background:var(--gray-light); padding:8px 10px; border-radius:var(--radius);\n  text-align:center; flex-shrink:0; min-width:108px;\n}\n.pop-card-code .ver{ display:block; margin-top:4px; font-weight:600; color:var(--red); }\n.pop-card-main{ flex:1; min-width:0; }\n.pop-card-main h3{ font-size:14.5px; margin-bottom:5px; }\n.pop-card-main-meta{ font-size:11.5px; color:var(--gray); display:flex; gap:12px; flex-wrap:wrap; margin-top:6px; }\n.pop-card-actions{ display:flex; gap:8px; flex-shrink:0; align-self:center; }\n\n/* ===================================================================\n   TREINAMENTOS\n   =================================================================== */\n.train-card{ overflow:hidden; }\n.train-thumb{\n  height: 108px;\n  background: linear-gradient(135deg, var(--ink), #3a3431);\n  display:flex; align-items:center; justify-content:center;\n  position:relative;\n}\n.train-thumb svg{ width:30px; height:30px; color: rgba(255,255,255,0.85); }\n.train-thumb .dur{\n  position:absolute; bottom:8px; right:10px;\n  font-family:var(--f-mono); font-size:10.5px; color:#fff;\n  background: rgba(0,0,0,0.45); padding:2px 7px; border-radius:10px;\n}\n.train-body{ padding:16px 18px; }\n.train-body h3{ font-size:14px; margin-bottom:7px; }\n.train-body p{ font-size:12.5px; color:var(--gray); line-height:1.55; margin-bottom:12px; }\n.train-audience{ font-size:11px; color:var(--gray); margin-bottom:14px; display:flex; gap:6px; align-items:center; }\n.train-actions{ display:flex; gap:8px; flex-wrap:wrap; }\n.train-actions .btn{ flex:1; justify-content:center; }\n\n/* ===================================================================\n   PADRONIZAÇÃO\n   =================================================================== */\n.table-wrap{ overflow-x:auto; }\ntable.std-table{ width:100%; border-collapse:collapse; font-size:13px; }\ntable.std-table th{\n  text-align:left; font-size:11px; text-transform:uppercase; letter-spacing:.4px;\n  color:var(--gray); padding:11px 16px; border-bottom:1px solid var(--line); font-weight:600;\n}\ntable.std-table td{ padding:13px 16px; border-bottom:1px solid var(--line-soft); }\ntable.std-table tr:last-child td{ border-bottom:none; }\n.status-dot{ display:inline-flex; align-items:center; gap:6px; font-size:12px; font-weight:600; }\n.status-dot::before{ content:\"\"; width:7px;height:7px;border-radius:50%; }\n.status-padronizado::before{ background:var(--green); }\n.status-padronizado{ color:var(--green); }\n.status-alternativa::before{ background:var(--amber); }\n.status-alternativa{ color:var(--amber); }\n\n/* ===================================================================\n   SEGURANÇA DO PACIENTE\n   =================================================================== */\n.lasa-pair{\n  display:flex; align-items:center; gap:14px; padding:15px 18px; margin-bottom:10px;\n}\n.lasa-word{ font-family:var(--f-display); font-weight:700; font-size:16px; }\n.lasa-word .hl{ background: #FCE4A6; padding:0 2px; border-radius:2px; }\n.lasa-vs{ font-family:var(--f-mono); font-size:11px; color:var(--gray); }\n.lasa-note{ margin-left:auto; font-size:11.5px; color:var(--gray); max-width:280px; text-align:right; }\n\n.vigilancia-grid{ display:grid; grid-template-columns:repeat(2,1fr); gap:10px; }\n.vigilancia-item{\n  display:flex; align-items:center; gap:10px; padding:13px 15px;\n  border-left:3px solid var(--red);\n}\n.vigilancia-item svg{ width:16px;height:16px; color:var(--red); flex-shrink:0; }\n.vigilancia-item span{ font-size:13px; font-weight:600; }\n\n.check-steps{ display:flex; flex-direction:column; gap:0; }\n.check-step{ display:flex; gap:14px; padding:14px 0; border-bottom:1px solid var(--line-soft); }\n.check-step:last-child{ border-bottom:none; }\n.check-step-num{\n  font-family:var(--f-mono); font-weight:600; font-size:12px;\n  width:26px; height:26px; border-radius:50%; background:var(--ink); color:#fff;\n  display:flex; align-items:center; justify-content:center; flex-shrink:0;\n}\n.check-step-text strong{ display:block; font-size:13px; margin-bottom:2px; }\n.check-step-text span{ font-size:12px; color:var(--gray); }\n\n/* ===================================================================\n   FLUXOS — diagramas em sequência (numerados, pois SÃO sequências reais)\n   =================================================================== */\n.flow-acc{ margin-bottom:12px; }\n.flow-acc-head{\n  display:flex; align-items:center; gap:13px; padding:16px 20px;\n  width:100%; background:none; border:none; text-align:left;\n}\n.flow-acc-head .num{ font-family:var(--f-mono); font-size:12px; color:var(--gray); }\n.flow-acc-head h3{ font-size:14.5px; flex:1; }\n.flow-acc-head svg{ width:15px;height:15px; color:var(--gray); transition:transform .2s; flex-shrink:0; }\n.flow-acc.open .flow-acc-head svg{ transform: rotate(180deg); }\n.flow-acc-body{ display:none; padding: 0 22px 20px 22px; }\n.flow-acc.open .flow-acc-body{ display:block; }\n\n.flow-steps{ display:flex; gap:0; overflow-x:auto; padding-top:6px; padding-bottom:8px; }\n.flow-step{ display:flex; align-items:flex-start; flex-shrink:0; min-width:168px; }\n.flow-step-inner{ padding-right:18px; }\n.flow-step-num{\n  font-family:var(--f-mono); font-size:11px; color:var(--white); background:var(--red);\n  width:22px; height:22px; border-radius:50%; display:flex; align-items:center; justify-content:center; margin-bottom:8px;\n}\n.flow-step-title{ font-size:12.5px; font-weight:600; line-height:1.4; }\n.flow-step-text{ font-size:11.5px; color:var(--gray); margin-top:4px; line-height:1.45; }\n.flow-arrow{ color:var(--line); margin: 0 4px; padding-top:5px; flex-shrink:0; }\n.flow-arrow svg{ width:16px;height:16px; }\n\n/* ===================================================================\n   CONTATO\n   =================================================================== */\n.contact-grid{ display:grid; grid-template-columns: 1.4fr 1fr; gap:22px; }\n.form-card{ padding:24px; }\n.field{ margin-bottom:16px; }\n.field label{ display:block; font-size:12px; font-weight:600; margin-bottom:6px; }\n.field input, .field select, .field textarea{\n  width:100%; padding:10px 12px; border:1px solid var(--line); border-radius:var(--radius);\n  font-family:var(--f-body); font-size:13px; background:var(--white); color:var(--ink);\n}\n.field textarea{ resize:vertical; min-height:90px; }\n.field input:focus, .field select:focus, .field textarea:focus{ outline:2px solid var(--red); outline-offset:0; border-color:var(--red); }\n.field-row{ display:grid; grid-template-columns:1fr 1fr; gap:14px; }\n\n.contact-info-item{ display:flex; gap:12px; padding:15px 0; border-bottom:1px solid var(--line-soft); }\n.contact-info-item:last-child{ border-bottom:none; }\n.contact-info-item svg{ width:16px;height:16px; color:var(--red); flex-shrink:0; margin-top:2px; }\n.contact-info-item strong{ display:block; font-size:12.5px; margin-bottom:2px; }\n.contact-info-item span{ font-size:12px; color:var(--gray); line-height:1.5; }\n\n.confirm-box{\n  display:none; align-items:flex-start; gap:12px;\n  background:var(--green-bg); border-left:3px solid var(--green);\n  padding:14px 16px; border-radius:0 var(--radius) var(--radius) 0; margin-bottom:16px;\n}\n.confirm-box.show{ display:flex; }\n.confirm-box svg{ width:17px;height:17px; color:var(--green); flex-shrink:0; margin-top:1px; }\n.confirm-box strong{ font-size:13px; display:block; }\n.confirm-box span{ font-size:12px; color:var(--gray); }\n\n/* ===================================================================\n   MODAL (detalhe de comunicado)\n   =================================================================== */\n.modal-scrim{\n  position:fixed; inset:0; background:rgba(38,35,33,0.55); z-index:60;\n  display:none; align-items:center; justify-content:center; padding:24px;\n}\n.modal-scrim.show{ display:flex; }\n.modal-box{\n  background:var(--white); border-radius:var(--radius); max-width:560px; width:100%;\n  max-height:85vh; overflow-y:auto; box-shadow: var(--shadow-pop);\n}\n.modal-head{ padding:22px 24px 16px; border-bottom:1px solid var(--line); display:flex; gap:16px; align-items:flex-start; }\n.modal-head h2{ font-size:17px; flex:1; }\n.modal-close{ background:none; border:none; color:var(--gray); width:28px; height:28px; flex-shrink:0; }\n.modal-close svg{ width:18px;height:18px; }\n.modal-body{ padding:20px 24px 26px; }\n\n/* ===================================================================\n   RESPONSIVO\n   =================================================================== */\n@media (max-width: 980px){\n  .grid-4{ grid-template-columns: repeat(2,1fr); }\n  .grid-3{ grid-template-columns: repeat(2,1fr); }\n  .dash-grid{ grid-template-columns: 1fr; }\n  .contact-grid{ grid-template-columns: 1fr; }\n}\n\n@media (max-width: 760px){\n  .sidebar{ transform: translateX(-100%); width: 270px; }\n  .sidebar.open{ transform: translateX(0); box-shadow: var(--shadow-pop); }\n  .main{ margin-left:0; }\n  .topbar{ display:flex; }\n  .topstrip{ padding:14px 18px; }\n  .topstrip-meta .pill-status span{ display:none; }\n  .content{ padding: 22px 18px 50px; }\n  .grid-2, .grid-3, .grid-4{ grid-template-columns: 1fr; }\n  .vigilancia-grid{ grid-template-columns:1fr; }\n  .field-row{ grid-template-columns:1fr; }\n  .hero-stamp{ flex-direction:column; align-items:flex-start; text-align:left; }\n  .pop-card-body{ flex-direction:column; gap:12px; }\n  .pop-card-actions{ align-self:flex-start; }\n  .sidebar-scrim.show{\n    display:block; position:fixed; inset:0; background:rgba(0,0,0,0.4); z-index:35;\n  }\n  .page-head{ flex-direction:column; align-items:flex-start; }\n}\n</style>\n</head>\n<body>\n\n<div class=\"app\">\n\n  <!-- ============================ SIDEBAR ============================ -->\n  <aside class=\"sidebar\" id=\"sidebar\">\n    <div class=\"sidebar-brand\">\n      <div class=\"selo selo-sm\"><span class=\"selo-texto\">Farmácia · Uso Seguro</span></div>\n      <div class=\"sidebar-brand-text\">\n        <strong>Farmácia Hospitalar</strong>\n        <span>Hospital Santa Lúcia Bauru</span>\n      </div>\n    </div>\n    <nav class=\"nav\" id=\"nav\"></nav>\n    <div class=\"sidebar-foot\">\n      Portal de uso interno.<br>Conteúdo de exemplo — substitua pelos dados oficiais da unidade.\n    </div>\n  </aside>\n  <div class=\"sidebar-scrim\" id=\"sidebarScrim\"></div>\n\n  <div class=\"main\">\n    <!-- ============================ TOPBAR (mobile) ============================ -->\n    <div class=\"topbar\">\n      <button id=\"menuBtn\" aria-label=\"Abrir menu\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M3 6h18M3 12h18M3 18h18\"/></svg>\n      </button>\n      <div class=\"selo\"><span class=\"selo-texto\">Farmácia</span></div>\n      <span class=\"topbar-title\">Farmácia Hospitalar</span>\n    </div>\n\n    <!-- ============================ TOPSTRIP ============================ -->\n    <div class=\"topstrip\">\n      <div class=\"search\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n        <input id=\"globalSearch\" placeholder=\"Buscar POPs, comunicados, medicamentos…\" autocomplete=\"off\">\n      </div>\n      <div class=\"topstrip-meta\">\n        <span class=\"pill-status\"><span>Sistemas operacionais</span></span>\n      </div>\n    </div>\n\n    <!-- ============================ CONTEÚDO ============================ -->\n    <div class=\"content\" id=\"content\"><!-- views injetadas via JS --></div>\n  </div>\n</div>\n\n<!-- ============================ MODAL COMUNICADO ============================ -->\n<div class=\"modal-scrim\" id=\"modalScrim\">\n  <div class=\"modal-box\">\n    <div class=\"modal-head\">\n      <h2 id=\"modalTitle\"></h2>\n      <button class=\"modal-close\" id=\"modalClose\" aria-label=\"Fechar\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M18 6L6 18M6 6l12 12\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\" id=\"modalBody\"></div>\n  </div>\n</div>\n\n<script>\n/* =====================================================================\n   ÍCONES — glifos simples e consistentes (24x24, stroke), sem dependência externa\n   ===================================================================== */\nconst ICONS = {\n  home: \'<path d=\"M4 11.5L12 4l8 7.5\"/><path d=\"M6 10v9h12v-9\"/><path d=\"M10 19v-5h4v5\"/>\',\n  megaphone: \'<path d=\"M3 11v3a1 1 0 001 1h2l4 4V6L6 10H4a1 1 0 00-1 1z\"/><path d=\"M10 7l8-3v17l-8-3\"/><path d=\"M19 10.5a3 3 0 010 4\"/>\',\n  book: \'<path d=\"M4 19.5A2.5 2.5 0 016.5 17H20\"/><path d=\"M4 5.5A2.5 2.5 0 016.5 3H20v17H6.5A2.5 2.5 0 014 17.5v-12z\"/>\',\n  cap: \'<path d=\"M2 9l10-4 10 4-10 4-10-4z\"/><path d=\"M6 11.5V16c0 1.5 3 3 6 3s6-1.5 6-3v-4.5\"/>\',\n  pill: \'<path d=\"M5 13.5L13.5 5a4.5 4.5 0 016.36 6.36L11.36 19.86A4.5 4.5 0 015 13.5z\"/><path d=\"M9 9l6 6\"/>\',\n  shield: \'<path d=\"M12 3l8 3v6c0 5-3.5 7.5-8 9-4.5-1.5-8-4-8-9V6l8-3z\"/><path d=\"M9 12l2.2 2.2L15.5 9.5\"/>\',\n  flow: \'<circle cx=\"5\" cy=\"6\" r=\"2.2\"/><circle cx=\"19\" cy=\"6\" r=\"2.2\"/><circle cx=\"12\" cy=\"18\" r=\"2.2\"/><path d=\"M7 7l3.5 9M17 7l-3.5 9\"/>\',\n  mail: \'<path d=\"M4 6h16v12H4z\"/><path d=\"M4 7l8 6 8-6\"/>\',\n  chev: \'<path d=\"M6 9l6 6 6-6\"/>\',\n  paperclip: \'<path d=\"M8 12l6-6a3 3 0 014.2 4.2l-8 8a5 5 0 01-7-7l7-7\"/>\',\n  alert: \'<path d=\"M12 3l9 16H3l9-16z\"/><path d=\"M12 10v4\"/><circle cx=\"12\" cy=\"17\" r=\"0.6\"/>\',\n  check: \'<path d=\"M5 13l4 4L19 7\"/>\',\n  bell: \'<path d=\"M9 18a3 3 0 006 0\"/><path d=\"M6 11a6 6 0 1112 0v3.5l1.5 2.5h-15L6 14.5V11z\"/>\',\n  download: \'<path d=\"M12 4v11\"/><path d=\"M7 11l5 5 5-5\"/><path d=\"M5 19h14\"/>\',\n  film: \'<path d=\"M4 5h16v14H4z\"/><path d=\"M4 9h16M4 15h16M9 5v4M9 15v4\"/>\',\n  pin: \'<path d=\"M12 21s7-6.2 7-11.5A7 7 0 105 9.5C5 14.8 12 21 12 21z\"/><circle cx=\"12\" cy=\"9.5\" r=\"2.3\"/>\',\n  phone: \'<path d=\"M5 4h3l2 5-2.5 2a11 11 0 005.5 5.5l2-2.5 5 2v3a1 1 0 01-1 1A16 16 0 014 5a1 1 0 011-1z\"/>\',\n  clock: \'<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3.5 2\"/>\',\n  send: \'<path d=\"M3 11l18-8-8 18-2.5-7L3 11z\"/>\'\n};\nfunction ic(name, cls=\'\'){ return `<svg class=\"${cls}\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\">${ICONS[name]||\'\'}</svg>`; }\n\n/* =====================================================================\n   CONTEÚDO — substitua estes dados pelos materiais oficiais da farmácia.\n   Tudo o que aparece no portal vem destes objetos; não é necessário\n   editar HTML/CSS para atualizar comunicados, POPs, treinamentos etc.\n   ===================================================================== */\n\nconst NAV_ITEMS = [\n  { id:\'home\', label:\'Início\', icon:\'home\' },\n  { id:\'comunicados\', label:\'Comunicados\', icon:\'megaphone\', badge:()=>COMUNICADOS.length },\n  { id:\'pops\', label:\'POPs e Protocolos\', icon:\'book\', badge:()=>POPS.length },\n  { id:\'treinamentos\', label:\'Treinamentos\', icon:\'cap\' },\n  { id:\'padronizacao\', label:\'Padronização\', icon:\'pill\' },\n  { id:\'seguranca\', label:\'Segurança do Paciente\', icon:\'shield\' },\n  { id:\'fluxos\', label:\'Fluxos e Processos\', icon:\'flow\' },\n  { id:\'contato\', label:\'Contato\', icon:\'mail\' },\n];\n\nconst COMUNICADOS = [\n  {\n    id:\'c1\', cat:\'padronizacao\', catLabel:\'Padronização\',\n    titulo:\'Atualização da Lista de Medicamentos Padronizados — Junho/2026\',\n    data:\'24/06/2026\',\n    resumo:\'Inclusão de 3 itens e substituição de apresentação de 2 antimicrobianos na lista vigente, após avaliação da Comissão de Farmácia e Terapêutica (CFT).\',\n    corpo:\'A Comissão de Farmácia e Terapêutica aprovou, em reunião ordinária, a atualização da lista de medicamentos padronizados para o mês de junho. As principais alterações envolvem a inclusão de novas apresentações para adequação às boas práticas de fracionamento e a substituição de itens com restrição de fornecimento pelo distribuidor.\\n\\nAs unidades assistenciais devem observar a nova lista a partir de 01/07/2026. Estoques remanescentes dos itens substituídos poderão ser utilizados até o esgotamento, mediante orientação da farmácia clínica.\\n\\nDúvidas podem ser encaminhadas pelo canal de solicitações da farmácia.\',\n    anexo:\'Lista_Padronizacao_Jun2026.pdf\'\n  },\n  {\n    id:\'c2\', cat:\'desabastecimento\', catLabel:\'Desabastecimento\',\n    titulo:\'Desabastecimento temporário — Cloridrato de Vancomicina 500mg\',\n    data:\'21/06/2026\',\n    resumo:\'Fornecedor informou indisponibilidade pontual. Estoque de segurança garante cobertura prevista de 12 dias; alternativa terapêutica orientada para novas prescrições.\',\n    corpo:\'Em razão de instabilidade na cadeia de fornecimento, a Vancomicina 500mg pó para solução injetável encontra-se com fornecimento irregular. A farmácia mantém estoque estratégico para atendimento das prescrições em curso.\\n\\nPara novas prescrições, recomenda-se contato prévio com a farmácia clínica para avaliação de alternativa terapêutica e ajuste posológico, conforme nota técnica anexa.\\n\\nA situação será reavaliada semanalmente e novas atualizações serão publicadas neste canal.\',\n    anexo:\'Nota_Tecnica_Vancomicina.pdf\'\n  },\n  {\n    id:\'c3\', cat:\'protocolo\', catLabel:\'Protocolo\',\n    titulo:\'Novo fluxo de solicitação de medicamentos não padronizados\',\n    data:\'18/06/2026\',\n    resumo:\'A solicitação passa a ser feita exclusivamente pelo formulário eletrônico da farmácia, com prazo de resposta de até 4 horas em dias úteis.\',\n    corpo:\'A partir desta data, solicitações de medicamentos não padronizados deverão ser registradas pelo canal eletrônico da farmácia (seção \"Fluxos e Processos\" deste portal), substituindo o formulário em papel.\\n\\nO novo fluxo prevê: registro da solicitação justificada pelo médico assistente, análise farmacêutica de pertinência clínica e disponibilidade, e retorno em até 4 horas em dias úteis (8 horas em finais de semana e feriados).\\n\\nCasos de urgência devem ser comunicados também por telefone ao ramal da farmácia central.\',\n    anexo:\'Fluxo_Medicamento_Nao_Padronizado.pdf\'\n  },\n  {\n    id:\'c4\', cat:\'alerta\', catLabel:\'Alerta sanitário\',\n    titulo:\'Alerta ANVISA — recolhimento de lote de Insulina Regular\',\n    data:\'15/06/2026\',\n    resumo:\'Recolhimento preventivo de lote específico por desvio de qualidade. Farmácia já realizou conferência de estoque; nenhum frasco do lote identificado na unidade.\',\n    corpo:\'Em atenção ao alerta da ANVISA, a farmácia realizou conferência imediata do estoque de Insulina Regular. Não foram localizados frascos pertencentes ao lote objeto do recolhimento nesta unidade.\\n\\nAinda assim, recomenda-se que a equipe assistencial confira o número de lote de frascos já distribuídos para os setores antes da administração, conforme rotina padrão de checagem dupla para medicamentos de alta vigilância.\\n\\nEm caso de identificação do lote, suspender o uso e notificar a farmácia imediatamente.\',\n    anexo:\'Alerta_Anvisa_Insulina.pdf\'\n  },\n  {\n    id:\'c5\', cat:\'orientacao\', catLabel:\'Orientação institucional\',\n    titulo:\'Horário de funcionamento da Farmácia Central — feriado\',\n    data:\'10/06/2026\',\n    resumo:\'Atendimento em horário reduzido no feriado, com plantão para urgências mantido em regime 24h.\',\n    corpo:\'No feriado do próximo dia 24, a Farmácia Central funcionará em horário reduzido (8h às 14h) para dispensação de rotina. O plantão farmacêutico para urgências e setores críticos permanece em regime de 24 horas, conforme escala afixada no mural da farmácia.\\n\\nSolicitações de medicamentos não padronizados serão analisadas no primeiro dia útil subsequente, exceto em caráter de urgência clínica.\',\n    anexo:null\n  },\n];\n\nconst POPS = [\n  { codigo:\'POP-FAR-001\', versao:\'v4.0\', titulo:\'Dispensação de medicamentos em unidades de internação\', cat:\'dispensacao\', catLabel:\'Dispensação\', data:\'12/05/2026\' },\n  { codigo:\'POP-FAR-014\', versao:\'v2.1\', titulo:\'Armazenamento de medicamentos termolábeis (cadeia fria)\', cat:\'cadeia-fria\', catLabel:\'Cadeia fria\', data:\'03/04/2026\' },\n  { codigo:\'POP-FAR-022\', versao:\'v3.2\', titulo:\'Manejo de medicamentos de alta vigilância\', cat:\'alta-vigilancia\', catLabel:\'Alta vigilância\', data:\'28/05/2026\' },\n  { codigo:\'POP-FAR-030\', versao:\'v2.0\', titulo:\'Dispensação e controle de antimicrobianos\', cat:\'antimicrobianos\', catLabel:\'Antimicrobianos\', data:\'15/02/2026\' },\n  { codigo:\'POP-FAR-045\', versao:\'v1.3\', titulo:\'Fracionamento de formas sólidas orais\', cat:\'fracionamento\', catLabel:\'Fracionamento\', data:\'20/01/2026\' },\n  { codigo:\'POP-FAR-052\', versao:\'v2.4\', titulo:\'Manipulação de nutrição parenteral\', cat:\'farmacotecnica\', catLabel:\'Farmacotécnica hospitalar\', data:\'09/06/2026\' },\n  { codigo:\'POP-FAR-007\', versao:\'v3.0\', titulo:\'Armazenamento geral de medicamentos e correlatos\', cat:\'armazenamento\', catLabel:\'Armazenamento\', data:\'02/03/2026\' },\n  { codigo:\'POP-FAR-038\', versao:\'v1.1\', titulo:\'Reconstituição e diluição de antimicrobianos injetáveis\', cat:\'antimicrobianos\', catLabel:\'Antimicrobianos\', data:\'11/11/2025\' },\n];\n\nconst POP_CATEGORIAS = [\n  { id:\'todas\', label:\'Todas\' },\n  { id:\'dispensacao\', label:\'Dispensação\' },\n  { id:\'armazenamento\', label:\'Armazenamento\' },\n  { id:\'cadeia-fria\', label:\'Cadeia fria\' },\n  { id:\'alta-vigilancia\', label:\'Alta vigilância\' },\n  { id:\'antimicrobianos\', label:\'Antimicrobianos\' },\n  { id:\'fracionamento\', label:\'Fracionamento\' },\n  { id:\'farmacotecnica\', label:\'Farmacotécnica\' },\n];\n\nconst TREINAMENTOS = [\n  { titulo:\'Uso seguro de medicamentos de alta vigilância\', publico:\'Enfermagem e Farmácia\', duracao:\'25 min\', desc:\'Identificação, dupla checagem e boas práticas no manuseio de medicamentos com risco aumentado de dano.\' },\n  { titulo:\'Armazenamento correto de termolábeis e cadeia fria\', publico:\'Enfermagem, Farmácia e Almoxarifado\', duracao:\'18 min\', desc:\'Faixas de temperatura, rotina de monitoramento e conduta em caso de desvio térmico.\' },\n  { titulo:\'Erros de medicação: identificação e prevenção\', publico:\'Toda equipe assistencial\', duracao:\'30 min\', desc:\'Os \"5 certos\" da administração de medicamentos e como notificar eventos adversos.\' },\n  { titulo:\'Antimicrobianos e stewardship hospitalar\', publico:\'Médicos e Farmácia Clínica\', duracao:\'40 min\', desc:\'Princípios do uso racional de antimicrobianos e papel da farmácia no programa institucional.\' },\n];\n\nconst MEDICAMENTOS_PADRONIZADOS = [\n  { nome:\'Dipirona sódica\', classe:\'Analgésico/Antitérmico\', apresentacao:\'500mg/mL — solução injetável\', status:\'padronizado\' },\n  { nome:\'Ceftriaxona sódica\', classe:\'Antimicrobiano\', apresentacao:\'1g — pó p/ solução injetável\', status:\'padronizado\' },\n  { nome:\'Enoxaparina sódica\', classe:\'Anticoagulante\', apresentacao:\'40mg/0,4mL — seringa preenchida\', status:\'padronizado\' },\n  { nome:\'Vancomicina (em desabastecimento)\', classe:\'Antimicrobiano\', apresentacao:\'500mg — pó p/ solução injetável\', status:\'alternativa\' },\n  { nome:\'Omeprazol\', classe:\'Inibidor de bomba de prótons\', apresentacao:\'40mg — pó p/ solução injetável\', status:\'padronizado\' },\n  { nome:\'Midazolam\', classe:\'Sedativo/hipnótico\', apresentacao:\'5mg/mL — solução injetável\', status:\'padronizado\' },\n];\n\nconst ATUALIZACOES_PADRONIZACAO = [\n  { tipo:\'Inclusão\', item:\'Sulfato de magnésio 10% — ampola 10mL\', data:\'24/06/2026\' },\n  { tipo:\'Exclusão\', item:\'Apresentação anterior de Ceftriaxona 250mg (descontinuada pelo fabricante)\', data:\'24/06/2026\' },\n];\n\nconst NOTAS_TECNICAS = [\n  { titulo:\'Nota técnica — manejo de alternativa terapêutica à Vancomicina\', data:\'21/06/2026\' },\n  { titulo:\'Nota técnica — uso de Sulfato de Magnésio em pré-eclâmpsia\', data:\'05/06/2026\' },\n];\n\nconst LASA_PARES = [\n  { a:\'Hidr<span class=\"hl\">ALA</span>zina\', b:\'Hidr<span class=\"hl\">OXI</span>zina\', nota:\'Anti-hipertensivo × anti-histamínico. Confirmar indicação clínica antes da dispensação.\' },\n  { a:\'Clona<span class=\"hl\">ZE</span>pam\', b:\'Clo<span class=\"hl\">BA</span>zam\', nota:\'Ambos anticonvulsivantes/benzodiazepínicos — checar dose e apresentação.\' },\n  { a:\'Insulina <span class=\"hl\">NPH</span>\', b:\'Insulina <span class=\"hl\">Regular</span>\', nota:\'Tempo de ação distinto. Sempre confirmar tipo antes da administração.\' },\n  { a:\'Do<span class=\"hl\">PA</span>mina\', b:\'Do<span class=\"hl\">BU</span>tamina\', nota:\'Aminas vasoativas com mecanismos diferentes — risco elevado em UTI.\' },\n];\n\nconst ALTA_VIGILANCIA = [\'Insulinas (todas as apresentações)\',\'Heparina e demais anticoagulantes\',\'Cloreto de Potássio concentrado\',\'Opioides injetáveis\',\'Quimioterápicos antineoplásicos\',\'Bloqueadores neuromusculares\',\'Soluções concentradas de eletrólitos\',\'Sedativos para sedação profunda\'];\n\nconst CHECAGEM_DUPLA = [\n  { titulo:\'Identificação do paciente\', texto:\'Confirmar nome completo e data de nascimento, conferindo com a pulseira de identificação.\' },\n  { titulo:\'Confirmação do medicamento\', texto:\'Verificar nome, concentração, apresentação e validade do item a ser administrado.\' },\n  { titulo:\'Checagem da prescrição\', texto:\'Confrontar dose, via e horário com a prescrição médica vigente.\' },\n  { titulo:\'Assinatura dos dois profissionais\', texto:\'Ambos os profissionais envolvidos na checagem assinam o registro antes da administração.\' },\n];\n\nconst FLUXOS = [\n  { titulo:\'Solicitação de medicamento não padronizado\', passos:[\n    {t:\'Abertura da solicitação\', d:\'Médico assistente registra a justificativa clínica no formulário eletrônico.\'},\n    {t:\'Triagem farmacêutica\', d:\'Farmácia avalia pertinência clínica e disponibilidade de alternativa padronizada.\'},\n    {t:\'Parecer e aquisição\', d:\'Em caso de aprovação, farmácia inicia processo de aquisição ou empréstimo entre unidades.\'},\n    {t:\'Liberação ao setor\', d:\'Medicamento é liberado e o solicitante é notificado pelo prazo definido em protocolo.\'},\n  ]},\n  { titulo:\'Fluxo de devolução de medicamentos\', passos:[\n    {t:\'Identificação do item\', d:\'Setor separa o medicamento não utilizado, íntegro e dentro da validade.\'},\n    {t:\'Registro da devolução\', d:\'Preenchimento do formulário de devolução com motivo e responsável.\'},\n    {t:\'Conferência farmacêutica\', d:\'Farmácia verifica condições de armazenamento e integridade da embalagem.\'},\n    {t:\'Retorno ao estoque ou descarte\', d:\'Item retorna ao estoque ativo ou é destinado a descarte conforme normas vigentes.\'},\n  ]},\n  { titulo:\'Perdas e ajustes de estoque\', passos:[\n    {t:\'Identificação da divergência\', d:\'Equipe identifica perda, quebra ou divergência no inventário.\'},\n    {t:\'Registro formal\', d:\'Abertura de ocorrência com descrição, quantidade e setor envolvido.\'},\n    {t:\'Análise da farmácia\', d:\'Avaliação da causa raiz e classificação (operacional, técnica ou administrativa).\'},\n    {t:\'Ajuste no sistema\', d:\'Correção do saldo de estoque e arquivamento da documentação de suporte.\'},\n  ]},\n  { titulo:\'Fluxo de emergência\', passos:[\n    {t:\'Acionamento\', d:\'Setor aciona a farmácia pelo ramal de emergência, informando o medicamento necessário.\'},\n    {t:\'Priorização imediata\', d:\'Farmacêutico interrompe atividade de rotina para atendimento prioritário.\'},\n    {t:\'Entrega expressa\', d:\'Medicamento é encaminhado ao setor por mensageiro dedicado ou retirada direta.\'},\n    {t:\'Registro retroativo\', d:\'Documentação formal da dispensação é completada em até 2 horas.\'},\n  ]},\n  { titulo:\'Atendimento a setores críticos\', passos:[\n    {t:\'Padronização específica\', d:\'UTI, centro cirúrgico e emergência possuem kits e padronização própria revisados semestralmente.\'},\n    {t:\'Reposição programada\', d:\'Farmácia realiza checagem e reposição de kits em horários fixos, sem necessidade de solicitação.\'},\n    {t:\'Canal direto\', d:\'Setores críticos possuem ramal direto com farmacêutico de plantão.\'},\n    {t:\'Auditoria periódica\', d:\'Farmácia realiza auditoria mensal de validade e integridade dos kits.\'},\n  ]},\n];\n\nconst KPIS = [\n  { num:\'98,2%\', label:\'Conformidade em auditorias de dispensação\', trend:\'+0,6 p.p. vs mês anterior\', trendType:\'up\' },\n  { num:\'312\', label:\'POPs vigentes na biblioteca\', trend:\'4 revisados este mês\', trendType:\'flat\' },\n  { num:\'47\', label:\'Treinamentos concluídos no mês\', trend:\'+12 vs mês anterior\', trendType:\'up\' },\n  { num:\'1\', label:\'Evento adverso grave notificado no mês\', trend:\'Em análise pela CCIH\', trendType:\'warn\' },\n];\n\n/* =====================================================================\n   ROTEAMENTO E RENDERIZAÇÃO\n   ===================================================================== */\nlet currentView = \'home\';\nlet popFiltro = { cat:\'todas\', q:\'\' };\nlet comFiltro = { cat:\'todas\' };\n\nfunction catTagClass(cat){\n  return {protocolo:\'tag-protocolo\', padronizacao:\'tag-padronizacao\', desabastecimento:\'tag-desabastecimento\', alerta:\'tag-alerta\', orientacao:\'tag-orientacao\'}[cat] || \'tag-orientacao\';\n}\n\nfunction renderNav(){\n  document.getElementById(\'nav\').innerHTML = NAV_ITEMS.map(item => `\n    <button class=\"nav-item ${item.id===currentView?\'active\':\'\'}\" data-view=\"${item.id}\">\n      ${ic(item.icon)}\n      <span>${item.label}</span>\n      ${item.badge ? `<span class=\"badge\">${item.badge()}</span>` : \'\'}\n    </button>\n  `).join(\'\');\n  document.querySelectorAll(\'.nav-item\').forEach(btn=>{\n    btn.addEventListener(\'click\', ()=>{ navigate(btn.dataset.view); closeMobileMenu(); });\n  });\n}\n\nfunction renderHome(){\n  return `\n    <div class=\"page-head\">\n      <div>\n        <span class=\"eyebrow\">Painel principal</span>\n        <h1>Bem-vindo ao portal da Farmácia Hospitalar</h1>\n        <p>Acesso rápido a comunicados, protocolos e indicadores da assistência farmacêutica do Hospital Santa Lúcia Bauru.</p>\n      </div>\n    </div>\n\n    <div class=\"hero-stamp\">\n      <div class=\"selo\"><span class=\"selo-texto\">Farmácia Hospitalar · Uso Seguro de Medicamentos</span></div>\n      <div class=\"hero-stamp-text\">\n        <span class=\"eyebrow\">Compromisso institucional</span>\n        <h1>Uso seguro e racional de medicamentos, em cada etapa da assistência.</h1>\n        <p>Este portal reúne os protocolos, comunicados e materiais de educação continuada da Farmácia Hospitalar para toda a equipe do hospital.</p>\n      </div>\n    </div>\n\n    <div class=\"grid grid-4 kpi-row\">\n      ${KPIS.map(k=>`\n        <div class=\"card kpi\">\n          <div class=\"kpi-num\">${k.num}</div>\n          <div class=\"kpi-label\">${k.label}</div>\n          <span class=\"kpi-trend trend-${k.trendType}\">${k.trend}</span>\n        </div>\n      `).join(\'\')}\n    </div>\n\n    <div class=\"dash-grid\">\n      <div class=\"dash-col\">\n        <div class=\"card\" style=\"padding:18px 18px 8px;\">\n          <div class=\"section-title\">${ic(\'megaphone\')} Comunicados recentes <span class=\"ver-tudo\" data-go=\"comunicados\">Ver todos</span></div>\n          ${COMUNICADOS.slice(0,4).map(c=>`\n            <div class=\"list-item\">\n              <div class=\"list-item-icon\">${ic(\'megaphone\')}</div>\n              <div class=\"list-item-body\">\n                <div class=\"list-item-title\">${c.titulo}</div>\n                <div class=\"list-item-meta\">\n                  <span class=\"tag ${catTagClass(c.cat)}\">${c.catLabel}</span>\n                  <span class=\"mono\">${c.data}</span>\n                </div>\n              </div>\n            </div>\n          `).join(\'\')}\n        </div>\n\n        <div class=\"card\" style=\"padding:18px 18px 8px; margin-top:20px;\">\n          <div class=\"section-title\">${ic(\'book\')} POPs mais acessados <span class=\"ver-tudo\" data-go=\"pops\">Ver biblioteca</span></div>\n          ${POPS.slice(0,4).map(p=>`\n            <div class=\"list-item\">\n              <div class=\"list-item-icon\">${ic(\'book\')}</div>\n              <div class=\"list-item-body\">\n                <div class=\"list-item-title\">${p.titulo}</div>\n                <div class=\"list-item-meta\"><span class=\"mono\">${p.codigo} · ${p.versao}</span><span>${p.catLabel}</span></div>\n              </div>\n            </div>\n          `).join(\'\')}\n        </div>\n      </div>\n\n      <div class=\"dash-col\">\n        <div class=\"card\" style=\"padding:18px;\">\n          <div class=\"section-title\">${ic(\'alert\')} Alertas de segurança medicamentosa</div>\n          <div class=\"alert-row crit\">\n            ${ic(\'alert\')}\n            <div><div class=\"alert-row-title\">Recolhimento de lote — Insulina Regular</div><div class=\"alert-row-text\">Conferir número de lote antes da administração. Ver comunicado completo.</div></div>\n          </div>\n          <div class=\"alert-row\">\n            ${ic(\'alert\')}\n            <div><div class=\"alert-row-title\">Desabastecimento — Vancomicina 500mg</div><div class=\"alert-row-text\">Estoque de segurança garante cobertura de 12 dias.</div></div>\n          </div>\n        </div>\n\n        <div class=\"card\" style=\"padding:18px 18px 8px; margin-top:20px;\">\n          <div class=\"section-title\">${ic(\'cap\')} Treinamentos em destaque <span class=\"ver-tudo\" data-go=\"treinamentos\">Ver todos</span></div>\n          ${TREINAMENTOS.slice(0,2).map(t=>`\n            <div class=\"list-item\">\n              <div class=\"list-item-icon\">${ic(\'cap\')}</div>\n              <div class=\"list-item-body\">\n                <div class=\"list-item-title\">${t.titulo}</div>\n                <div class=\"list-item-meta\"><span class=\"mono\">${t.duracao}</span><span>${t.publico}</span></div>\n              </div>\n            </div>\n          `).join(\'\')}\n        </div>\n\n        <div class=\"card\" style=\"padding:18px 18px 8px; margin-top:20px;\">\n          <div class=\"section-title\">${ic(\'pill\')} Padronização — atualizações</div>\n          ${ATUALIZACOES_PADRONIZACAO.map(a=>`\n            <div class=\"list-item\">\n              <div class=\"list-item-icon\">${ic(\'pill\')}</div>\n              <div class=\"list-item-body\">\n                <div class=\"list-item-title\">${a.tipo}: ${a.item}</div>\n                <div class=\"list-item-meta\"><span class=\"mono\">${a.data}</span></div>\n              </div>\n            </div>\n          `).join(\'\')}\n        </div>\n      </div>\n    </div>\n  `;\n}\n\nfunction renderComunicados(){\n  const cats = [{id:\'todas\',label:\'Todas\'},{id:\'protocolo\',label:\'Protocolo\'},{id:\'padronizacao\',label:\'Padronização\'},{id:\'desabastecimento\',label:\'Desabastecimento\'},{id:\'alerta\',label:\'Alerta sanitário\'},{id:\'orientacao\',label:\'Orientação\'}];\n  const lista = COMUNICADOS.filter(c=> comFiltro.cat===\'todas\' || c.cat===comFiltro.cat);\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Comunicação oficial</span><h1>Comunicados da Farmácia</h1><p>Publicações oficiais sobre protocolos, padronização, desabastecimentos e alertas sanitários.</p></div>\n    </div>\n    <div class=\"filter-row\">\n      ${cats.map(c=>`<button class=\"chip ${comFiltro.cat===c.id?\'active\':\'\'}\" data-comcat=\"${c.id}\">${c.label}</button>`).join(\'\')}\n    </div>\n    <div id=\"comList\">\n      ${lista.length? lista.map(c=>`\n        <div class=\"card com-card\" data-comid=\"${c.id}\">\n          <div class=\"com-card-top\">\n            <span class=\"tag ${catTagClass(c.cat)}\">${c.catLabel}</span>\n            <span class=\"com-card-date mono\">${c.data}</span>\n          </div>\n          <h3>${c.titulo}</h3>\n          <p>${c.resumo}</p>\n          <div class=\"com-card-foot\">\n            <button class=\"btn btn-ghost\" data-comid=\"${c.id}\">Ler comunicado completo →</button>\n            ${c.anexo? `<span class=\"anexo-link\">${ic(\'paperclip\')} ${c.anexo}</span>` : \'\'}\n          </div>\n        </div>\n      `).join(\'\') : `<div class=\"empty\">Nenhum comunicado nesta categoria.</div>`}\n    </div>\n  `;\n}\n\nfunction renderPops(){\n  const lista = POPS.filter(p=>{\n    const matchCat = popFiltro.cat===\'todas\' || p.cat===popFiltro.cat;\n    const q = popFiltro.q.trim().toLowerCase();\n    const matchQ = !q || p.titulo.toLowerCase().includes(q) || p.codigo.toLowerCase().includes(q);\n    return matchCat && matchQ;\n  });\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Documentação técnica</span><h1>Biblioteca de POPs e Protocolos</h1><p>Procedimentos Operacionais Padrão vigentes, organizados por categoria e com controle de versão.</p></div>\n    </div>\n    <div class=\"lib-toolbar\">\n      <div class=\"search\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n        <input id=\"popSearch\" placeholder=\"Buscar por título ou código…\" value=\"${popFiltro.q}\">\n      </div>\n    </div>\n    <div class=\"filter-row\">\n      ${POP_CATEGORIAS.map(c=>`<button class=\"chip ${popFiltro.cat===c.id?\'active\':\'\'}\" data-popcat=\"${c.id}\">${c.label}</button>`).join(\'\')}\n    </div>\n    <div id=\"popList\">\n      ${lista.length? lista.map(p=>`\n        <div class=\"card pop-card\">\n          <div class=\"pop-card-tab\"></div>\n          <div class=\"pop-card-body\">\n            <div class=\"pop-card-code mono\">${p.codigo}<span class=\"ver\">${p.versao}</span></div>\n            <div class=\"pop-card-main\">\n              <h3>${p.titulo}</h3>\n              <div class=\"pop-card-main-meta\">\n                <span class=\"tag tag-orientacao\">${p.catLabel}</span>\n                <span class=\"mono\">Atualizado em ${p.data}</span>\n              </div>\n            </div>\n            <div class=\"pop-card-actions\">\n              <button class=\"btn btn-primary\" onclick=\"alert(\'Download de exemplo — conecte este botão ao arquivo real do POP (PDF).\')\">${ic(\'download\')} PDF</button>\n            </div>\n          </div>\n        </div>\n      `).join(\'\') : `<div class=\"empty\">Nenhum POP encontrado para esta busca.</div>`}\n    </div>\n  `;\n}\n\nfunction renderTreinamentos(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Educação continuada</span><h1>Treinamentos da Farmácia Hospitalar</h1><p>Capacitações sobre uso seguro de medicamentos, com vídeo, material de apoio e avaliação.</p></div>\n    </div>\n    <div class=\"grid grid-2\">\n      ${TREINAMENTOS.map(t=>`\n        <div class=\"card train-card\">\n          <div class=\"train-thumb\">${ic(\'film\')}<span class=\"dur mono\">${t.duracao}</span></div>\n          <div class=\"train-body\">\n            <h3>${t.titulo}</h3>\n            <p>${t.desc}</p>\n            <div class=\"train-audience\">${ic(\'cap\')} Público-alvo: ${t.publico}</div>\n            <div class=\"train-actions\">\n              <button class=\"btn btn-primary\" onclick=\"alert(\'Player de exemplo — incorpore aqui o vídeo do YouTube privado ou Google Drive.\')\">${ic(\'film\')} Assistir</button>\n              <button class=\"btn\" onclick=\"alert(\'Material de apoio em PDF — anexe aqui o arquivo real.\')\">${ic(\'download\')} Material</button>\n              <button class=\"btn\" onclick=\"alert(\'Questionário de avaliação — conecte aqui o Google Forms do treinamento.\')\">${ic(\'check\')} Avaliação</button>\n            </div>\n          </div>\n        </div>\n      `).join(\'\')}\n    </div>\n  `;\n}\n\nfunction renderPadronizacao(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Padronização institucional</span><h1>Padronização de Medicamentos</h1><p>Lista vigente, atualizações recentes e notas técnicas da Comissão de Farmácia e Terapêutica.</p></div>\n    </div>\n    <div class=\"card\" style=\"margin-bottom:20px;\">\n      <div class=\"table-wrap\">\n        <table class=\"std-table\">\n          <thead><tr><th>Medicamento</th><th>Classe</th><th>Apresentação</th><th>Status</th></tr></thead>\n          <tbody>\n            ${MEDICAMENTOS_PADRONIZADOS.map(m=>`\n              <tr>\n                <td><strong>${m.nome}</strong></td>\n                <td>${m.classe}</td>\n                <td>${m.apresentacao}</td>\n                <td><span class=\"status-dot status-${m.status}\">${m.status===\'padronizado\'?\'Padronizado\':\'Alternativa em uso\'}</span></td>\n              </tr>\n            `).join(\'\')}\n          </tbody>\n        </table>\n      </div>\n    </div>\n    <div class=\"grid grid-2\">\n      <div class=\"card\" style=\"padding:18px;\">\n        <div class=\"section-title\">${ic(\'pill\')} Atualizações recentes</div>\n        ${ATUALIZACOES_PADRONIZACAO.map(a=>`\n          <div class=\"list-item\"><div class=\"list-item-icon\">${ic(\'pill\')}</div>\n            <div class=\"list-item-body\"><div class=\"list-item-title\">${a.tipo}</div><div class=\"list-item-meta\">${a.item}<br><span class=\"mono\">${a.data}</span></div></div>\n          </div>\n        `).join(\'\')}\n      </div>\n      <div class=\"card\" style=\"padding:18px;\">\n        <div class=\"section-title\">${ic(\'book\')} Notas técnicas farmacêuticas</div>\n        ${NOTAS_TECNICAS.map(n=>`\n          <div class=\"list-item\"><div class=\"list-item-icon\">${ic(\'book\')}</div>\n            <div class=\"list-item-body\"><div class=\"list-item-title\">${n.titulo}</div><div class=\"list-item-meta\"><span class=\"mono\">${n.data}</span></div></div>\n          </div>\n        `).join(\'\')}\n      </div>\n    </div>\n  `;\n}\n\nfunction renderSeguranca(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Segurança do paciente</span><h1>Segurança do Paciente — Farmácia</h1><p>Conteúdo crítico sobre medicamentos LASA, alta vigilância e prevenção de erros de medicação.</p></div>\n    </div>\n\n    <div class=\"section-title\">${ic(\'alert\')} Medicamentos com nome ou aparência semelhante (LASA)</div>\n    <div style=\"margin-bottom:26px;\">\n      ${LASA_PARES.map(l=>`\n        <div class=\"card lasa-pair\">\n          <span class=\"lasa-word\">${l.a}</span><span class=\"lasa-vs\">vs</span><span class=\"lasa-word\">${l.b}</span>\n          <span class=\"lasa-note\">${l.nota}</span>\n        </div>\n      `).join(\'\')}\n    </div>\n\n    <div class=\"grid grid-2\" style=\"margin-bottom:26px;\">\n      <div>\n        <div class=\"section-title\">${ic(\'shield\')} Medicamentos de alta vigilância</div>\n        <div class=\"vigilancia-grid\">\n          ${ALTA_VIGILANCIA.map(v=>`<div class=\"card vigilancia-item\">${ic(\'alert\')}<span>${v}</span></div>`).join(\'\')}\n        </div>\n      </div>\n      <div>\n        <div class=\"section-title\">${ic(\'check\')} Protocolo de dupla checagem</div>\n        <div class=\"card\" style=\"padding: 6px 20px;\">\n          <div class=\"check-steps\">\n            ${CHECAGEM_DUPLA.map((c,i)=>`\n              <div class=\"check-step\">\n                <div class=\"check-step-num\">${i+1}</div>\n                <div class=\"check-step-text\"><strong>${c.titulo}</strong><span>${c.texto}</span></div>\n              </div>\n            `).join(\'\')}\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\" style=\"padding:20px; display:flex; gap:16px; align-items:center; flex-wrap:wrap;\">\n      <div style=\"flex:1; min-width:220px;\">\n        <div class=\"section-title\" style=\"margin-bottom:6px;\">${ic(\'bell\')} Identificou um erro de medicação ou evento adverso?</div>\n        <p style=\"font-size:12.5px; color:var(--gray);\">A notificação é essencial para a melhoria contínua dos processos. Não é necessário identificar o profissional.</p>\n      </div>\n      <button class=\"btn btn-primary\" data-go=\"contato\">${ic(\'send\')} Notificar evento</button>\n    </div>\n  `;\n}\n\nfunction renderFluxos(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Processos operacionais</span><h1>Fluxos e Processos da Farmácia</h1><p>Etapas padronizadas para solicitações, devoluções, ajustes de estoque e atendimentos especiais.</p></div>\n    </div>\n    <div id=\"flowList\">\n      ${FLUXOS.map((f,i)=>`\n        <div class=\"card flow-acc ${i===0?\'open\':\'\'}\" data-flow=\"${i}\">\n          <button class=\"flow-acc-head\" data-flowtoggle=\"${i}\">\n            <span class=\"num mono\">0${i+1}</span>\n            <h3>${f.titulo}</h3>\n            ${ic(\'chev\')}\n          </button>\n          <div class=\"flow-acc-body\">\n            <div class=\"flow-steps\">\n              ${f.passos.map((p,j)=>`\n                <div class=\"flow-step\">\n                  <div class=\"flow-step-inner\">\n                    <div class=\"flow-step-num mono\">${j+1}</div>\n                    <div class=\"flow-step-title\">${p.t}</div>\n                    <div class=\"flow-step-text\">${p.d}</div>\n                  </div>\n                </div>\n                ${j<f.passos.length-1? `<div class=\"flow-arrow\">${ic(\'chev\')}</div>` : \'\'}\n              `).join(\'\')}\n            </div>\n          </div>\n        </div>\n      `).join(\'\')}\n    </div>\n  `;\n}\n\nfunction renderContato(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Canal direto</span><h1>Contato e Solicitações</h1><p>Solicite medicamentos, tire dúvidas técnicas ou notifique problemas diretamente à Farmácia Hospitalar.</p></div>\n    </div>\n    <div class=\"contact-grid\">\n      <div class=\"card form-card\">\n        <div class=\"confirm-box\" id=\"confirmBox\">\n          ${ic(\'check\')}\n          <div><strong>Solicitação registrada</strong><span>Este é um formulário de demonstração — conecte-o ao seu sistema real de chamados ou e-mail institucional.</span></div>\n        </div>\n        <form id=\"contactForm\">\n          <div class=\"field-row\">\n            <div class=\"field\"><label>Nome completo</label><input required placeholder=\"Seu nome\"></div>\n            <div class=\"field\"><label>Setor</label><input required placeholder=\"Ex.: UTI Adulto\"></div>\n          </div>\n          <div class=\"field\">\n            <label>Tipo de solicitação</label>\n            <select>\n              <option>Solicitação de medicamento não padronizado</option>\n              <option>Dúvida técnica</option>\n              <option>Sugestão</option>\n              <option>Notificação de problema / evento adverso</option>\n            </select>\n          </div>\n          <div class=\"field\"><label>Mensagem</label><textarea required placeholder=\"Descreva sua solicitação com o máximo de detalhes possível…\"></textarea></div>\n          <button class=\"btn btn-primary btn-block\" type=\"submit\">${ic(\'send\')} Enviar solicitação</button>\n        </form>\n      </div>\n      <div class=\"card\" style=\"padding:22px 24px;\">\n        <div class=\"section-title\" style=\"margin-bottom:16px;\">Canais diretos</div>\n        <div class=\"contact-info-item\">${ic(\'phone\')}<div><strong>Ramal da Farmácia Central</strong><span>Ramal 4521 — dias úteis, 7h às 19h</span></div></div>\n        <div class=\"contact-info-item\">${ic(\'mail\')}<div><strong>E-mail institucional</strong><span>farmacia.hospitalar@hospitalsantalucia.exemplo</span></div></div>\n        <div class=\"contact-info-item\">${ic(\'clock\')}<div><strong>Plantão farmacêutico</strong><span>24 horas, todos os dias, via ramal de urgência 4599</span></div></div>\n        <div class=\"contact-info-item\">${ic(\'pin\')}<div><strong>Localização</strong><span>Farmácia Central — Bloco A, térreo</span></div></div>\n      </div>\n    </div>\n  `;\n}\n\nconst RENDERERS = {\n  home: renderHome, comunicados: renderComunicados, pops: renderPops,\n  treinamentos: renderTreinamentos, padronizacao: renderPadronizacao,\n  seguranca: renderSeguranca, fluxos: renderFluxos, contato: renderContato,\n};\n\nfunction navigate(view){\n  if(!RENDERERS[view]) return;\n  currentView = view;\n  document.getElementById(\'content\').innerHTML = `<div class=\"view active\">${RENDERERS[view]()}</div>`;\n  renderNav();\n  bindViewEvents(view);\n  document.getElementById(\'content\').scrollTop = 0;\n  window.scrollTo(0,0);\n}\n\nfunction bindViewEvents(view){\n  document.querySelectorAll(\'[data-go]\').forEach(el=> el.addEventListener(\'click\', ()=> navigate(el.dataset.go)));\n\n  if(view===\'comunicados\'){\n    document.querySelectorAll(\'[data-comcat]\').forEach(el=> el.addEventListener(\'click\', ()=>{ comFiltro.cat = el.dataset.comcat; navigate(\'comunicados\'); }));\n    document.querySelectorAll(\'[data-comid]\').forEach(el=> el.addEventListener(\'click\', ()=> openComunicado(el.dataset.comid)));\n  }\n  if(view===\'pops\'){\n    document.querySelectorAll(\'[data-popcat]\').forEach(el=> el.addEventListener(\'click\', ()=>{ popFiltro.cat = el.dataset.popcat; navigate(\'pops\'); }));\n    const input = document.getElementById(\'popSearch\');\n    if(input){\n      input.addEventListener(\'input\', ()=>{\n        const pos = input.selectionStart;\n        popFiltro.q = input.value;\n        navigate(\'pops\');\n        const newInput = document.getElementById(\'popSearch\');\n        newInput.focus();\n        newInput.setSelectionRange(pos,pos);\n      });\n    }\n  }\n  if(view===\'fluxos\'){\n    document.querySelectorAll(\'[data-flowtoggle]\').forEach(el=>{\n      el.addEventListener(\'click\', ()=>{\n        const card = el.closest(\'.flow-acc\');\n        card.classList.toggle(\'open\');\n      });\n    });\n  }\n  if(view===\'contato\'){\n    const form = document.getElementById(\'contactForm\');\n    form.addEventListener(\'submit\', (e)=>{\n      e.preventDefault();\n      document.getElementById(\'confirmBox\').classList.add(\'show\');\n      form.reset();\n      document.getElementById(\'confirmBox\').scrollIntoView({behavior:\'smooth\', block:\'center\'});\n    });\n  }\n}\n\nfunction openComunicado(id){\n  const c = COMUNICADOS.find(x=>x.id===id);\n  if(!c) return;\n  document.getElementById(\'modalTitle\').textContent = c.titulo;\n  document.getElementById(\'modalBody\').innerHTML = `\n    <div class=\"com-card-top\" style=\"margin-bottom:14px;\">\n      <span class=\"tag ${catTagClass(c.cat)}\">${c.catLabel}</span>\n      <span class=\"com-card-date mono\">${c.data}</span>\n    </div>\n    <div class=\"com-detail-body\">${c.corpo.split(\'\\n\\n\').map(p=>`<p>${p}</p>`).join(\'\')}</div>\n    ${c.anexo? `<div style=\"margin-top:16px;\"><span class=\"anexo-link\">${ic(\'paperclip\')} ${c.anexo}</span></div>` : \'\'}\n  `;\n  document.getElementById(\'modalScrim\').classList.add(\'show\');\n}\n\n/* =====================================================================\n   INTERAÇÕES GLOBAIS — menu mobile, busca global, modal\n   ===================================================================== */\nfunction openMobileMenu(){ document.getElementById(\'sidebar\').classList.add(\'open\'); document.getElementById(\'sidebarScrim\').classList.add(\'show\'); }\nfunction closeMobileMenu(){ document.getElementById(\'sidebar\').classList.remove(\'open\'); document.getElementById(\'sidebarScrim\').classList.remove(\'show\'); }\ndocument.getElementById(\'menuBtn\').addEventListener(\'click\', openMobileMenu);\ndocument.getElementById(\'sidebarScrim\').addEventListener(\'click\', closeMobileMenu);\n\ndocument.getElementById(\'modalClose\').addEventListener(\'click\', ()=> document.getElementById(\'modalScrim\').classList.remove(\'show\'));\ndocument.getElementById(\'modalScrim\').addEventListener(\'click\', (e)=>{ if(e.target.id===\'modalScrim\') document.getElementById(\'modalScrim\').classList.remove(\'show\'); });\ndocument.addEventListener(\'keydown\', (e)=>{ if(e.key===\'Escape\') document.getElementById(\'modalScrim\').classList.remove(\'show\'); });\n\ndocument.getElementById(\'globalSearch\').addEventListener(\'keydown\', (e)=>{\n  if(e.key===\'Enter\'){\n    const q = e.target.value.trim();\n    if(!q) return;\n    popFiltro = { cat:\'todas\', q:q };\n    navigate(\'pops\');\n  }\n});\n\n/* inicialização */\nrenderNav();\nnavigate(\'home\');\n</script>\n</body>\n</html>\n', '', '', 'inherit', 'closed', 'closed', '', '6-revision-v1', '', '', '2026-09-09 13:11:34', '2026-09-09 16:11:34', '', 6, 'http://localhost/faramcia_SL/wordpress/?p=8', 0, 'revision', '', 0);
INSERT INTO `wp_userposts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(9, 1, '2026-09-09 13:12:21', '2026-09-09 16:12:21', '<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Farmácia Hospitalar · Hospital Santa Lúcia Bauru</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Serif:wght@400;500;600;700&family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n\n/* ===================================================================\n   TOKENS — Identidade visual do Hospital Santa Lúcia Bauru\n   =================================================================== */\n:root{\n  /* paleta institucional (fixa pelo briefing) */\n  --red: #A80F14;\n  --red-deep: #7A0B0F;\n  --red-tint: #FBEAEA;\n  --gray: #666666;\n  --white: #FFFFFF;\n  --gray-light: #F5F5F5;\n\n  /* derivados de apoio — tons de \"papel\" e tinta, não decorativos */\n  --paper: #FBFAF8;\n  --ink: #262321;\n  --line: #E2DDD7;\n  --line-soft: #EEEAE5;\n\n  /* cores funcionais — usadas só para status/segurança, nunca decoração */\n  --amber: #92600A;\n  --amber-bg: #FBF1DF;\n  --green: #2E6B40;\n  --green-bg: #E9F2EA;\n\n  /* tipografia */\n  --f-display: \"IBM Plex Serif\", Georgia, serif;\n  --f-body: \"IBM Plex Sans\", -apple-system, Segoe UI, sans-serif;\n  --f-mono: \"IBM Plex Mono\", \"SFMono-Regular\", monospace;\n\n  --radius: 3px;\n  --shadow-card: 0 1px 2px rgba(38,35,33,0.06), 0 1px 1px rgba(38,35,33,0.04);\n  --shadow-pop: 0 8px 24px rgba(38,35,33,0.12);\n\n  --sidebar-w: 248px;\n}\n\n*{ box-sizing: border-box; }\nhtml{ scroll-behavior: smooth; }\nbody{\n  margin:0;\n  font-family: var(--f-body);\n  color: var(--ink);\n  background: var(--gray-light);\n  -webkit-font-smoothing: antialiased;\n}\nh1,h2,h3,h4{ font-family: var(--f-display); margin:0; line-height:1.2; font-weight:600; }\np{ margin:0; }\na{ color: var(--red); text-decoration: none; }\nbutton{ font-family: var(--f-body); cursor:pointer; }\n:focus-visible{ outline: 2px solid var(--red); outline-offset: 2px; }\n.mono{ font-family: var(--f-mono); }\n\n@media (prefers-reduced-motion: reduce){\n  *{ animation-duration: 0.001ms !important; transition-duration: 0.001ms !important; scroll-behavior:auto !important; }\n}\n\n/* ===================================================================\n   SELO — elemento de assinatura visual do portal\n   Inspirado no carimbo oficial de validação de documentos hospitalares.\n   =================================================================== */\n.selo{\n  --size: 92px;\n  width: var(--size); height: var(--size);\n  border-radius: 50%;\n  border: 2px solid currentColor;\n  display:flex; align-items:center; justify-content:center;\n  position: relative;\n  transform: rotate(-9deg);\n  flex-shrink:0;\n  color: var(--red);\n}\n.selo::before{\n  content:\"\";\n  position:absolute; inset:6px;\n  border: 1px dashed currentColor;\n  border-radius:50%;\n  opacity:0.55;\n}\n.selo-texto{\n  font-family: var(--f-mono);\n  font-size: 8.5px;\n  font-weight:600;\n  letter-spacing: 0.5px;\n  text-align:center;\n  text-transform: uppercase;\n  line-height:1.25;\n  padding: 0 10px;\n}\n.selo.selo-sm{ --size: 44px; }\n.selo.selo-sm .selo-texto{ font-size: 5.6px; padding:0 5px; }\n.selo.selo-ghost{ color: var(--gray); opacity:0.65; }\n\n/* ===================================================================\n   LAYOUT GERAL\n   =================================================================== */\n.app{\n  display:flex;\n  min-height:100vh;\n}\n\n/* ---------- SIDEBAR ---------- */\n.sidebar{\n  width: var(--sidebar-w);\n  flex-shrink:0;\n  background: var(--ink);\n  color: var(--white);\n  display:flex;\n  flex-direction:column;\n  position: fixed;\n  top:0; left:0; bottom:0;\n  z-index: 40;\n  transition: transform .25s ease;\n}\n.sidebar-brand{\n  padding: 22px 20px 18px;\n  border-bottom: 1px solid rgba(255,255,255,0.12);\n  display:flex; align-items:center; gap:12px;\n}\n.sidebar-brand .selo{ color: var(--white); }\n.sidebar-brand-text{ font-family: var(--f-display); line-height:1.25; }\n.sidebar-brand-text strong{ display:block; font-size:14.5px; font-weight:600; }\n.sidebar-brand-text span{ display:block; font-size:11px; color: rgba(255,255,255,0.6); font-family: var(--f-body); margin-top:2px; }\n\n.nav{ flex:1; padding: 10px 12px; display:flex; flex-direction:column; gap:2px; overflow-y:auto; }\n.nav-item{\n  display:flex; align-items:center; gap:11px;\n  padding: 10px 12px;\n  border-radius: var(--radius);\n  color: rgba(255,255,255,0.72);\n  font-size: 13.5px;\n  font-weight:500;\n  background:none; border:none; text-align:left; width:100%;\n  transition: background .15s, color .15s;\n}\n.nav-item svg{ width:17px; height:17px; flex-shrink:0; opacity:0.9; }\n.nav-item:hover{ background: rgba(255,255,255,0.07); color: var(--white); }\n.nav-item.active{ background: var(--red); color: var(--white); }\n.nav-item .badge{\n  margin-left:auto;\n  font-family: var(--f-mono);\n  font-size: 10px;\n  background: rgba(255,255,255,0.14);\n  padding: 1px 6px;\n  border-radius: 10px;\n}\n.nav-item.active .badge{ background: rgba(255,255,255,0.25); }\n\n.sidebar-foot{\n  padding: 14px 20px 18px;\n  border-top: 1px solid rgba(255,255,255,0.12);\n  font-size: 11px;\n  color: rgba(255,255,255,0.5);\n  line-height:1.6;\n}\n\n/* ---------- TOPBAR (mobile) ---------- */\n.topbar{\n  display:none;\n  position: sticky; top:0; z-index:30;\n  background: var(--ink); color:var(--white);\n  align-items:center; gap:12px;\n  padding: 13px 16px;\n}\n.topbar button{\n  background:none; border:none; color:var(--white);\n  width:32px;height:32px; display:flex; align-items:center; justify-content:center;\n}\n.topbar .selo{ --size:32px; color:var(--white); }\n.topbar .selo .selo-texto{ font-size:4px; }\n.topbar-title{ font-family: var(--f-display); font-size:14px; font-weight:600; }\n\n.sidebar-scrim{ display:none; }\n\n/* ---------- MAIN ---------- */\n.main{\n  margin-left: var(--sidebar-w);\n  flex:1;\n  min-width:0;\n  display:flex; flex-direction:column;\n}\n.topstrip{\n  background: var(--white);\n  border-bottom: 1px solid var(--line);\n  padding: 16px 36px;\n  display:flex; align-items:center; gap:18px;\n  position: sticky; top:0; z-index:20;\n}\n.search{\n  flex:1; max-width: 480px;\n  display:flex; align-items:center; gap:9px;\n  background: var(--gray-light);\n  border:1px solid var(--line);\n  border-radius: var(--radius);\n  padding: 9px 13px;\n}\n.search svg{ width:15px; height:15px; color: var(--gray); flex-shrink:0; }\n.search input{\n  border:none; background:none; outline:none; width:100%;\n  font-size:13.5px; font-family:var(--f-body); color:var(--ink);\n}\n.topstrip-meta{\n  margin-left:auto;\n  display:flex; align-items:center; gap:16px;\n  font-size:12.5px; color:var(--gray);\n}\n.pill-status{\n  display:flex; align-items:center; gap:6px;\n  font-family: var(--f-mono); font-size:11.5px;\n  color: var(--green);\n  background: var(--green-bg);\n  padding: 5px 10px; border-radius: 20px;\n}\n.pill-status::before{ content:\"\"; width:6px;height:6px;border-radius:50%; background:currentColor; }\n\n.content{\n  flex:1;\n  padding: 32px 36px 64px;\n  max-width: 1180px;\n}\n\n.view{ display:none; animation: fadein .35s ease; }\n.view.active{ display:block; }\n@keyframes fadein{ from{opacity:0; transform:translateY(4px);} to{opacity:1; transform:translateY(0);} }\n\n.page-head{\n  display:flex; align-items:flex-end; justify-content:space-between; gap:20px;\n  margin-bottom: 28px;\n  padding-bottom: 18px;\n  border-bottom: 1px solid var(--line);\n}\n.page-head .eyebrow{\n  font-family: var(--f-mono); font-size:11px; letter-spacing:1px;\n  color: var(--red); text-transform:uppercase; margin-bottom:6px; display:block;\n}\n.page-head h1{ font-size: 26px; }\n.page-head p{ color: var(--gray); font-size: 13.5px; margin-top:6px; max-width:560px; }\n\n/* ===================================================================\n   COMPONENTES REUTILIZÁVEIS\n   =================================================================== */\n.card{\n  background: var(--white);\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  box-shadow: var(--shadow-card);\n}\n.grid{ display:grid; gap:18px; }\n.grid-2{ grid-template-columns: repeat(2,1fr); }\n.grid-3{ grid-template-columns: repeat(3,1fr); }\n.grid-4{ grid-template-columns: repeat(4,1fr); }\n\n.section-title{\n  display:flex; align-items:center; gap:9px;\n  font-size: 14px; font-weight:600; font-family: var(--f-display);\n  margin-bottom:14px;\n}\n.section-title svg{ width:16px;height:16px; color:var(--red); }\n.section-title .ver-tudo{\n  margin-left:auto; font-family:var(--f-body); font-size:12px; font-weight:500; color:var(--red);\n}\n\n.tag{\n  display:inline-flex; align-items:center; gap:5px;\n  font-size: 10.5px; font-weight:600; text-transform:uppercase; letter-spacing:.4px;\n  padding: 3px 8px; border-radius: 20px;\n  font-family: var(--f-body);\n}\n.tag-protocolo{ background:var(--red-tint); color:var(--red-deep); }\n.tag-padronizacao{ background:var(--green-bg); color:var(--green); }\n.tag-desabastecimento{ background:var(--amber-bg); color:var(--amber); }\n.tag-alerta{ background:#2A2A2A; color:#fff; }\n.tag-orientacao{ background:var(--gray-light); color:var(--gray); border:1px solid var(--line); }\n\n.btn{\n  display:inline-flex; align-items:center; gap:7px;\n  font-size:12.5px; font-weight:600;\n  padding: 8px 14px; border-radius: var(--radius);\n  border: 1px solid var(--line);\n  background: var(--white); color: var(--ink);\n  transition: border-color .15s, background .15s;\n}\n.btn svg{ width:13px;height:13px; }\n.btn:hover{ border-color: var(--gray); }\n.btn-primary{ background: var(--red); border-color:var(--red); color:var(--white); }\n.btn-primary:hover{ background: var(--red-deep); border-color:var(--red-deep); }\n.btn-block{ width:100%; justify-content:center; }\n.btn-ghost{ border-color:transparent; padding-left:4px; padding-right:4px; }\n\n.empty{\n  text-align:center; padding: 38px 20px; color: var(--gray); font-size:13px;\n}\n\n/* ===================================================================\n   DASHBOARD\n   =================================================================== */\n.hero-stamp{\n  display:flex; align-items:center; gap:22px;\n  background: var(--ink);\n  color: var(--white);\n  border-radius: var(--radius);\n  padding: 26px 30px;\n  margin-bottom: 26px;\n  position:relative;\n  overflow:hidden;\n}\n.hero-stamp::after{\n  content:\"\";\n  position:absolute; right:-40px; top:-60px;\n  width:220px; height:220px;\n  border:1px dashed rgba(255,255,255,0.08);\n  border-radius:50%;\n}\n.hero-stamp .selo{ color:var(--white); --size:78px; }\n.hero-stamp-text .eyebrow{ font-family:var(--f-mono); font-size:11px; letter-spacing:1px; color:#E7A6A8; text-transform:uppercase; }\n.hero-stamp-text h1{ font-size:21px; margin-top:6px; }\n.hero-stamp-text p{ font-size:13px; color:rgba(255,255,255,0.68); margin-top:7px; max-width:520px; }\n\n.kpi-row{ margin-bottom:26px; }\n.kpi{ padding: 16px 18px; }\n.kpi .kpi-num{ font-family:var(--f-display); font-size:25px; font-weight:600; }\n.kpi .kpi-label{ font-size:11.5px; color:var(--gray); margin-top:4px; line-height:1.4; }\n.kpi .kpi-trend{ font-family:var(--f-mono); font-size:10.5px; margin-top:8px; display:inline-block; padding:2px 7px; border-radius:10px; }\n.trend-up{ background:var(--green-bg); color:var(--green); }\n.trend-flat{ background:var(--gray-light); color:var(--gray); }\n.trend-warn{ background:var(--amber-bg); color:var(--amber); }\n\n.dash-grid{ display:grid; grid-template-columns: 1.3fr 1fr; gap:20px; margin-bottom:20px; }\n.dash-col{ display:flex; flex-direction:column; gap:20px; }\n\n.list-item{\n  display:flex; gap:13px; padding: 13px 16px;\n  border-bottom: 1px solid var(--line-soft);\n}\n.list-item:last-child{ border-bottom:none; }\n.list-item-icon{\n  width:30px;height:30px; border-radius:50%; flex-shrink:0;\n  display:flex; align-items:center; justify-content:center;\n  background: var(--red-tint); color:var(--red);\n}\n.list-item-icon svg{ width:14px;height:14px; }\n.list-item-body{ flex:1; min-width:0; }\n.list-item-title{ font-size:13px; font-weight:600; line-height:1.35; }\n.list-item-meta{ font-size:11px; color:var(--gray); margin-top:4px; display:flex; gap:8px; align-items:center; flex-wrap:wrap; }\n\n.alert-row{\n  display:flex; gap:12px; align-items:flex-start;\n  padding: 13px 16px;\n  border-left: 3px solid var(--amber);\n  background: var(--amber-bg);\n  border-radius: 0 var(--radius) var(--radius) 0;\n  margin-bottom:10px;\n}\n.alert-row.crit{ border-left-color: var(--red); background: var(--red-tint); }\n.alert-row svg{ width:16px;height:16px; flex-shrink:0; margin-top:1px; color:var(--amber); }\n.alert-row.crit svg{ color:var(--red); }\n.alert-row-title{ font-size:12.5px; font-weight:600; }\n.alert-row-text{ font-size:11.5px; color:var(--gray); margin-top:3px; line-height:1.45; }\n\n/* ===================================================================\n   COMUNICADOS\n   =================================================================== */\n.filter-row{ display:flex; gap:8px; margin-bottom:20px; flex-wrap:wrap; align-items:center; }\n.chip{\n  font-size:12px; font-weight:500; padding:7px 13px;\n  border-radius:20px; border:1px solid var(--line); background:var(--white); color:var(--gray);\n}\n.chip.active{ background: var(--ink); border-color:var(--ink); color:var(--white); }\n\n.com-card{ padding: 18px 20px; margin-bottom:14px; cursor:pointer; }\n.com-card-top{ display:flex; align-items:center; gap:10px; margin-bottom:8px; flex-wrap:wrap; }\n.com-card-date{ font-family:var(--f-mono); font-size:11px; color:var(--gray); }\n.com-card h3{ font-size:15px; margin-bottom:6px; }\n.com-card p{ font-size:13px; color:var(--gray); line-height:1.55; }\n.com-card-foot{ margin-top:12px; display:flex; align-items:center; gap:14px; }\n.anexo-link{ display:flex; align-items:center; gap:6px; font-size:12px; font-weight:600; color:var(--red); }\n.anexo-link svg{ width:13px;height:13px; }\n\n.com-detail-body{ font-size:13.5px; line-height:1.7; color:var(--ink); }\n.com-detail-body p{ margin-bottom:12px; }\n\n/* ===================================================================\n   POPs — biblioteca em formato de \"ficha de documento\"\n   =================================================================== */\n.lib-toolbar{ display:flex; gap:10px; margin-bottom:18px; flex-wrap:wrap; }\n.lib-toolbar .search{ max-width:340px; }\n\n.pop-card{\n  display:flex; gap:0; overflow:hidden; margin-bottom:12px;\n}\n.pop-card-tab{\n  width:6px; background: var(--red); flex-shrink:0;\n}\n.pop-card-body{ padding:16px 18px; flex:1; display:flex; gap:16px; align-items:flex-start; }\n.pop-card-code{\n  font-family:var(--f-mono); font-size:12px; color:var(--gray);\n  background:var(--gray-light); padding:8px 10px; border-radius:var(--radius);\n  text-align:center; flex-shrink:0; min-width:108px;\n}\n.pop-card-code .ver{ display:block; margin-top:4px; font-weight:600; color:var(--red); }\n.pop-card-main{ flex:1; min-width:0; }\n.pop-card-main h3{ font-size:14.5px; margin-bottom:5px; }\n.pop-card-main-meta{ font-size:11.5px; color:var(--gray); display:flex; gap:12px; flex-wrap:wrap; margin-top:6px; }\n.pop-card-actions{ display:flex; gap:8px; flex-shrink:0; align-self:center; }\n\n/* ===================================================================\n   TREINAMENTOS\n   =================================================================== */\n.train-card{ overflow:hidden; }\n.train-thumb{\n  height: 108px;\n  background: linear-gradient(135deg, var(--ink), #3a3431);\n  display:flex; align-items:center; justify-content:center;\n  position:relative;\n}\n.train-thumb svg{ width:30px; height:30px; color: rgba(255,255,255,0.85); }\n.train-thumb .dur{\n  position:absolute; bottom:8px; right:10px;\n  font-family:var(--f-mono); font-size:10.5px; color:#fff;\n  background: rgba(0,0,0,0.45); padding:2px 7px; border-radius:10px;\n}\n.train-body{ padding:16px 18px; }\n.train-body h3{ font-size:14px; margin-bottom:7px; }\n.train-body p{ font-size:12.5px; color:var(--gray); line-height:1.55; margin-bottom:12px; }\n.train-audience{ font-size:11px; color:var(--gray); margin-bottom:14px; display:flex; gap:6px; align-items:center; }\n.train-actions{ display:flex; gap:8px; flex-wrap:wrap; }\n.train-actions .btn{ flex:1; justify-content:center; }\n\n/* ===================================================================\n   PADRONIZAÇÃO\n   =================================================================== */\n.table-wrap{ overflow-x:auto; }\ntable.std-table{ width:100%; border-collapse:collapse; font-size:13px; }\ntable.std-table th{\n  text-align:left; font-size:11px; text-transform:uppercase; letter-spacing:.4px;\n  color:var(--gray); padding:11px 16px; border-bottom:1px solid var(--line); font-weight:600;\n}\ntable.std-table td{ padding:13px 16px; border-bottom:1px solid var(--line-soft); }\ntable.std-table tr:last-child td{ border-bottom:none; }\n.status-dot{ display:inline-flex; align-items:center; gap:6px; font-size:12px; font-weight:600; }\n.status-dot::before{ content:\"\"; width:7px;height:7px;border-radius:50%; }\n.status-padronizado::before{ background:var(--green); }\n.status-padronizado{ color:var(--green); }\n.status-alternativa::before{ background:var(--amber); }\n.status-alternativa{ color:var(--amber); }\n\n/* ===================================================================\n   SEGURANÇA DO PACIENTE\n   =================================================================== */\n.lasa-pair{\n  display:flex; align-items:center; gap:14px; padding:15px 18px; margin-bottom:10px;\n}\n.lasa-word{ font-family:var(--f-display); font-weight:700; font-size:16px; }\n.lasa-word .hl{ background: #FCE4A6; padding:0 2px; border-radius:2px; }\n.lasa-vs{ font-family:var(--f-mono); font-size:11px; color:var(--gray); }\n.lasa-note{ margin-left:auto; font-size:11.5px; color:var(--gray); max-width:280px; text-align:right; }\n\n.vigilancia-grid{ display:grid; grid-template-columns:repeat(2,1fr); gap:10px; }\n.vigilancia-item{\n  display:flex; align-items:center; gap:10px; padding:13px 15px;\n  border-left:3px solid var(--red);\n}\n.vigilancia-item svg{ width:16px;height:16px; color:var(--red); flex-shrink:0; }\n.vigilancia-item span{ font-size:13px; font-weight:600; }\n\n.check-steps{ display:flex; flex-direction:column; gap:0; }\n.check-step{ display:flex; gap:14px; padding:14px 0; border-bottom:1px solid var(--line-soft); }\n.check-step:last-child{ border-bottom:none; }\n.check-step-num{\n  font-family:var(--f-mono); font-weight:600; font-size:12px;\n  width:26px; height:26px; border-radius:50%; background:var(--ink); color:#fff;\n  display:flex; align-items:center; justify-content:center; flex-shrink:0;\n}\n.check-step-text strong{ display:block; font-size:13px; margin-bottom:2px; }\n.check-step-text span{ font-size:12px; color:var(--gray); }\n\n/* ===================================================================\n   FLUXOS — diagramas em sequência (numerados, pois SÃO sequências reais)\n   =================================================================== */\n.flow-acc{ margin-bottom:12px; }\n.flow-acc-head{\n  display:flex; align-items:center; gap:13px; padding:16px 20px;\n  width:100%; background:none; border:none; text-align:left;\n}\n.flow-acc-head .num{ font-family:var(--f-mono); font-size:12px; color:var(--gray); }\n.flow-acc-head h3{ font-size:14.5px; flex:1; }\n.flow-acc-head svg{ width:15px;height:15px; color:var(--gray); transition:transform .2s; flex-shrink:0; }\n.flow-acc.open .flow-acc-head svg{ transform: rotate(180deg); }\n.flow-acc-body{ display:none; padding: 0 22px 20px 22px; }\n.flow-acc.open .flow-acc-body{ display:block; }\n\n.flow-steps{ display:flex; gap:0; overflow-x:auto; padding-top:6px; padding-bottom:8px; }\n.flow-step{ display:flex; align-items:flex-start; flex-shrink:0; min-width:168px; }\n.flow-step-inner{ padding-right:18px; }\n.flow-step-num{\n  font-family:var(--f-mono); font-size:11px; color:var(--white); background:var(--red);\n  width:22px; height:22px; border-radius:50%; display:flex; align-items:center; justify-content:center; margin-bottom:8px;\n}\n.flow-step-title{ font-size:12.5px; font-weight:600; line-height:1.4; }\n.flow-step-text{ font-size:11.5px; color:var(--gray); margin-top:4px; line-height:1.45; }\n.flow-arrow{ color:var(--line); margin: 0 4px; padding-top:5px; flex-shrink:0; }\n.flow-arrow svg{ width:16px;height:16px; }\n\n/* ===================================================================\n   CONTATO\n   =================================================================== */\n.contact-grid{ display:grid; grid-template-columns: 1.4fr 1fr; gap:22px; }\n.form-card{ padding:24px; }\n.field{ margin-bottom:16px; }\n.field label{ display:block; font-size:12px; font-weight:600; margin-bottom:6px; }\n.field input, .field select, .field textarea{\n  width:100%; padding:10px 12px; border:1px solid var(--line); border-radius:var(--radius);\n  font-family:var(--f-body); font-size:13px; background:var(--white); color:var(--ink);\n}\n.field textarea{ resize:vertical; min-height:90px; }\n.field input:focus, .field select:focus, .field textarea:focus{ outline:2px solid var(--red); outline-offset:0; border-color:var(--red); }\n.field-row{ display:grid; grid-template-columns:1fr 1fr; gap:14px; }\n\n.contact-info-item{ display:flex; gap:12px; padding:15px 0; border-bottom:1px solid var(--line-soft); }\n.contact-info-item:last-child{ border-bottom:none; }\n.contact-info-item svg{ width:16px;height:16px; color:var(--red); flex-shrink:0; margin-top:2px; }\n.contact-info-item strong{ display:block; font-size:12.5px; margin-bottom:2px; }\n.contact-info-item span{ font-size:12px; color:var(--gray); line-height:1.5; }\n\n.confirm-box{\n  display:none; align-items:flex-start; gap:12px;\n  background:var(--green-bg); border-left:3px solid var(--green);\n  padding:14px 16px; border-radius:0 var(--radius) var(--radius) 0; margin-bottom:16px;\n}\n.confirm-box.show{ display:flex; }\n.confirm-box svg{ width:17px;height:17px; color:var(--green); flex-shrink:0; margin-top:1px; }\n.confirm-box strong{ font-size:13px; display:block; }\n.confirm-box span{ font-size:12px; color:var(--gray); }\n\n/* ===================================================================\n   MODAL (detalhe de comunicado)\n   =================================================================== */\n.modal-scrim{\n  position:fixed; inset:0; background:rgba(38,35,33,0.55); z-index:60;\n  display:none; align-items:center; justify-content:center; padding:24px;\n}\n.modal-scrim.show{ display:flex; }\n.modal-box{\n  background:var(--white); border-radius:var(--radius); max-width:560px; width:100%;\n  max-height:85vh; overflow-y:auto; box-shadow: var(--shadow-pop);\n}\n.modal-head{ padding:22px 24px 16px; border-bottom:1px solid var(--line); display:flex; gap:16px; align-items:flex-start; }\n.modal-head h2{ font-size:17px; flex:1; }\n.modal-close{ background:none; border:none; color:var(--gray); width:28px; height:28px; flex-shrink:0; }\n.modal-close svg{ width:18px;height:18px; }\n.modal-body{ padding:20px 24px 26px; }\n\n/* ===================================================================\n   RESPONSIVO\n   =================================================================== */\n@media (max-width: 980px){\n  .grid-4{ grid-template-columns: repeat(2,1fr); }\n  .grid-3{ grid-template-columns: repeat(2,1fr); }\n  .dash-grid{ grid-template-columns: 1fr; }\n  .contact-grid{ grid-template-columns: 1fr; }\n}\n\n@media (max-width: 760px){\n  .sidebar{ transform: translateX(-100%); width: 270px; }\n  .sidebar.open{ transform: translateX(0); box-shadow: var(--shadow-pop); }\n  .main{ margin-left:0; }\n  .topbar{ display:flex; }\n  .topstrip{ padding:14px 18px; }\n  .topstrip-meta .pill-status span{ display:none; }\n  .content{ padding: 22px 18px 50px; }\n  .grid-2, .grid-3, .grid-4{ grid-template-columns: 1fr; }\n  .vigilancia-grid{ grid-template-columns:1fr; }\n  .field-row{ grid-template-columns:1fr; }\n  .hero-stamp{ flex-direction:column; align-items:flex-start; text-align:left; }\n  .pop-card-body{ flex-direction:column; gap:12px; }\n  .pop-card-actions{ align-self:flex-start; }\n  .sidebar-scrim.show{\n    display:block; position:fixed; inset:0; background:rgba(0,0,0,0.4); z-index:35;\n  }\n  .page-head{ flex-direction:column; align-items:flex-start; }\n}\n</style>\n</head>\n<body>\n\n<div class=\"app\">\n\n  <!-- ============================ SIDEBAR ============================ -->\n  <aside class=\"sidebar\" id=\"sidebar\">\n    <div class=\"sidebar-brand\">\n      <div class=\"selo selo-sm\"><span class=\"selo-texto\">Farmácia · Uso Seguro</span></div>\n      <div class=\"sidebar-brand-text\">\n        <strong>Farmácia Hospitalar</strong>\n        <span>Hospital Santa Lúcia Bauru</span>\n      </div>\n    </div>\n    <nav class=\"nav\" id=\"nav\"></nav>\n    <div class=\"sidebar-foot\">\n      Portal de uso interno.<br>Conteúdo de exemplo — substitua pelos dados oficiais da unidade.\n    </div>\n  </aside>\n  <div class=\"sidebar-scrim\" id=\"sidebarScrim\"></div>\n\n  <div class=\"main\">\n    <!-- ============================ TOPBAR (mobile) ============================ -->\n    <div class=\"topbar\">\n      <button id=\"menuBtn\" aria-label=\"Abrir menu\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M3 6h18M3 12h18M3 18h18\"/></svg>\n      </button>\n      <div class=\"selo\"><span class=\"selo-texto\">Farmácia</span></div>\n      <span class=\"topbar-title\">Farmácia Hospitalar</span>\n    </div>\n\n    <!-- ============================ TOPSTRIP ============================ -->\n    <div class=\"topstrip\">\n      <div class=\"search\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n        <input id=\"globalSearch\" placeholder=\"Buscar POPs, comunicados, medicamentos…\" autocomplete=\"off\">\n      </div>\n      <div class=\"topstrip-meta\">\n        <span class=\"pill-status\"><span>Sistemas operacionais</span></span>\n      </div>\n    </div>\n\n    <!-- ============================ CONTEÚDO ============================ -->\n    <div class=\"content\" id=\"content\"><!-- views injetadas via JS --></div>\n  </div>\n</div>\n\n<!-- ============================ MODAL COMUNICADO ============================ -->\n<div class=\"modal-scrim\" id=\"modalScrim\">\n  <div class=\"modal-box\">\n    <div class=\"modal-head\">\n      <h2 id=\"modalTitle\"></h2>\n      <button class=\"modal-close\" id=\"modalClose\" aria-label=\"Fechar\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M18 6L6 18M6 6l12 12\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\" id=\"modalBody\"></div>\n  </div>\n</div>\n\n<script>\n/* =====================================================================\n   ÍCONES — glifos simples e consistentes (24x24, stroke), sem dependência externa\n   ===================================================================== */\nconst ICONS = {\n  home: \'<path d=\"M4 11.5L12 4l8 7.5\"/><path d=\"M6 10v9h12v-9\"/><path d=\"M10 19v-5h4v5\"/>\',\n  megaphone: \'<path d=\"M3 11v3a1 1 0 001 1h2l4 4V6L6 10H4a1 1 0 00-1 1z\"/><path d=\"M10 7l8-3v17l-8-3\"/><path d=\"M19 10.5a3 3 0 010 4\"/>\',\n  book: \'<path d=\"M4 19.5A2.5 2.5 0 016.5 17H20\"/><path d=\"M4 5.5A2.5 2.5 0 016.5 3H20v17H6.5A2.5 2.5 0 014 17.5v-12z\"/>\',\n  cap: \'<path d=\"M2 9l10-4 10 4-10 4-10-4z\"/><path d=\"M6 11.5V16c0 1.5 3 3 6 3s6-1.5 6-3v-4.5\"/>\',\n  pill: \'<path d=\"M5 13.5L13.5 5a4.5 4.5 0 016.36 6.36L11.36 19.86A4.5 4.5 0 015 13.5z\"/><path d=\"M9 9l6 6\"/>\',\n  shield: \'<path d=\"M12 3l8 3v6c0 5-3.5 7.5-8 9-4.5-1.5-8-4-8-9V6l8-3z\"/><path d=\"M9 12l2.2 2.2L15.5 9.5\"/>\',\n  flow: \'<circle cx=\"5\" cy=\"6\" r=\"2.2\"/><circle cx=\"19\" cy=\"6\" r=\"2.2\"/><circle cx=\"12\" cy=\"18\" r=\"2.2\"/><path d=\"M7 7l3.5 9M17 7l-3.5 9\"/>\',\n  mail: \'<path d=\"M4 6h16v12H4z\"/><path d=\"M4 7l8 6 8-6\"/>\',\n  chev: \'<path d=\"M6 9l6 6 6-6\"/>\',\n  paperclip: \'<path d=\"M8 12l6-6a3 3 0 014.2 4.2l-8 8a5 5 0 01-7-7l7-7\"/>\',\n  alert: \'<path d=\"M12 3l9 16H3l9-16z\"/><path d=\"M12 10v4\"/><circle cx=\"12\" cy=\"17\" r=\"0.6\"/>\',\n  check: \'<path d=\"M5 13l4 4L19 7\"/>\',\n  bell: \'<path d=\"M9 18a3 3 0 006 0\"/><path d=\"M6 11a6 6 0 1112 0v3.5l1.5 2.5h-15L6 14.5V11z\"/>\',\n  download: \'<path d=\"M12 4v11\"/><path d=\"M7 11l5 5 5-5\"/><path d=\"M5 19h14\"/>\',\n  film: \'<path d=\"M4 5h16v14H4z\"/><path d=\"M4 9h16M4 15h16M9 5v4M9 15v4\"/>\',\n  pin: \'<path d=\"M12 21s7-6.2 7-11.5A7 7 0 105 9.5C5 14.8 12 21 12 21z\"/><circle cx=\"12\" cy=\"9.5\" r=\"2.3\"/>\',\n  phone: \'<path d=\"M5 4h3l2 5-2.5 2a11 11 0 005.5 5.5l2-2.5 5 2v3a1 1 0 01-1 1A16 16 0 014 5a1 1 0 011-1z\"/>\',\n  clock: \'<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3.5 2\"/>\',\n  send: \'<path d=\"M3 11l18-8-8 18-2.5-7L3 11z\"/>\'\n};\nfunction ic(name, cls=\'\'){ return `<svg class=\"${cls}\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\">${ICONS[name]||\'\'}</svg>`; }\n\n/* =====================================================================\n   CONTEÚDO — substitua estes dados pelos materiais oficiais da farmácia.\n   Tudo o que aparece no portal vem destes objetos; não é necessário\n   editar HTML/CSS para atualizar comunicados, POPs, treinamentos etc.\n   ===================================================================== */\n\nconst NAV_ITEMS = [\n  { id:\'home\', label:\'Início\', icon:\'home\' },\n  { id:\'comunicados\', label:\'Comunicados\', icon:\'megaphone\', badge:()=>COMUNICADOS.length },\n  { id:\'pops\', label:\'POPs e Protocolos\', icon:\'book\', badge:()=>POPS.length },\n  { id:\'treinamentos\', label:\'Treinamentos\', icon:\'cap\' },\n  { id:\'padronizacao\', label:\'Padronização\', icon:\'pill\' },\n  { id:\'seguranca\', label:\'Segurança do Paciente\', icon:\'shield\' },\n  { id:\'fluxos\', label:\'Fluxos e Processos\', icon:\'flow\' },\n  { id:\'contato\', label:\'Contato\', icon:\'mail\' },\n];\n\nconst COMUNICADOS = [\n  {\n    id:\'c1\', cat:\'padronizacao\', catLabel:\'Padronização\',\n    titulo:\'Atualização da Lista de Medicamentos Padronizados — Junho/2026\',\n    data:\'24/06/2026\',\n    resumo:\'Inclusão de 3 itens e substituição de apresentação de 2 antimicrobianos na lista vigente, após avaliação da Comissão de Farmácia e Terapêutica (CFT).\',\n    corpo:\'A Comissão de Farmácia e Terapêutica aprovou, em reunião ordinária, a atualização da lista de medicamentos padronizados para o mês de junho. As principais alterações envolvem a inclusão de novas apresentações para adequação às boas práticas de fracionamento e a substituição de itens com restrição de fornecimento pelo distribuidor.\\n\\nAs unidades assistenciais devem observar a nova lista a partir de 01/07/2026. Estoques remanescentes dos itens substituídos poderão ser utilizados até o esgotamento, mediante orientação da farmácia clínica.\\n\\nDúvidas podem ser encaminhadas pelo canal de solicitações da farmácia.\',\n    anexo:\'Lista_Padronizacao_Jun2026.pdf\'\n  },\n  {\n    id:\'c2\', cat:\'desabastecimento\', catLabel:\'Desabastecimento\',\n    titulo:\'Desabastecimento temporário — Cloridrato de Vancomicina 500mg\',\n    data:\'21/06/2026\',\n    resumo:\'Fornecedor informou indisponibilidade pontual. Estoque de segurança garante cobertura prevista de 12 dias; alternativa terapêutica orientada para novas prescrições.\',\n    corpo:\'Em razão de instabilidade na cadeia de fornecimento, a Vancomicina 500mg pó para solução injetável encontra-se com fornecimento irregular. A farmácia mantém estoque estratégico para atendimento das prescrições em curso.\\n\\nPara novas prescrições, recomenda-se contato prévio com a farmácia clínica para avaliação de alternativa terapêutica e ajuste posológico, conforme nota técnica anexa.\\n\\nA situação será reavaliada semanalmente e novas atualizações serão publicadas neste canal.\',\n    anexo:\'Nota_Tecnica_Vancomicina.pdf\'\n  },\n  {\n    id:\'c3\', cat:\'protocolo\', catLabel:\'Protocolo\',\n    titulo:\'Novo fluxo de solicitação de medicamentos não padronizados\',\n    data:\'18/06/2026\',\n    resumo:\'A solicitação passa a ser feita exclusivamente pelo formulário eletrônico da farmácia, com prazo de resposta de até 4 horas em dias úteis.\',\n    corpo:\'A partir desta data, solicitações de medicamentos não padronizados deverão ser registradas pelo canal eletrônico da farmácia (seção \"Fluxos e Processos\" deste portal), substituindo o formulário em papel.\\n\\nO novo fluxo prevê: registro da solicitação justificada pelo médico assistente, análise farmacêutica de pertinência clínica e disponibilidade, e retorno em até 4 horas em dias úteis (8 horas em finais de semana e feriados).\\n\\nCasos de urgência devem ser comunicados também por telefone ao ramal da farmácia central.\',\n    anexo:\'Fluxo_Medicamento_Nao_Padronizado.pdf\'\n  },\n  {\n    id:\'c4\', cat:\'alerta\', catLabel:\'Alerta sanitário\',\n    titulo:\'Alerta ANVISA — recolhimento de lote de Insulina Regular\',\n    data:\'15/06/2026\',\n    resumo:\'Recolhimento preventivo de lote específico por desvio de qualidade. Farmácia já realizou conferência de estoque; nenhum frasco do lote identificado na unidade.\',\n    corpo:\'Em atenção ao alerta da ANVISA, a farmácia realizou conferência imediata do estoque de Insulina Regular. Não foram localizados frascos pertencentes ao lote objeto do recolhimento nesta unidade.\\n\\nAinda assim, recomenda-se que a equipe assistencial confira o número de lote de frascos já distribuídos para os setores antes da administração, conforme rotina padrão de checagem dupla para medicamentos de alta vigilância.\\n\\nEm caso de identificação do lote, suspender o uso e notificar a farmácia imediatamente.\',\n    anexo:\'Alerta_Anvisa_Insulina.pdf\'\n  },\n  {\n    id:\'c5\', cat:\'orientacao\', catLabel:\'Orientação institucional\',\n    titulo:\'Horário de funcionamento da Farmácia Central — feriado\',\n    data:\'10/06/2026\',\n    resumo:\'Atendimento em horário reduzido no feriado, com plantão para urgências mantido em regime 24h.\',\n    corpo:\'No feriado do próximo dia 24, a Farmácia Central funcionará em horário reduzido (8h às 14h) para dispensação de rotina. O plantão farmacêutico para urgências e setores críticos permanece em regime de 24 horas, conforme escala afixada no mural da farmácia.\\n\\nSolicitações de medicamentos não padronizados serão analisadas no primeiro dia útil subsequente, exceto em caráter de urgência clínica.\',\n    anexo:null\n  },\n];\n\nconst POPS = [\n  { codigo:\'POP-FAR-001\', versao:\'v4.0\', titulo:\'Dispensação de medicamentos em unidades de internação\', cat:\'dispensacao\', catLabel:\'Dispensação\', data:\'12/05/2026\' },\n  { codigo:\'POP-FAR-014\', versao:\'v2.1\', titulo:\'Armazenamento de medicamentos termolábeis (cadeia fria)\', cat:\'cadeia-fria\', catLabel:\'Cadeia fria\', data:\'03/04/2026\' },\n  { codigo:\'POP-FAR-022\', versao:\'v3.2\', titulo:\'Manejo de medicamentos de alta vigilância\', cat:\'alta-vigilancia\', catLabel:\'Alta vigilância\', data:\'28/05/2026\' },\n  { codigo:\'POP-FAR-030\', versao:\'v2.0\', titulo:\'Dispensação e controle de antimicrobianos\', cat:\'antimicrobianos\', catLabel:\'Antimicrobianos\', data:\'15/02/2026\' },\n  { codigo:\'POP-FAR-045\', versao:\'v1.3\', titulo:\'Fracionamento de formas sólidas orais\', cat:\'fracionamento\', catLabel:\'Fracionamento\', data:\'20/01/2026\' },\n  { codigo:\'POP-FAR-052\', versao:\'v2.4\', titulo:\'Manipulação de nutrição parenteral\', cat:\'farmacotecnica\', catLabel:\'Farmacotécnica hospitalar\', data:\'09/06/2026\' },\n  { codigo:\'POP-FAR-007\', versao:\'v3.0\', titulo:\'Armazenamento geral de medicamentos e correlatos\', cat:\'armazenamento\', catLabel:\'Armazenamento\', data:\'02/03/2026\' },\n  { codigo:\'POP-FAR-038\', versao:\'v1.1\', titulo:\'Reconstituição e diluição de antimicrobianos injetáveis\', cat:\'antimicrobianos\', catLabel:\'Antimicrobianos\', data:\'11/11/2025\' },\n];\n\nconst POP_CATEGORIAS = [\n  { id:\'todas\', label:\'Todas\' },\n  { id:\'dispensacao\', label:\'Dispensação\' },\n  { id:\'armazenamento\', label:\'Armazenamento\' },\n  { id:\'cadeia-fria\', label:\'Cadeia fria\' },\n  { id:\'alta-vigilancia\', label:\'Alta vigilância\' },\n  { id:\'antimicrobianos\', label:\'Antimicrobianos\' },\n  { id:\'fracionamento\', label:\'Fracionamento\' },\n  { id:\'farmacotecnica\', label:\'Farmacotécnica\' },\n];\n\nconst TREINAMENTOS = [\n  { titulo:\'Uso seguro de medicamentos de alta vigilância\', publico:\'Enfermagem e Farmácia\', duracao:\'25 min\', desc:\'Identificação, dupla checagem e boas práticas no manuseio de medicamentos com risco aumentado de dano.\' },\n  { titulo:\'Armazenamento correto de termolábeis e cadeia fria\', publico:\'Enfermagem, Farmácia e Almoxarifado\', duracao:\'18 min\', desc:\'Faixas de temperatura, rotina de monitoramento e conduta em caso de desvio térmico.\' },\n  { titulo:\'Erros de medicação: identificação e prevenção\', publico:\'Toda equipe assistencial\', duracao:\'30 min\', desc:\'Os \"5 certos\" da administração de medicamentos e como notificar eventos adversos.\' },\n  { titulo:\'Antimicrobianos e stewardship hospitalar\', publico:\'Médicos e Farmácia Clínica\', duracao:\'40 min\', desc:\'Princípios do uso racional de antimicrobianos e papel da farmácia no programa institucional.\' },\n];\n\nconst MEDICAMENTOS_PADRONIZADOS = [\n  { nome:\'Dipirona sódica\', classe:\'Analgésico/Antitérmico\', apresentacao:\'500mg/mL — solução injetável\', status:\'padronizado\' },\n  { nome:\'Ceftriaxona sódica\', classe:\'Antimicrobiano\', apresentacao:\'1g — pó p/ solução injetável\', status:\'padronizado\' },\n  { nome:\'Enoxaparina sódica\', classe:\'Anticoagulante\', apresentacao:\'40mg/0,4mL — seringa preenchida\', status:\'padronizado\' },\n  { nome:\'Vancomicina (em desabastecimento)\', classe:\'Antimicrobiano\', apresentacao:\'500mg — pó p/ solução injetável\', status:\'alternativa\' },\n  { nome:\'Omeprazol\', classe:\'Inibidor de bomba de prótons\', apresentacao:\'40mg — pó p/ solução injetável\', status:\'padronizado\' },\n  { nome:\'Midazolam\', classe:\'Sedativo/hipnótico\', apresentacao:\'5mg/mL — solução injetável\', status:\'padronizado\' },\n];\n\nconst ATUALIZACOES_PADRONIZACAO = [\n  { tipo:\'Inclusão\', item:\'Sulfato de magnésio 10% — ampola 10mL\', data:\'24/06/2026\' },\n  { tipo:\'Exclusão\', item:\'Apresentação anterior de Ceftriaxona 250mg (descontinuada pelo fabricante)\', data:\'24/06/2026\' },\n];\n\nconst NOTAS_TECNICAS = [\n  { titulo:\'Nota técnica — manejo de alternativa terapêutica à Vancomicina\', data:\'21/06/2026\' },\n  { titulo:\'Nota técnica — uso de Sulfato de Magnésio em pré-eclâmpsia\', data:\'05/06/2026\' },\n];\n\nconst LASA_PARES = [\n  { a:\'Hidr<span class=\"hl\">ALA</span>zina\', b:\'Hidr<span class=\"hl\">OXI</span>zina\', nota:\'Anti-hipertensivo × anti-histamínico. Confirmar indicação clínica antes da dispensação.\' },\n  { a:\'Clona<span class=\"hl\">ZE</span>pam\', b:\'Clo<span class=\"hl\">BA</span>zam\', nota:\'Ambos anticonvulsivantes/benzodiazepínicos — checar dose e apresentação.\' },\n  { a:\'Insulina <span class=\"hl\">NPH</span>\', b:\'Insulina <span class=\"hl\">Regular</span>\', nota:\'Tempo de ação distinto. Sempre confirmar tipo antes da administração.\' },\n  { a:\'Do<span class=\"hl\">PA</span>mina\', b:\'Do<span class=\"hl\">BU</span>tamina\', nota:\'Aminas vasoativas com mecanismos diferentes — risco elevado em UTI.\' },\n];\n\nconst ALTA_VIGILANCIA = [\'Insulinas (todas as apresentações)\',\'Heparina e demais anticoagulantes\',\'Cloreto de Potássio concentrado\',\'Opioides injetáveis\',\'Quimioterápicos antineoplásicos\',\'Bloqueadores neuromusculares\',\'Soluções concentradas de eletrólitos\',\'Sedativos para sedação profunda\'];\n\nconst CHECAGEM_DUPLA = [\n  { titulo:\'Identificação do paciente\', texto:\'Confirmar nome completo e data de nascimento, conferindo com a pulseira de identificação.\' },\n  { titulo:\'Confirmação do medicamento\', texto:\'Verificar nome, concentração, apresentação e validade do item a ser administrado.\' },\n  { titulo:\'Checagem da prescrição\', texto:\'Confrontar dose, via e horário com a prescrição médica vigente.\' },\n  { titulo:\'Assinatura dos dois profissionais\', texto:\'Ambos os profissionais envolvidos na checagem assinam o registro antes da administração.\' },\n];\n\nconst FLUXOS = [\n  { titulo:\'Solicitação de medicamento não padronizado\', passos:[\n    {t:\'Abertura da solicitação\', d:\'Médico assistente registra a justificativa clínica no formulário eletrônico.\'},\n    {t:\'Triagem farmacêutica\', d:\'Farmácia avalia pertinência clínica e disponibilidade de alternativa padronizada.\'},\n    {t:\'Parecer e aquisição\', d:\'Em caso de aprovação, farmácia inicia processo de aquisição ou empréstimo entre unidades.\'},\n    {t:\'Liberação ao setor\', d:\'Medicamento é liberado e o solicitante é notificado pelo prazo definido em protocolo.\'},\n  ]},\n  { titulo:\'Fluxo de devolução de medicamentos\', passos:[\n    {t:\'Identificação do item\', d:\'Setor separa o medicamento não utilizado, íntegro e dentro da validade.\'},\n    {t:\'Registro da devolução\', d:\'Preenchimento do formulário de devolução com motivo e responsável.\'},\n    {t:\'Conferência farmacêutica\', d:\'Farmácia verifica condições de armazenamento e integridade da embalagem.\'},\n    {t:\'Retorno ao estoque ou descarte\', d:\'Item retorna ao estoque ativo ou é destinado a descarte conforme normas vigentes.\'},\n  ]},\n  { titulo:\'Perdas e ajustes de estoque\', passos:[\n    {t:\'Identificação da divergência\', d:\'Equipe identifica perda, quebra ou divergência no inventário.\'},\n    {t:\'Registro formal\', d:\'Abertura de ocorrência com descrição, quantidade e setor envolvido.\'},\n    {t:\'Análise da farmácia\', d:\'Avaliação da causa raiz e classificação (operacional, técnica ou administrativa).\'},\n    {t:\'Ajuste no sistema\', d:\'Correção do saldo de estoque e arquivamento da documentação de suporte.\'},\n  ]},\n  { titulo:\'Fluxo de emergência\', passos:[\n    {t:\'Acionamento\', d:\'Setor aciona a farmácia pelo ramal de emergência, informando o medicamento necessário.\'},\n    {t:\'Priorização imediata\', d:\'Farmacêutico interrompe atividade de rotina para atendimento prioritário.\'},\n    {t:\'Entrega expressa\', d:\'Medicamento é encaminhado ao setor por mensageiro dedicado ou retirada direta.\'},\n    {t:\'Registro retroativo\', d:\'Documentação formal da dispensação é completada em até 2 horas.\'},\n  ]},\n  { titulo:\'Atendimento a setores críticos\', passos:[\n    {t:\'Padronização específica\', d:\'UTI, centro cirúrgico e emergência possuem kits e padronização própria revisados semestralmente.\'},\n    {t:\'Reposição programada\', d:\'Farmácia realiza checagem e reposição de kits em horários fixos, sem necessidade de solicitação.\'},\n    {t:\'Canal direto\', d:\'Setores críticos possuem ramal direto com farmacêutico de plantão.\'},\n    {t:\'Auditoria periódica\', d:\'Farmácia realiza auditoria mensal de validade e integridade dos kits.\'},\n  ]},\n];\n\nconst KPIS = [\n  { num:\'98,2%\', label:\'Conformidade em auditorias de dispensação\', trend:\'+0,6 p.p. vs mês anterior\', trendType:\'up\' },\n  { num:\'312\', label:\'POPs vigentes na biblioteca\', trend:\'4 revisados este mês\', trendType:\'flat\' },\n  { num:\'47\', label:\'Treinamentos concluídos no mês\', trend:\'+12 vs mês anterior\', trendType:\'up\' },\n  { num:\'1\', label:\'Evento adverso grave notificado no mês\', trend:\'Em análise pela CCIH\', trendType:\'warn\' },\n];\n\n/* =====================================================================\n   ROTEAMENTO E RENDERIZAÇÃO\n   ===================================================================== */\nlet currentView = \'home\';\nlet popFiltro = { cat:\'todas\', q:\'\' };\nlet comFiltro = { cat:\'todas\' };\n\nfunction catTagClass(cat){\n  return {protocolo:\'tag-protocolo\', padronizacao:\'tag-padronizacao\', desabastecimento:\'tag-desabastecimento\', alerta:\'tag-alerta\', orientacao:\'tag-orientacao\'}[cat] || \'tag-orientacao\';\n}\n\nfunction renderNav(){\n  document.getElementById(\'nav\').innerHTML = NAV_ITEMS.map(item => `\n    <button class=\"nav-item ${item.id===currentView?\'active\':\'\'}\" data-view=\"${item.id}\">\n      ${ic(item.icon)}\n      <span>${item.label}</span>\n      ${item.badge ? `<span class=\"badge\">${item.badge()}</span>` : \'\'}\n    </button>\n  `).join(\'\');\n  document.querySelectorAll(\'.nav-item\').forEach(btn=>{\n    btn.addEventListener(\'click\', ()=>{ navigate(btn.dataset.view); closeMobileMenu(); });\n  });\n}\n\nfunction renderHome(){\n  return `\n    <div class=\"page-head\">\n      <div>\n        <span class=\"eyebrow\">Painel principal</span>\n        <h1>Bem-vindo ao portal da Farmácia Hospitalar</h1>\n        <p>Acesso rápido a comunicados, protocolos e indicadores da assistência farmacêutica do Hospital Santa Lúcia Bauru.</p>\n      </div>\n    </div>\n\n    <div class=\"hero-stamp\">\n      <div class=\"selo\"><span class=\"selo-texto\">Farmácia Hospitalar · Uso Seguro de Medicamentos</span></div>\n      <div class=\"hero-stamp-text\">\n        <span class=\"eyebrow\">Compromisso institucional</span>\n        <h1>Uso seguro e racional de medicamentos, em cada etapa da assistência.</h1>\n        <p>Este portal reúne os protocolos, comunicados e materiais de educação continuada da Farmácia Hospitalar para toda a equipe do hospital.</p>\n      </div>\n    </div>\n\n    <div class=\"grid grid-4 kpi-row\">\n      ${KPIS.map(k=>`\n        <div class=\"card kpi\">\n          <div class=\"kpi-num\">${k.num}</div>\n          <div class=\"kpi-label\">${k.label}</div>\n          <span class=\"kpi-trend trend-${k.trendType}\">${k.trend}</span>\n        </div>\n      `).join(\'\')}\n    </div>\n\n    <div class=\"dash-grid\">\n      <div class=\"dash-col\">\n        <div class=\"card\" style=\"padding:18px 18px 8px;\">\n          <div class=\"section-title\">${ic(\'megaphone\')} Comunicados recentes <span class=\"ver-tudo\" data-go=\"comunicados\">Ver todos</span></div>\n          ${COMUNICADOS.slice(0,4).map(c=>`\n            <div class=\"list-item\">\n              <div class=\"list-item-icon\">${ic(\'megaphone\')}</div>\n              <div class=\"list-item-body\">\n                <div class=\"list-item-title\">${c.titulo}</div>\n                <div class=\"list-item-meta\">\n                  <span class=\"tag ${catTagClass(c.cat)}\">${c.catLabel}</span>\n                  <span class=\"mono\">${c.data}</span>\n                </div>\n              </div>\n            </div>\n          `).join(\'\')}\n        </div>\n\n        <div class=\"card\" style=\"padding:18px 18px 8px; margin-top:20px;\">\n          <div class=\"section-title\">${ic(\'book\')} POPs mais acessados <span class=\"ver-tudo\" data-go=\"pops\">Ver biblioteca</span></div>\n          ${POPS.slice(0,4).map(p=>`\n            <div class=\"list-item\">\n              <div class=\"list-item-icon\">${ic(\'book\')}</div>\n              <div class=\"list-item-body\">\n                <div class=\"list-item-title\">${p.titulo}</div>\n                <div class=\"list-item-meta\"><span class=\"mono\">${p.codigo} · ${p.versao}</span><span>${p.catLabel}</span></div>\n              </div>\n            </div>\n          `).join(\'\')}\n        </div>\n      </div>\n\n      <div class=\"dash-col\">\n        <div class=\"card\" style=\"padding:18px;\">\n          <div class=\"section-title\">${ic(\'alert\')} Alertas de segurança medicamentosa</div>\n          <div class=\"alert-row crit\">\n            ${ic(\'alert\')}\n            <div><div class=\"alert-row-title\">Recolhimento de lote — Insulina Regular</div><div class=\"alert-row-text\">Conferir número de lote antes da administração. Ver comunicado completo.</div></div>\n          </div>\n          <div class=\"alert-row\">\n            ${ic(\'alert\')}\n            <div><div class=\"alert-row-title\">Desabastecimento — Vancomicina 500mg</div><div class=\"alert-row-text\">Estoque de segurança garante cobertura de 12 dias.</div></div>\n          </div>\n        </div>\n\n        <div class=\"card\" style=\"padding:18px 18px 8px; margin-top:20px;\">\n          <div class=\"section-title\">${ic(\'cap\')} Treinamentos em destaque <span class=\"ver-tudo\" data-go=\"treinamentos\">Ver todos</span></div>\n          ${TREINAMENTOS.slice(0,2).map(t=>`\n            <div class=\"list-item\">\n              <div class=\"list-item-icon\">${ic(\'cap\')}</div>\n              <div class=\"list-item-body\">\n                <div class=\"list-item-title\">${t.titulo}</div>\n                <div class=\"list-item-meta\"><span class=\"mono\">${t.duracao}</span><span>${t.publico}</span></div>\n              </div>\n            </div>\n          `).join(\'\')}\n        </div>\n\n        <div class=\"card\" style=\"padding:18px 18px 8px; margin-top:20px;\">\n          <div class=\"section-title\">${ic(\'pill\')} Padronização — atualizações</div>\n          ${ATUALIZACOES_PADRONIZACAO.map(a=>`\n            <div class=\"list-item\">\n              <div class=\"list-item-icon\">${ic(\'pill\')}</div>\n              <div class=\"list-item-body\">\n                <div class=\"list-item-title\">${a.tipo}: ${a.item}</div>\n                <div class=\"list-item-meta\"><span class=\"mono\">${a.data}</span></div>\n              </div>\n            </div>\n          `).join(\'\')}\n        </div>\n      </div>\n    </div>\n  `;\n}\n\nfunction renderComunicados(){\n  const cats = [{id:\'todas\',label:\'Todas\'},{id:\'protocolo\',label:\'Protocolo\'},{id:\'padronizacao\',label:\'Padronização\'},{id:\'desabastecimento\',label:\'Desabastecimento\'},{id:\'alerta\',label:\'Alerta sanitário\'},{id:\'orientacao\',label:\'Orientação\'}];\n  const lista = COMUNICADOS.filter(c=> comFiltro.cat===\'todas\' || c.cat===comFiltro.cat);\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Comunicação oficial</span><h1>Comunicados da Farmácia</h1><p>Publicações oficiais sobre protocolos, padronização, desabastecimentos e alertas sanitários.</p></div>\n    </div>\n    <div class=\"filter-row\">\n      ${cats.map(c=>`<button class=\"chip ${comFiltro.cat===c.id?\'active\':\'\'}\" data-comcat=\"${c.id}\">${c.label}</button>`).join(\'\')}\n    </div>\n    <div id=\"comList\">\n      ${lista.length? lista.map(c=>`\n        <div class=\"card com-card\" data-comid=\"${c.id}\">\n          <div class=\"com-card-top\">\n            <span class=\"tag ${catTagClass(c.cat)}\">${c.catLabel}</span>\n            <span class=\"com-card-date mono\">${c.data}</span>\n          </div>\n          <h3>${c.titulo}</h3>\n          <p>${c.resumo}</p>\n          <div class=\"com-card-foot\">\n            <button class=\"btn btn-ghost\" data-comid=\"${c.id}\">Ler comunicado completo →</button>\n            ${c.anexo? `<span class=\"anexo-link\">${ic(\'paperclip\')} ${c.anexo}</span>` : \'\'}\n          </div>\n        </div>\n      `).join(\'\') : `<div class=\"empty\">Nenhum comunicado nesta categoria.</div>`}\n    </div>\n  `;\n}\n\nfunction renderPops(){\n  const lista = POPS.filter(p=>{\n    const matchCat = popFiltro.cat===\'todas\' || p.cat===popFiltro.cat;\n    const q = popFiltro.q.trim().toLowerCase();\n    const matchQ = !q || p.titulo.toLowerCase().includes(q) || p.codigo.toLowerCase().includes(q);\n    return matchCat && matchQ;\n  });\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Documentação técnica</span><h1>Biblioteca de POPs e Protocolos</h1><p>Procedimentos Operacionais Padrão vigentes, organizados por categoria e com controle de versão.</p></div>\n    </div>\n    <div class=\"lib-toolbar\">\n      <div class=\"search\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n        <input id=\"popSearch\" placeholder=\"Buscar por título ou código…\" value=\"${popFiltro.q}\">\n      </div>\n    </div>\n    <div class=\"filter-row\">\n      ${POP_CATEGORIAS.map(c=>`<button class=\"chip ${popFiltro.cat===c.id?\'active\':\'\'}\" data-popcat=\"${c.id}\">${c.label}</button>`).join(\'\')}\n    </div>\n    <div id=\"popList\">\n      ${lista.length? lista.map(p=>`\n        <div class=\"card pop-card\">\n          <div class=\"pop-card-tab\"></div>\n          <div class=\"pop-card-body\">\n            <div class=\"pop-card-code mono\">${p.codigo}<span class=\"ver\">${p.versao}</span></div>\n            <div class=\"pop-card-main\">\n              <h3>${p.titulo}</h3>\n              <div class=\"pop-card-main-meta\">\n                <span class=\"tag tag-orientacao\">${p.catLabel}</span>\n                <span class=\"mono\">Atualizado em ${p.data}</span>\n              </div>\n            </div>\n            <div class=\"pop-card-actions\">\n              <button class=\"btn btn-primary\" onclick=\"alert(\'Download de exemplo — conecte este botão ao arquivo real do POP (PDF).\')\">${ic(\'download\')} PDF</button>\n            </div>\n          </div>\n        </div>\n      `).join(\'\') : `<div class=\"empty\">Nenhum POP encontrado para esta busca.</div>`}\n    </div>\n  `;\n}\n\nfunction renderTreinamentos(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Educação continuada</span><h1>Treinamentos da Farmácia Hospitalar</h1><p>Capacitações sobre uso seguro de medicamentos, com vídeo, material de apoio e avaliação.</p></div>\n    </div>\n    <div class=\"grid grid-2\">\n      ${TREINAMENTOS.map(t=>`\n        <div class=\"card train-card\">\n          <div class=\"train-thumb\">${ic(\'film\')}<span class=\"dur mono\">${t.duracao}</span></div>\n          <div class=\"train-body\">\n            <h3>${t.titulo}</h3>\n            <p>${t.desc}</p>\n            <div class=\"train-audience\">${ic(\'cap\')} Público-alvo: ${t.publico}</div>\n            <div class=\"train-actions\">\n              <button class=\"btn btn-primary\" onclick=\"alert(\'Player de exemplo — incorpore aqui o vídeo do YouTube privado ou Google Drive.\')\">${ic(\'film\')} Assistir</button>\n              <button class=\"btn\" onclick=\"alert(\'Material de apoio em PDF — anexe aqui o arquivo real.\')\">${ic(\'download\')} Material</button>\n              <button class=\"btn\" onclick=\"alert(\'Questionário de avaliação — conecte aqui o Google Forms do treinamento.\')\">${ic(\'check\')} Avaliação</button>\n            </div>\n          </div>\n        </div>\n      `).join(\'\')}\n    </div>\n  `;\n}\n\nfunction renderPadronizacao(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Padronização institucional</span><h1>Padronização de Medicamentos</h1><p>Lista vigente, atualizações recentes e notas técnicas da Comissão de Farmácia e Terapêutica.</p></div>\n    </div>\n    <div class=\"card\" style=\"margin-bottom:20px;\">\n      <div class=\"table-wrap\">\n        <table class=\"std-table\">\n          <thead><tr><th>Medicamento</th><th>Classe</th><th>Apresentação</th><th>Status</th></tr></thead>\n          <tbody>\n            ${MEDICAMENTOS_PADRONIZADOS.map(m=>`\n              <tr>\n                <td><strong>${m.nome}</strong></td>\n                <td>${m.classe}</td>\n                <td>${m.apresentacao}</td>\n                <td><span class=\"status-dot status-${m.status}\">${m.status===\'padronizado\'?\'Padronizado\':\'Alternativa em uso\'}</span></td>\n              </tr>\n            `).join(\'\')}\n          </tbody>\n        </table>\n      </div>\n    </div>\n    <div class=\"grid grid-2\">\n      <div class=\"card\" style=\"padding:18px;\">\n        <div class=\"section-title\">${ic(\'pill\')} Atualizações recentes</div>\n        ${ATUALIZACOES_PADRONIZACAO.map(a=>`\n          <div class=\"list-item\"><div class=\"list-item-icon\">${ic(\'pill\')}</div>\n            <div class=\"list-item-body\"><div class=\"list-item-title\">${a.tipo}</div><div class=\"list-item-meta\">${a.item}<br><span class=\"mono\">${a.data}</span></div></div>\n          </div>\n        `).join(\'\')}\n      </div>\n      <div class=\"card\" style=\"padding:18px;\">\n        <div class=\"section-title\">${ic(\'book\')} Notas técnicas farmacêuticas</div>\n        ${NOTAS_TECNICAS.map(n=>`\n          <div class=\"list-item\"><div class=\"list-item-icon\">${ic(\'book\')}</div>\n            <div class=\"list-item-body\"><div class=\"list-item-title\">${n.titulo}</div><div class=\"list-item-meta\"><span class=\"mono\">${n.data}</span></div></div>\n          </div>\n        `).join(\'\')}\n      </div>\n    </div>\n  `;\n}\n\nfunction renderSeguranca(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Segurança do paciente</span><h1>Segurança do Paciente — Farmácia</h1><p>Conteúdo crítico sobre medicamentos LASA, alta vigilância e prevenção de erros de medicação.</p></div>\n    </div>\n\n    <div class=\"section-title\">${ic(\'alert\')} Medicamentos com nome ou aparência semelhante (LASA)</div>\n    <div style=\"margin-bottom:26px;\">\n      ${LASA_PARES.map(l=>`\n        <div class=\"card lasa-pair\">\n          <span class=\"lasa-word\">${l.a}</span><span class=\"lasa-vs\">vs</span><span class=\"lasa-word\">${l.b}</span>\n          <span class=\"lasa-note\">${l.nota}</span>\n        </div>\n      `).join(\'\')}\n    </div>\n\n    <div class=\"grid grid-2\" style=\"margin-bottom:26px;\">\n      <div>\n        <div class=\"section-title\">${ic(\'shield\')} Medicamentos de alta vigilância</div>\n        <div class=\"vigilancia-grid\">\n          ${ALTA_VIGILANCIA.map(v=>`<div class=\"card vigilancia-item\">${ic(\'alert\')}<span>${v}</span></div>`).join(\'\')}\n        </div>\n      </div>\n      <div>\n        <div class=\"section-title\">${ic(\'check\')} Protocolo de dupla checagem</div>\n        <div class=\"card\" style=\"padding: 6px 20px;\">\n          <div class=\"check-steps\">\n            ${CHECAGEM_DUPLA.map((c,i)=>`\n              <div class=\"check-step\">\n                <div class=\"check-step-num\">${i+1}</div>\n                <div class=\"check-step-text\"><strong>${c.titulo}</strong><span>${c.texto}</span></div>\n              </div>\n            `).join(\'\')}\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\" style=\"padding:20px; display:flex; gap:16px; align-items:center; flex-wrap:wrap;\">\n      <div style=\"flex:1; min-width:220px;\">\n        <div class=\"section-title\" style=\"margin-bottom:6px;\">${ic(\'bell\')} Identificou um erro de medicação ou evento adverso?</div>\n        <p style=\"font-size:12.5px; color:var(--gray);\">A notificação é essencial para a melhoria contínua dos processos. Não é necessário identificar o profissional.</p>\n      </div>\n      <button class=\"btn btn-primary\" data-go=\"contato\">${ic(\'send\')} Notificar evento</button>\n    </div>\n  `;\n}\n\nfunction renderFluxos(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Processos operacionais</span><h1>Fluxos e Processos da Farmácia</h1><p>Etapas padronizadas para solicitações, devoluções, ajustes de estoque e atendimentos especiais.</p></div>\n    </div>\n    <div id=\"flowList\">\n      ${FLUXOS.map((f,i)=>`\n        <div class=\"card flow-acc ${i===0?\'open\':\'\'}\" data-flow=\"${i}\">\n          <button class=\"flow-acc-head\" data-flowtoggle=\"${i}\">\n            <span class=\"num mono\">0${i+1}</span>\n            <h3>${f.titulo}</h3>\n            ${ic(\'chev\')}\n          </button>\n          <div class=\"flow-acc-body\">\n            <div class=\"flow-steps\">\n              ${f.passos.map((p,j)=>`\n                <div class=\"flow-step\">\n                  <div class=\"flow-step-inner\">\n                    <div class=\"flow-step-num mono\">${j+1}</div>\n                    <div class=\"flow-step-title\">${p.t}</div>\n                    <div class=\"flow-step-text\">${p.d}</div>\n                  </div>\n                </div>\n                ${j<f.passos.length-1? `<div class=\"flow-arrow\">${ic(\'chev\')}</div>` : \'\'}\n              `).join(\'\')}\n            </div>\n          </div>\n        </div>\n      `).join(\'\')}\n    </div>\n  `;\n}\n\nfunction renderContato(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Canal direto</span><h1>Contato e Solicitações</h1><p>Solicite medicamentos, tire dúvidas técnicas ou notifique problemas diretamente à Farmácia Hospitalar.</p></div>\n    </div>\n    <div class=\"contact-grid\">\n      <div class=\"card form-card\">\n        <div class=\"confirm-box\" id=\"confirmBox\">\n          ${ic(\'check\')}\n          <div><strong>Solicitação registrada</strong><span>Este é um formulário de demonstração — conecte-o ao seu sistema real de chamados ou e-mail institucional.</span></div>\n        </div>\n        <form id=\"contactForm\">\n          <div class=\"field-row\">\n            <div class=\"field\"><label>Nome completo</label><input required placeholder=\"Seu nome\"></div>\n            <div class=\"field\"><label>Setor</label><input required placeholder=\"Ex.: UTI Adulto\"></div>\n          </div>\n          <div class=\"field\">\n            <label>Tipo de solicitação</label>\n            <select>\n              <option>Solicitação de medicamento não padronizado</option>\n              <option>Dúvida técnica</option>\n              <option>Sugestão</option>\n              <option>Notificação de problema / evento adverso</option>\n            </select>\n          </div>\n          <div class=\"field\"><label>Mensagem</label><textarea required placeholder=\"Descreva sua solicitação com o máximo de detalhes possível…\"></textarea></div>\n          <button class=\"btn btn-primary btn-block\" type=\"submit\">${ic(\'send\')} Enviar solicitação</button>\n        </form>\n      </div>\n      <div class=\"card\" style=\"padding:22px 24px;\">\n        <div class=\"section-title\" style=\"margin-bottom:16px;\">Canais diretos</div>\n        <div class=\"contact-info-item\">${ic(\'phone\')}<div><strong>Ramal da Farmácia Central</strong><span>Ramal 4521 — dias úteis, 7h às 19h</span></div></div>\n        <div class=\"contact-info-item\">${ic(\'mail\')}<div><strong>E-mail institucional</strong><span>farmacia.hospitalar@hospitalsantalucia.exemplo</span></div></div>\n        <div class=\"contact-info-item\">${ic(\'clock\')}<div><strong>Plantão farmacêutico</strong><span>24 horas, todos os dias, via ramal de urgência 4599</span></div></div>\n        <div class=\"contact-info-item\">${ic(\'pin\')}<div><strong>Localização</strong><span>Farmácia Central — Bloco A, térreo</span></div></div>\n      </div>\n    </div>\n  `;\n}\n\nconst RENDERERS = {\n  home: renderHome, comunicados: renderComunicados, pops: renderPops,\n  treinamentos: renderTreinamentos, padronizacao: renderPadronizacao,\n  seguranca: renderSeguranca, fluxos: renderFluxos, contato: renderContato,\n};\n\nfunction navigate(view){\n  if(!RENDERERS[view]) return;\n  currentView = view;\n  document.getElementById(\'content\').innerHTML = `<div class=\"view active\">${RENDERERS[view]()}</div>`;\n  renderNav();\n  bindViewEvents(view);\n  document.getElementById(\'content\').scrollTop = 0;\n  window.scrollTo(0,0);\n}\n\nfunction bindViewEvents(view){\n  document.querySelectorAll(\'[data-go]\').forEach(el=> el.addEventListener(\'click\', ()=> navigate(el.dataset.go)));\n\n  if(view===\'comunicados\'){\n    document.querySelectorAll(\'[data-comcat]\').forEach(el=> el.addEventListener(\'click\', ()=>{ comFiltro.cat = el.dataset.comcat; navigate(\'comunicados\'); }));\n    document.querySelectorAll(\'[data-comid]\').forEach(el=> el.addEventListener(\'click\', ()=> openComunicado(el.dataset.comid)));\n  }\n  if(view===\'pops\'){\n    document.querySelectorAll(\'[data-popcat]\').forEach(el=> el.addEventListener(\'click\', ()=>{ popFiltro.cat = el.dataset.popcat; navigate(\'pops\'); }));\n    const input = document.getElementById(\'popSearch\');\n    if(input){\n      input.addEventListener(\'input\', ()=>{\n        const pos = input.selectionStart;\n        popFiltro.q = input.value;\n        navigate(\'pops\');\n        const newInput = document.getElementById(\'popSearch\');\n        newInput.focus();\n        newInput.setSelectionRange(pos,pos);\n      });\n    }\n  }\n  if(view===\'fluxos\'){\n    document.querySelectorAll(\'[data-flowtoggle]\').forEach(el=>{\n      el.addEventListener(\'click\', ()=>{\n        const card = el.closest(\'.flow-acc\');\n        card.classList.toggle(\'open\');\n      });\n    });\n  }\n  if(view===\'contato\'){\n    const form = document.getElementById(\'contactForm\');\n    form.addEventListener(\'submit\', (e)=>{\n      e.preventDefault();\n      document.getElementById(\'confirmBox\').classList.add(\'show\');\n      form.reset();\n      document.getElementById(\'confirmBox\').scrollIntoView({behavior:\'smooth\', block:\'center\'});\n    });\n  }\n}\n\nfunction openComunicado(id){\n  const c = COMUNICADOS.find(x=>x.id===id);\n  if(!c) return;\n  document.getElementById(\'modalTitle\').textContent = c.titulo;\n  document.getElementById(\'modalBody\').innerHTML = `\n    <div class=\"com-card-top\" style=\"margin-bottom:14px;\">\n      <span class=\"tag ${catTagClass(c.cat)}\">${c.catLabel}</span>\n      <span class=\"com-card-date mono\">${c.data}</span>\n    </div>\n    <div class=\"com-detail-body\">${c.corpo.split(\'\\n\\n\').map(p=>`<p>${p}</p>`).join(\'\')}</div>\n    ${c.anexo? `<div style=\"margin-top:16px;\"><span class=\"anexo-link\">${ic(\'paperclip\')} ${c.anexo}</span></div>` : \'\'}\n  `;\n  document.getElementById(\'modalScrim\').classList.add(\'show\');\n}\n\n/* =====================================================================\n   INTERAÇÕES GLOBAIS — menu mobile, busca global, modal\n   ===================================================================== */\nfunction openMobileMenu(){ document.getElementById(\'sidebar\').classList.add(\'open\'); document.getElementById(\'sidebarScrim\').classList.add(\'show\'); }\nfunction closeMobileMenu(){ document.getElementById(\'sidebar\').classList.remove(\'open\'); document.getElementById(\'sidebarScrim\').classList.remove(\'show\'); }\ndocument.getElementById(\'menuBtn\').addEventListener(\'click\', openMobileMenu);\ndocument.getElementById(\'sidebarScrim\').addEventListener(\'click\', closeMobileMenu);\n\ndocument.getElementById(\'modalClose\').addEventListener(\'click\', ()=> document.getElementById(\'modalScrim\').classList.remove(\'show\'));\ndocument.getElementById(\'modalScrim\').addEventListener(\'click\', (e)=>{ if(e.target.id===\'modalScrim\') document.getElementById(\'modalScrim\').classList.remove(\'show\'); });\ndocument.addEventListener(\'keydown\', (e)=>{ if(e.key===\'Escape\') document.getElementById(\'modalScrim\').classList.remove(\'show\'); });\n\ndocument.getElementById(\'globalSearch\').addEventListener(\'keydown\', (e)=>{\n  if(e.key===\'Enter\'){\n    const q = e.target.value.trim();\n    if(!q) return;\n    popFiltro = { cat:\'todas\', q:q };\n    navigate(\'pops\');\n  }\n});\n\n/* inicialização */\nrenderNav();\nnavigate(\'home\');\n</script>\n</body>\n</html>\n', '', '', 'publish', 'closed', 'closed', '', '9-2', '', '', '2026-09-09 13:12:21', '2026-09-09 16:12:21', '', 0, 'http://localhost/faramcia_SL/wordpress/?page_id=9', 0, 'page', '', 0);
INSERT INTO `wp_userposts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(10, 1, '2026-09-09 13:12:17', '2026-09-09 16:12:17', '<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Farmácia Hospitalar · Hospital Santa Lúcia Bauru</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Serif:wght@400;500;600;700&family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n\n/* ===================================================================\n   TOKENS — Identidade visual do Hospital Santa Lúcia Bauru\n   =================================================================== */\n:root{\n  /* paleta institucional (fixa pelo briefing) */\n  --red: #A80F14;\n  --red-deep: #7A0B0F;\n  --red-tint: #FBEAEA;\n  --gray: #666666;\n  --white: #FFFFFF;\n  --gray-light: #F5F5F5;\n\n  /* derivados de apoio — tons de \"papel\" e tinta, não decorativos */\n  --paper: #FBFAF8;\n  --ink: #262321;\n  --line: #E2DDD7;\n  --line-soft: #EEEAE5;\n\n  /* cores funcionais — usadas só para status/segurança, nunca decoração */\n  --amber: #92600A;\n  --amber-bg: #FBF1DF;\n  --green: #2E6B40;\n  --green-bg: #E9F2EA;\n\n  /* tipografia */\n  --f-display: \"IBM Plex Serif\", Georgia, serif;\n  --f-body: \"IBM Plex Sans\", -apple-system, Segoe UI, sans-serif;\n  --f-mono: \"IBM Plex Mono\", \"SFMono-Regular\", monospace;\n\n  --radius: 3px;\n  --shadow-card: 0 1px 2px rgba(38,35,33,0.06), 0 1px 1px rgba(38,35,33,0.04);\n  --shadow-pop: 0 8px 24px rgba(38,35,33,0.12);\n\n  --sidebar-w: 248px;\n}\n\n*{ box-sizing: border-box; }\nhtml{ scroll-behavior: smooth; }\nbody{\n  margin:0;\n  font-family: var(--f-body);\n  color: var(--ink);\n  background: var(--gray-light);\n  -webkit-font-smoothing: antialiased;\n}\nh1,h2,h3,h4{ font-family: var(--f-display); margin:0; line-height:1.2; font-weight:600; }\np{ margin:0; }\na{ color: var(--red); text-decoration: none; }\nbutton{ font-family: var(--f-body); cursor:pointer; }\n:focus-visible{ outline: 2px solid var(--red); outline-offset: 2px; }\n.mono{ font-family: var(--f-mono); }\n\n@media (prefers-reduced-motion: reduce){\n  *{ animation-duration: 0.001ms !important; transition-duration: 0.001ms !important; scroll-behavior:auto !important; }\n}\n\n/* ===================================================================\n   SELO — elemento de assinatura visual do portal\n   Inspirado no carimbo oficial de validação de documentos hospitalares.\n   =================================================================== */\n.selo{\n  --size: 92px;\n  width: var(--size); height: var(--size);\n  border-radius: 50%;\n  border: 2px solid currentColor;\n  display:flex; align-items:center; justify-content:center;\n  position: relative;\n  transform: rotate(-9deg);\n  flex-shrink:0;\n  color: var(--red);\n}\n.selo::before{\n  content:\"\";\n  position:absolute; inset:6px;\n  border: 1px dashed currentColor;\n  border-radius:50%;\n  opacity:0.55;\n}\n.selo-texto{\n  font-family: var(--f-mono);\n  font-size: 8.5px;\n  font-weight:600;\n  letter-spacing: 0.5px;\n  text-align:center;\n  text-transform: uppercase;\n  line-height:1.25;\n  padding: 0 10px;\n}\n.selo.selo-sm{ --size: 44px; }\n.selo.selo-sm .selo-texto{ font-size: 5.6px; padding:0 5px; }\n.selo.selo-ghost{ color: var(--gray); opacity:0.65; }\n\n/* ===================================================================\n   LAYOUT GERAL\n   =================================================================== */\n.app{\n  display:flex;\n  min-height:100vh;\n}\n\n/* ---------- SIDEBAR ---------- */\n.sidebar{\n  width: var(--sidebar-w);\n  flex-shrink:0;\n  background: var(--ink);\n  color: var(--white);\n  display:flex;\n  flex-direction:column;\n  position: fixed;\n  top:0; left:0; bottom:0;\n  z-index: 40;\n  transition: transform .25s ease;\n}\n.sidebar-brand{\n  padding: 22px 20px 18px;\n  border-bottom: 1px solid rgba(255,255,255,0.12);\n  display:flex; align-items:center; gap:12px;\n}\n.sidebar-brand .selo{ color: var(--white); }\n.sidebar-brand-text{ font-family: var(--f-display); line-height:1.25; }\n.sidebar-brand-text strong{ display:block; font-size:14.5px; font-weight:600; }\n.sidebar-brand-text span{ display:block; font-size:11px; color: rgba(255,255,255,0.6); font-family: var(--f-body); margin-top:2px; }\n\n.nav{ flex:1; padding: 10px 12px; display:flex; flex-direction:column; gap:2px; overflow-y:auto; }\n.nav-item{\n  display:flex; align-items:center; gap:11px;\n  padding: 10px 12px;\n  border-radius: var(--radius);\n  color: rgba(255,255,255,0.72);\n  font-size: 13.5px;\n  font-weight:500;\n  background:none; border:none; text-align:left; width:100%;\n  transition: background .15s, color .15s;\n}\n.nav-item svg{ width:17px; height:17px; flex-shrink:0; opacity:0.9; }\n.nav-item:hover{ background: rgba(255,255,255,0.07); color: var(--white); }\n.nav-item.active{ background: var(--red); color: var(--white); }\n.nav-item .badge{\n  margin-left:auto;\n  font-family: var(--f-mono);\n  font-size: 10px;\n  background: rgba(255,255,255,0.14);\n  padding: 1px 6px;\n  border-radius: 10px;\n}\n.nav-item.active .badge{ background: rgba(255,255,255,0.25); }\n\n.sidebar-foot{\n  padding: 14px 20px 18px;\n  border-top: 1px solid rgba(255,255,255,0.12);\n  font-size: 11px;\n  color: rgba(255,255,255,0.5);\n  line-height:1.6;\n}\n\n/* ---------- TOPBAR (mobile) ---------- */\n.topbar{\n  display:none;\n  position: sticky; top:0; z-index:30;\n  background: var(--ink); color:var(--white);\n  align-items:center; gap:12px;\n  padding: 13px 16px;\n}\n.topbar button{\n  background:none; border:none; color:var(--white);\n  width:32px;height:32px; display:flex; align-items:center; justify-content:center;\n}\n.topbar .selo{ --size:32px; color:var(--white); }\n.topbar .selo .selo-texto{ font-size:4px; }\n.topbar-title{ font-family: var(--f-display); font-size:14px; font-weight:600; }\n\n.sidebar-scrim{ display:none; }\n\n/* ---------- MAIN ---------- */\n.main{\n  margin-left: var(--sidebar-w);\n  flex:1;\n  min-width:0;\n  display:flex; flex-direction:column;\n}\n.topstrip{\n  background: var(--white);\n  border-bottom: 1px solid var(--line);\n  padding: 16px 36px;\n  display:flex; align-items:center; gap:18px;\n  position: sticky; top:0; z-index:20;\n}\n.search{\n  flex:1; max-width: 480px;\n  display:flex; align-items:center; gap:9px;\n  background: var(--gray-light);\n  border:1px solid var(--line);\n  border-radius: var(--radius);\n  padding: 9px 13px;\n}\n.search svg{ width:15px; height:15px; color: var(--gray); flex-shrink:0; }\n.search input{\n  border:none; background:none; outline:none; width:100%;\n  font-size:13.5px; font-family:var(--f-body); color:var(--ink);\n}\n.topstrip-meta{\n  margin-left:auto;\n  display:flex; align-items:center; gap:16px;\n  font-size:12.5px; color:var(--gray);\n}\n.pill-status{\n  display:flex; align-items:center; gap:6px;\n  font-family: var(--f-mono); font-size:11.5px;\n  color: var(--green);\n  background: var(--green-bg);\n  padding: 5px 10px; border-radius: 20px;\n}\n.pill-status::before{ content:\"\"; width:6px;height:6px;border-radius:50%; background:currentColor; }\n\n.content{\n  flex:1;\n  padding: 32px 36px 64px;\n  max-width: 1180px;\n}\n\n.view{ display:none; animation: fadein .35s ease; }\n.view.active{ display:block; }\n@keyframes fadein{ from{opacity:0; transform:translateY(4px);} to{opacity:1; transform:translateY(0);} }\n\n.page-head{\n  display:flex; align-items:flex-end; justify-content:space-between; gap:20px;\n  margin-bottom: 28px;\n  padding-bottom: 18px;\n  border-bottom: 1px solid var(--line);\n}\n.page-head .eyebrow{\n  font-family: var(--f-mono); font-size:11px; letter-spacing:1px;\n  color: var(--red); text-transform:uppercase; margin-bottom:6px; display:block;\n}\n.page-head h1{ font-size: 26px; }\n.page-head p{ color: var(--gray); font-size: 13.5px; margin-top:6px; max-width:560px; }\n\n/* ===================================================================\n   COMPONENTES REUTILIZÁVEIS\n   =================================================================== */\n.card{\n  background: var(--white);\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  box-shadow: var(--shadow-card);\n}\n.grid{ display:grid; gap:18px; }\n.grid-2{ grid-template-columns: repeat(2,1fr); }\n.grid-3{ grid-template-columns: repeat(3,1fr); }\n.grid-4{ grid-template-columns: repeat(4,1fr); }\n\n.section-title{\n  display:flex; align-items:center; gap:9px;\n  font-size: 14px; font-weight:600; font-family: var(--f-display);\n  margin-bottom:14px;\n}\n.section-title svg{ width:16px;height:16px; color:var(--red); }\n.section-title .ver-tudo{\n  margin-left:auto; font-family:var(--f-body); font-size:12px; font-weight:500; color:var(--red);\n}\n\n.tag{\n  display:inline-flex; align-items:center; gap:5px;\n  font-size: 10.5px; font-weight:600; text-transform:uppercase; letter-spacing:.4px;\n  padding: 3px 8px; border-radius: 20px;\n  font-family: var(--f-body);\n}\n.tag-protocolo{ background:var(--red-tint); color:var(--red-deep); }\n.tag-padronizacao{ background:var(--green-bg); color:var(--green); }\n.tag-desabastecimento{ background:var(--amber-bg); color:var(--amber); }\n.tag-alerta{ background:#2A2A2A; color:#fff; }\n.tag-orientacao{ background:var(--gray-light); color:var(--gray); border:1px solid var(--line); }\n\n.btn{\n  display:inline-flex; align-items:center; gap:7px;\n  font-size:12.5px; font-weight:600;\n  padding: 8px 14px; border-radius: var(--radius);\n  border: 1px solid var(--line);\n  background: var(--white); color: var(--ink);\n  transition: border-color .15s, background .15s;\n}\n.btn svg{ width:13px;height:13px; }\n.btn:hover{ border-color: var(--gray); }\n.btn-primary{ background: var(--red); border-color:var(--red); color:var(--white); }\n.btn-primary:hover{ background: var(--red-deep); border-color:var(--red-deep); }\n.btn-block{ width:100%; justify-content:center; }\n.btn-ghost{ border-color:transparent; padding-left:4px; padding-right:4px; }\n\n.empty{\n  text-align:center; padding: 38px 20px; color: var(--gray); font-size:13px;\n}\n\n/* ===================================================================\n   DASHBOARD\n   =================================================================== */\n.hero-stamp{\n  display:flex; align-items:center; gap:22px;\n  background: var(--ink);\n  color: var(--white);\n  border-radius: var(--radius);\n  padding: 26px 30px;\n  margin-bottom: 26px;\n  position:relative;\n  overflow:hidden;\n}\n.hero-stamp::after{\n  content:\"\";\n  position:absolute; right:-40px; top:-60px;\n  width:220px; height:220px;\n  border:1px dashed rgba(255,255,255,0.08);\n  border-radius:50%;\n}\n.hero-stamp .selo{ color:var(--white); --size:78px; }\n.hero-stamp-text .eyebrow{ font-family:var(--f-mono); font-size:11px; letter-spacing:1px; color:#E7A6A8; text-transform:uppercase; }\n.hero-stamp-text h1{ font-size:21px; margin-top:6px; }\n.hero-stamp-text p{ font-size:13px; color:rgba(255,255,255,0.68); margin-top:7px; max-width:520px; }\n\n.kpi-row{ margin-bottom:26px; }\n.kpi{ padding: 16px 18px; }\n.kpi .kpi-num{ font-family:var(--f-display); font-size:25px; font-weight:600; }\n.kpi .kpi-label{ font-size:11.5px; color:var(--gray); margin-top:4px; line-height:1.4; }\n.kpi .kpi-trend{ font-family:var(--f-mono); font-size:10.5px; margin-top:8px; display:inline-block; padding:2px 7px; border-radius:10px; }\n.trend-up{ background:var(--green-bg); color:var(--green); }\n.trend-flat{ background:var(--gray-light); color:var(--gray); }\n.trend-warn{ background:var(--amber-bg); color:var(--amber); }\n\n.dash-grid{ display:grid; grid-template-columns: 1.3fr 1fr; gap:20px; margin-bottom:20px; }\n.dash-col{ display:flex; flex-direction:column; gap:20px; }\n\n.list-item{\n  display:flex; gap:13px; padding: 13px 16px;\n  border-bottom: 1px solid var(--line-soft);\n}\n.list-item:last-child{ border-bottom:none; }\n.list-item-icon{\n  width:30px;height:30px; border-radius:50%; flex-shrink:0;\n  display:flex; align-items:center; justify-content:center;\n  background: var(--red-tint); color:var(--red);\n}\n.list-item-icon svg{ width:14px;height:14px; }\n.list-item-body{ flex:1; min-width:0; }\n.list-item-title{ font-size:13px; font-weight:600; line-height:1.35; }\n.list-item-meta{ font-size:11px; color:var(--gray); margin-top:4px; display:flex; gap:8px; align-items:center; flex-wrap:wrap; }\n\n.alert-row{\n  display:flex; gap:12px; align-items:flex-start;\n  padding: 13px 16px;\n  border-left: 3px solid var(--amber);\n  background: var(--amber-bg);\n  border-radius: 0 var(--radius) var(--radius) 0;\n  margin-bottom:10px;\n}\n.alert-row.crit{ border-left-color: var(--red); background: var(--red-tint); }\n.alert-row svg{ width:16px;height:16px; flex-shrink:0; margin-top:1px; color:var(--amber); }\n.alert-row.crit svg{ color:var(--red); }\n.alert-row-title{ font-size:12.5px; font-weight:600; }\n.alert-row-text{ font-size:11.5px; color:var(--gray); margin-top:3px; line-height:1.45; }\n\n/* ===================================================================\n   COMUNICADOS\n   =================================================================== */\n.filter-row{ display:flex; gap:8px; margin-bottom:20px; flex-wrap:wrap; align-items:center; }\n.chip{\n  font-size:12px; font-weight:500; padding:7px 13px;\n  border-radius:20px; border:1px solid var(--line); background:var(--white); color:var(--gray);\n}\n.chip.active{ background: var(--ink); border-color:var(--ink); color:var(--white); }\n\n.com-card{ padding: 18px 20px; margin-bottom:14px; cursor:pointer; }\n.com-card-top{ display:flex; align-items:center; gap:10px; margin-bottom:8px; flex-wrap:wrap; }\n.com-card-date{ font-family:var(--f-mono); font-size:11px; color:var(--gray); }\n.com-card h3{ font-size:15px; margin-bottom:6px; }\n.com-card p{ font-size:13px; color:var(--gray); line-height:1.55; }\n.com-card-foot{ margin-top:12px; display:flex; align-items:center; gap:14px; }\n.anexo-link{ display:flex; align-items:center; gap:6px; font-size:12px; font-weight:600; color:var(--red); }\n.anexo-link svg{ width:13px;height:13px; }\n\n.com-detail-body{ font-size:13.5px; line-height:1.7; color:var(--ink); }\n.com-detail-body p{ margin-bottom:12px; }\n\n/* ===================================================================\n   POPs — biblioteca em formato de \"ficha de documento\"\n   =================================================================== */\n.lib-toolbar{ display:flex; gap:10px; margin-bottom:18px; flex-wrap:wrap; }\n.lib-toolbar .search{ max-width:340px; }\n\n.pop-card{\n  display:flex; gap:0; overflow:hidden; margin-bottom:12px;\n}\n.pop-card-tab{\n  width:6px; background: var(--red); flex-shrink:0;\n}\n.pop-card-body{ padding:16px 18px; flex:1; display:flex; gap:16px; align-items:flex-start; }\n.pop-card-code{\n  font-family:var(--f-mono); font-size:12px; color:var(--gray);\n  background:var(--gray-light); padding:8px 10px; border-radius:var(--radius);\n  text-align:center; flex-shrink:0; min-width:108px;\n}\n.pop-card-code .ver{ display:block; margin-top:4px; font-weight:600; color:var(--red); }\n.pop-card-main{ flex:1; min-width:0; }\n.pop-card-main h3{ font-size:14.5px; margin-bottom:5px; }\n.pop-card-main-meta{ font-size:11.5px; color:var(--gray); display:flex; gap:12px; flex-wrap:wrap; margin-top:6px; }\n.pop-card-actions{ display:flex; gap:8px; flex-shrink:0; align-self:center; }\n\n/* ===================================================================\n   TREINAMENTOS\n   =================================================================== */\n.train-card{ overflow:hidden; }\n.train-thumb{\n  height: 108px;\n  background: linear-gradient(135deg, var(--ink), #3a3431);\n  display:flex; align-items:center; justify-content:center;\n  position:relative;\n}\n.train-thumb svg{ width:30px; height:30px; color: rgba(255,255,255,0.85); }\n.train-thumb .dur{\n  position:absolute; bottom:8px; right:10px;\n  font-family:var(--f-mono); font-size:10.5px; color:#fff;\n  background: rgba(0,0,0,0.45); padding:2px 7px; border-radius:10px;\n}\n.train-body{ padding:16px 18px; }\n.train-body h3{ font-size:14px; margin-bottom:7px; }\n.train-body p{ font-size:12.5px; color:var(--gray); line-height:1.55; margin-bottom:12px; }\n.train-audience{ font-size:11px; color:var(--gray); margin-bottom:14px; display:flex; gap:6px; align-items:center; }\n.train-actions{ display:flex; gap:8px; flex-wrap:wrap; }\n.train-actions .btn{ flex:1; justify-content:center; }\n\n/* ===================================================================\n   PADRONIZAÇÃO\n   =================================================================== */\n.table-wrap{ overflow-x:auto; }\ntable.std-table{ width:100%; border-collapse:collapse; font-size:13px; }\ntable.std-table th{\n  text-align:left; font-size:11px; text-transform:uppercase; letter-spacing:.4px;\n  color:var(--gray); padding:11px 16px; border-bottom:1px solid var(--line); font-weight:600;\n}\ntable.std-table td{ padding:13px 16px; border-bottom:1px solid var(--line-soft); }\ntable.std-table tr:last-child td{ border-bottom:none; }\n.status-dot{ display:inline-flex; align-items:center; gap:6px; font-size:12px; font-weight:600; }\n.status-dot::before{ content:\"\"; width:7px;height:7px;border-radius:50%; }\n.status-padronizado::before{ background:var(--green); }\n.status-padronizado{ color:var(--green); }\n.status-alternativa::before{ background:var(--amber); }\n.status-alternativa{ color:var(--amber); }\n\n/* ===================================================================\n   SEGURANÇA DO PACIENTE\n   =================================================================== */\n.lasa-pair{\n  display:flex; align-items:center; gap:14px; padding:15px 18px; margin-bottom:10px;\n}\n.lasa-word{ font-family:var(--f-display); font-weight:700; font-size:16px; }\n.lasa-word .hl{ background: #FCE4A6; padding:0 2px; border-radius:2px; }\n.lasa-vs{ font-family:var(--f-mono); font-size:11px; color:var(--gray); }\n.lasa-note{ margin-left:auto; font-size:11.5px; color:var(--gray); max-width:280px; text-align:right; }\n\n.vigilancia-grid{ display:grid; grid-template-columns:repeat(2,1fr); gap:10px; }\n.vigilancia-item{\n  display:flex; align-items:center; gap:10px; padding:13px 15px;\n  border-left:3px solid var(--red);\n}\n.vigilancia-item svg{ width:16px;height:16px; color:var(--red); flex-shrink:0; }\n.vigilancia-item span{ font-size:13px; font-weight:600; }\n\n.check-steps{ display:flex; flex-direction:column; gap:0; }\n.check-step{ display:flex; gap:14px; padding:14px 0; border-bottom:1px solid var(--line-soft); }\n.check-step:last-child{ border-bottom:none; }\n.check-step-num{\n  font-family:var(--f-mono); font-weight:600; font-size:12px;\n  width:26px; height:26px; border-radius:50%; background:var(--ink); color:#fff;\n  display:flex; align-items:center; justify-content:center; flex-shrink:0;\n}\n.check-step-text strong{ display:block; font-size:13px; margin-bottom:2px; }\n.check-step-text span{ font-size:12px; color:var(--gray); }\n\n/* ===================================================================\n   FLUXOS — diagramas em sequência (numerados, pois SÃO sequências reais)\n   =================================================================== */\n.flow-acc{ margin-bottom:12px; }\n.flow-acc-head{\n  display:flex; align-items:center; gap:13px; padding:16px 20px;\n  width:100%; background:none; border:none; text-align:left;\n}\n.flow-acc-head .num{ font-family:var(--f-mono); font-size:12px; color:var(--gray); }\n.flow-acc-head h3{ font-size:14.5px; flex:1; }\n.flow-acc-head svg{ width:15px;height:15px; color:var(--gray); transition:transform .2s; flex-shrink:0; }\n.flow-acc.open .flow-acc-head svg{ transform: rotate(180deg); }\n.flow-acc-body{ display:none; padding: 0 22px 20px 22px; }\n.flow-acc.open .flow-acc-body{ display:block; }\n\n.flow-steps{ display:flex; gap:0; overflow-x:auto; padding-top:6px; padding-bottom:8px; }\n.flow-step{ display:flex; align-items:flex-start; flex-shrink:0; min-width:168px; }\n.flow-step-inner{ padding-right:18px; }\n.flow-step-num{\n  font-family:var(--f-mono); font-size:11px; color:var(--white); background:var(--red);\n  width:22px; height:22px; border-radius:50%; display:flex; align-items:center; justify-content:center; margin-bottom:8px;\n}\n.flow-step-title{ font-size:12.5px; font-weight:600; line-height:1.4; }\n.flow-step-text{ font-size:11.5px; color:var(--gray); margin-top:4px; line-height:1.45; }\n.flow-arrow{ color:var(--line); margin: 0 4px; padding-top:5px; flex-shrink:0; }\n.flow-arrow svg{ width:16px;height:16px; }\n\n/* ===================================================================\n   CONTATO\n   =================================================================== */\n.contact-grid{ display:grid; grid-template-columns: 1.4fr 1fr; gap:22px; }\n.form-card{ padding:24px; }\n.field{ margin-bottom:16px; }\n.field label{ display:block; font-size:12px; font-weight:600; margin-bottom:6px; }\n.field input, .field select, .field textarea{\n  width:100%; padding:10px 12px; border:1px solid var(--line); border-radius:var(--radius);\n  font-family:var(--f-body); font-size:13px; background:var(--white); color:var(--ink);\n}\n.field textarea{ resize:vertical; min-height:90px; }\n.field input:focus, .field select:focus, .field textarea:focus{ outline:2px solid var(--red); outline-offset:0; border-color:var(--red); }\n.field-row{ display:grid; grid-template-columns:1fr 1fr; gap:14px; }\n\n.contact-info-item{ display:flex; gap:12px; padding:15px 0; border-bottom:1px solid var(--line-soft); }\n.contact-info-item:last-child{ border-bottom:none; }\n.contact-info-item svg{ width:16px;height:16px; color:var(--red); flex-shrink:0; margin-top:2px; }\n.contact-info-item strong{ display:block; font-size:12.5px; margin-bottom:2px; }\n.contact-info-item span{ font-size:12px; color:var(--gray); line-height:1.5; }\n\n.confirm-box{\n  display:none; align-items:flex-start; gap:12px;\n  background:var(--green-bg); border-left:3px solid var(--green);\n  padding:14px 16px; border-radius:0 var(--radius) var(--radius) 0; margin-bottom:16px;\n}\n.confirm-box.show{ display:flex; }\n.confirm-box svg{ width:17px;height:17px; color:var(--green); flex-shrink:0; margin-top:1px; }\n.confirm-box strong{ font-size:13px; display:block; }\n.confirm-box span{ font-size:12px; color:var(--gray); }\n\n/* ===================================================================\n   MODAL (detalhe de comunicado)\n   =================================================================== */\n.modal-scrim{\n  position:fixed; inset:0; background:rgba(38,35,33,0.55); z-index:60;\n  display:none; align-items:center; justify-content:center; padding:24px;\n}\n.modal-scrim.show{ display:flex; }\n.modal-box{\n  background:var(--white); border-radius:var(--radius); max-width:560px; width:100%;\n  max-height:85vh; overflow-y:auto; box-shadow: var(--shadow-pop);\n}\n.modal-head{ padding:22px 24px 16px; border-bottom:1px solid var(--line); display:flex; gap:16px; align-items:flex-start; }\n.modal-head h2{ font-size:17px; flex:1; }\n.modal-close{ background:none; border:none; color:var(--gray); width:28px; height:28px; flex-shrink:0; }\n.modal-close svg{ width:18px;height:18px; }\n.modal-body{ padding:20px 24px 26px; }\n\n/* ===================================================================\n   RESPONSIVO\n   =================================================================== */\n@media (max-width: 980px){\n  .grid-4{ grid-template-columns: repeat(2,1fr); }\n  .grid-3{ grid-template-columns: repeat(2,1fr); }\n  .dash-grid{ grid-template-columns: 1fr; }\n  .contact-grid{ grid-template-columns: 1fr; }\n}\n\n@media (max-width: 760px){\n  .sidebar{ transform: translateX(-100%); width: 270px; }\n  .sidebar.open{ transform: translateX(0); box-shadow: var(--shadow-pop); }\n  .main{ margin-left:0; }\n  .topbar{ display:flex; }\n  .topstrip{ padding:14px 18px; }\n  .topstrip-meta .pill-status span{ display:none; }\n  .content{ padding: 22px 18px 50px; }\n  .grid-2, .grid-3, .grid-4{ grid-template-columns: 1fr; }\n  .vigilancia-grid{ grid-template-columns:1fr; }\n  .field-row{ grid-template-columns:1fr; }\n  .hero-stamp{ flex-direction:column; align-items:flex-start; text-align:left; }\n  .pop-card-body{ flex-direction:column; gap:12px; }\n  .pop-card-actions{ align-self:flex-start; }\n  .sidebar-scrim.show{\n    display:block; position:fixed; inset:0; background:rgba(0,0,0,0.4); z-index:35;\n  }\n  .page-head{ flex-direction:column; align-items:flex-start; }\n}\n</style>\n</head>\n<body>\n\n<div class=\"app\">\n\n  <!-- ============================ SIDEBAR ============================ -->\n  <aside class=\"sidebar\" id=\"sidebar\">\n    <div class=\"sidebar-brand\">\n      <div class=\"selo selo-sm\"><span class=\"selo-texto\">Farmácia · Uso Seguro</span></div>\n      <div class=\"sidebar-brand-text\">\n        <strong>Farmácia Hospitalar</strong>\n        <span>Hospital Santa Lúcia Bauru</span>\n      </div>\n    </div>\n    <nav class=\"nav\" id=\"nav\"></nav>\n    <div class=\"sidebar-foot\">\n      Portal de uso interno.<br>Conteúdo de exemplo — substitua pelos dados oficiais da unidade.\n    </div>\n  </aside>\n  <div class=\"sidebar-scrim\" id=\"sidebarScrim\"></div>\n\n  <div class=\"main\">\n    <!-- ============================ TOPBAR (mobile) ============================ -->\n    <div class=\"topbar\">\n      <button id=\"menuBtn\" aria-label=\"Abrir menu\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M3 6h18M3 12h18M3 18h18\"/></svg>\n      </button>\n      <div class=\"selo\"><span class=\"selo-texto\">Farmácia</span></div>\n      <span class=\"topbar-title\">Farmácia Hospitalar</span>\n    </div>\n\n    <!-- ============================ TOPSTRIP ============================ -->\n    <div class=\"topstrip\">\n      <div class=\"search\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n        <input id=\"globalSearch\" placeholder=\"Buscar POPs, comunicados, medicamentos…\" autocomplete=\"off\">\n      </div>\n      <div class=\"topstrip-meta\">\n        <span class=\"pill-status\"><span>Sistemas operacionais</span></span>\n      </div>\n    </div>\n\n    <!-- ============================ CONTEÚDO ============================ -->\n    <div class=\"content\" id=\"content\"><!-- views injetadas via JS --></div>\n  </div>\n</div>\n\n<!-- ============================ MODAL COMUNICADO ============================ -->\n<div class=\"modal-scrim\" id=\"modalScrim\">\n  <div class=\"modal-box\">\n    <div class=\"modal-head\">\n      <h2 id=\"modalTitle\"></h2>\n      <button class=\"modal-close\" id=\"modalClose\" aria-label=\"Fechar\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M18 6L6 18M6 6l12 12\"/></svg>\n      </button>\n    </div>\n    <div class=\"modal-body\" id=\"modalBody\"></div>\n  </div>\n</div>\n\n<script>\n/* =====================================================================\n   ÍCONES — glifos simples e consistentes (24x24, stroke), sem dependência externa\n   ===================================================================== */\nconst ICONS = {\n  home: \'<path d=\"M4 11.5L12 4l8 7.5\"/><path d=\"M6 10v9h12v-9\"/><path d=\"M10 19v-5h4v5\"/>\',\n  megaphone: \'<path d=\"M3 11v3a1 1 0 001 1h2l4 4V6L6 10H4a1 1 0 00-1 1z\"/><path d=\"M10 7l8-3v17l-8-3\"/><path d=\"M19 10.5a3 3 0 010 4\"/>\',\n  book: \'<path d=\"M4 19.5A2.5 2.5 0 016.5 17H20\"/><path d=\"M4 5.5A2.5 2.5 0 016.5 3H20v17H6.5A2.5 2.5 0 014 17.5v-12z\"/>\',\n  cap: \'<path d=\"M2 9l10-4 10 4-10 4-10-4z\"/><path d=\"M6 11.5V16c0 1.5 3 3 6 3s6-1.5 6-3v-4.5\"/>\',\n  pill: \'<path d=\"M5 13.5L13.5 5a4.5 4.5 0 016.36 6.36L11.36 19.86A4.5 4.5 0 015 13.5z\"/><path d=\"M9 9l6 6\"/>\',\n  shield: \'<path d=\"M12 3l8 3v6c0 5-3.5 7.5-8 9-4.5-1.5-8-4-8-9V6l8-3z\"/><path d=\"M9 12l2.2 2.2L15.5 9.5\"/>\',\n  flow: \'<circle cx=\"5\" cy=\"6\" r=\"2.2\"/><circle cx=\"19\" cy=\"6\" r=\"2.2\"/><circle cx=\"12\" cy=\"18\" r=\"2.2\"/><path d=\"M7 7l3.5 9M17 7l-3.5 9\"/>\',\n  mail: \'<path d=\"M4 6h16v12H4z\"/><path d=\"M4 7l8 6 8-6\"/>\',\n  chev: \'<path d=\"M6 9l6 6 6-6\"/>\',\n  paperclip: \'<path d=\"M8 12l6-6a3 3 0 014.2 4.2l-8 8a5 5 0 01-7-7l7-7\"/>\',\n  alert: \'<path d=\"M12 3l9 16H3l9-16z\"/><path d=\"M12 10v4\"/><circle cx=\"12\" cy=\"17\" r=\"0.6\"/>\',\n  check: \'<path d=\"M5 13l4 4L19 7\"/>\',\n  bell: \'<path d=\"M9 18a3 3 0 006 0\"/><path d=\"M6 11a6 6 0 1112 0v3.5l1.5 2.5h-15L6 14.5V11z\"/>\',\n  download: \'<path d=\"M12 4v11\"/><path d=\"M7 11l5 5 5-5\"/><path d=\"M5 19h14\"/>\',\n  film: \'<path d=\"M4 5h16v14H4z\"/><path d=\"M4 9h16M4 15h16M9 5v4M9 15v4\"/>\',\n  pin: \'<path d=\"M12 21s7-6.2 7-11.5A7 7 0 105 9.5C5 14.8 12 21 12 21z\"/><circle cx=\"12\" cy=\"9.5\" r=\"2.3\"/>\',\n  phone: \'<path d=\"M5 4h3l2 5-2.5 2a11 11 0 005.5 5.5l2-2.5 5 2v3a1 1 0 01-1 1A16 16 0 014 5a1 1 0 011-1z\"/>\',\n  clock: \'<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3.5 2\"/>\',\n  send: \'<path d=\"M3 11l18-8-8 18-2.5-7L3 11z\"/>\'\n};\nfunction ic(name, cls=\'\'){ return `<svg class=\"${cls}\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\">${ICONS[name]||\'\'}</svg>`; }\n\n/* =====================================================================\n   CONTEÚDO — substitua estes dados pelos materiais oficiais da farmácia.\n   Tudo o que aparece no portal vem destes objetos; não é necessário\n   editar HTML/CSS para atualizar comunicados, POPs, treinamentos etc.\n   ===================================================================== */\n\nconst NAV_ITEMS = [\n  { id:\'home\', label:\'Início\', icon:\'home\' },\n  { id:\'comunicados\', label:\'Comunicados\', icon:\'megaphone\', badge:()=>COMUNICADOS.length },\n  { id:\'pops\', label:\'POPs e Protocolos\', icon:\'book\', badge:()=>POPS.length },\n  { id:\'treinamentos\', label:\'Treinamentos\', icon:\'cap\' },\n  { id:\'padronizacao\', label:\'Padronização\', icon:\'pill\' },\n  { id:\'seguranca\', label:\'Segurança do Paciente\', icon:\'shield\' },\n  { id:\'fluxos\', label:\'Fluxos e Processos\', icon:\'flow\' },\n  { id:\'contato\', label:\'Contato\', icon:\'mail\' },\n];\n\nconst COMUNICADOS = [\n  {\n    id:\'c1\', cat:\'padronizacao\', catLabel:\'Padronização\',\n    titulo:\'Atualização da Lista de Medicamentos Padronizados — Junho/2026\',\n    data:\'24/06/2026\',\n    resumo:\'Inclusão de 3 itens e substituição de apresentação de 2 antimicrobianos na lista vigente, após avaliação da Comissão de Farmácia e Terapêutica (CFT).\',\n    corpo:\'A Comissão de Farmácia e Terapêutica aprovou, em reunião ordinária, a atualização da lista de medicamentos padronizados para o mês de junho. As principais alterações envolvem a inclusão de novas apresentações para adequação às boas práticas de fracionamento e a substituição de itens com restrição de fornecimento pelo distribuidor.\\n\\nAs unidades assistenciais devem observar a nova lista a partir de 01/07/2026. Estoques remanescentes dos itens substituídos poderão ser utilizados até o esgotamento, mediante orientação da farmácia clínica.\\n\\nDúvidas podem ser encaminhadas pelo canal de solicitações da farmácia.\',\n    anexo:\'Lista_Padronizacao_Jun2026.pdf\'\n  },\n  {\n    id:\'c2\', cat:\'desabastecimento\', catLabel:\'Desabastecimento\',\n    titulo:\'Desabastecimento temporário — Cloridrato de Vancomicina 500mg\',\n    data:\'21/06/2026\',\n    resumo:\'Fornecedor informou indisponibilidade pontual. Estoque de segurança garante cobertura prevista de 12 dias; alternativa terapêutica orientada para novas prescrições.\',\n    corpo:\'Em razão de instabilidade na cadeia de fornecimento, a Vancomicina 500mg pó para solução injetável encontra-se com fornecimento irregular. A farmácia mantém estoque estratégico para atendimento das prescrições em curso.\\n\\nPara novas prescrições, recomenda-se contato prévio com a farmácia clínica para avaliação de alternativa terapêutica e ajuste posológico, conforme nota técnica anexa.\\n\\nA situação será reavaliada semanalmente e novas atualizações serão publicadas neste canal.\',\n    anexo:\'Nota_Tecnica_Vancomicina.pdf\'\n  },\n  {\n    id:\'c3\', cat:\'protocolo\', catLabel:\'Protocolo\',\n    titulo:\'Novo fluxo de solicitação de medicamentos não padronizados\',\n    data:\'18/06/2026\',\n    resumo:\'A solicitação passa a ser feita exclusivamente pelo formulário eletrônico da farmácia, com prazo de resposta de até 4 horas em dias úteis.\',\n    corpo:\'A partir desta data, solicitações de medicamentos não padronizados deverão ser registradas pelo canal eletrônico da farmácia (seção \"Fluxos e Processos\" deste portal), substituindo o formulário em papel.\\n\\nO novo fluxo prevê: registro da solicitação justificada pelo médico assistente, análise farmacêutica de pertinência clínica e disponibilidade, e retorno em até 4 horas em dias úteis (8 horas em finais de semana e feriados).\\n\\nCasos de urgência devem ser comunicados também por telefone ao ramal da farmácia central.\',\n    anexo:\'Fluxo_Medicamento_Nao_Padronizado.pdf\'\n  },\n  {\n    id:\'c4\', cat:\'alerta\', catLabel:\'Alerta sanitário\',\n    titulo:\'Alerta ANVISA — recolhimento de lote de Insulina Regular\',\n    data:\'15/06/2026\',\n    resumo:\'Recolhimento preventivo de lote específico por desvio de qualidade. Farmácia já realizou conferência de estoque; nenhum frasco do lote identificado na unidade.\',\n    corpo:\'Em atenção ao alerta da ANVISA, a farmácia realizou conferência imediata do estoque de Insulina Regular. Não foram localizados frascos pertencentes ao lote objeto do recolhimento nesta unidade.\\n\\nAinda assim, recomenda-se que a equipe assistencial confira o número de lote de frascos já distribuídos para os setores antes da administração, conforme rotina padrão de checagem dupla para medicamentos de alta vigilância.\\n\\nEm caso de identificação do lote, suspender o uso e notificar a farmácia imediatamente.\',\n    anexo:\'Alerta_Anvisa_Insulina.pdf\'\n  },\n  {\n    id:\'c5\', cat:\'orientacao\', catLabel:\'Orientação institucional\',\n    titulo:\'Horário de funcionamento da Farmácia Central — feriado\',\n    data:\'10/06/2026\',\n    resumo:\'Atendimento em horário reduzido no feriado, com plantão para urgências mantido em regime 24h.\',\n    corpo:\'No feriado do próximo dia 24, a Farmácia Central funcionará em horário reduzido (8h às 14h) para dispensação de rotina. O plantão farmacêutico para urgências e setores críticos permanece em regime de 24 horas, conforme escala afixada no mural da farmácia.\\n\\nSolicitações de medicamentos não padronizados serão analisadas no primeiro dia útil subsequente, exceto em caráter de urgência clínica.\',\n    anexo:null\n  },\n];\n\nconst POPS = [\n  { codigo:\'POP-FAR-001\', versao:\'v4.0\', titulo:\'Dispensação de medicamentos em unidades de internação\', cat:\'dispensacao\', catLabel:\'Dispensação\', data:\'12/05/2026\' },\n  { codigo:\'POP-FAR-014\', versao:\'v2.1\', titulo:\'Armazenamento de medicamentos termolábeis (cadeia fria)\', cat:\'cadeia-fria\', catLabel:\'Cadeia fria\', data:\'03/04/2026\' },\n  { codigo:\'POP-FAR-022\', versao:\'v3.2\', titulo:\'Manejo de medicamentos de alta vigilância\', cat:\'alta-vigilancia\', catLabel:\'Alta vigilância\', data:\'28/05/2026\' },\n  { codigo:\'POP-FAR-030\', versao:\'v2.0\', titulo:\'Dispensação e controle de antimicrobianos\', cat:\'antimicrobianos\', catLabel:\'Antimicrobianos\', data:\'15/02/2026\' },\n  { codigo:\'POP-FAR-045\', versao:\'v1.3\', titulo:\'Fracionamento de formas sólidas orais\', cat:\'fracionamento\', catLabel:\'Fracionamento\', data:\'20/01/2026\' },\n  { codigo:\'POP-FAR-052\', versao:\'v2.4\', titulo:\'Manipulação de nutrição parenteral\', cat:\'farmacotecnica\', catLabel:\'Farmacotécnica hospitalar\', data:\'09/06/2026\' },\n  { codigo:\'POP-FAR-007\', versao:\'v3.0\', titulo:\'Armazenamento geral de medicamentos e correlatos\', cat:\'armazenamento\', catLabel:\'Armazenamento\', data:\'02/03/2026\' },\n  { codigo:\'POP-FAR-038\', versao:\'v1.1\', titulo:\'Reconstituição e diluição de antimicrobianos injetáveis\', cat:\'antimicrobianos\', catLabel:\'Antimicrobianos\', data:\'11/11/2025\' },\n];\n\nconst POP_CATEGORIAS = [\n  { id:\'todas\', label:\'Todas\' },\n  { id:\'dispensacao\', label:\'Dispensação\' },\n  { id:\'armazenamento\', label:\'Armazenamento\' },\n  { id:\'cadeia-fria\', label:\'Cadeia fria\' },\n  { id:\'alta-vigilancia\', label:\'Alta vigilância\' },\n  { id:\'antimicrobianos\', label:\'Antimicrobianos\' },\n  { id:\'fracionamento\', label:\'Fracionamento\' },\n  { id:\'farmacotecnica\', label:\'Farmacotécnica\' },\n];\n\nconst TREINAMENTOS = [\n  { titulo:\'Uso seguro de medicamentos de alta vigilância\', publico:\'Enfermagem e Farmácia\', duracao:\'25 min\', desc:\'Identificação, dupla checagem e boas práticas no manuseio de medicamentos com risco aumentado de dano.\' },\n  { titulo:\'Armazenamento correto de termolábeis e cadeia fria\', publico:\'Enfermagem, Farmácia e Almoxarifado\', duracao:\'18 min\', desc:\'Faixas de temperatura, rotina de monitoramento e conduta em caso de desvio térmico.\' },\n  { titulo:\'Erros de medicação: identificação e prevenção\', publico:\'Toda equipe assistencial\', duracao:\'30 min\', desc:\'Os \"5 certos\" da administração de medicamentos e como notificar eventos adversos.\' },\n  { titulo:\'Antimicrobianos e stewardship hospitalar\', publico:\'Médicos e Farmácia Clínica\', duracao:\'40 min\', desc:\'Princípios do uso racional de antimicrobianos e papel da farmácia no programa institucional.\' },\n];\n\nconst MEDICAMENTOS_PADRONIZADOS = [\n  { nome:\'Dipirona sódica\', classe:\'Analgésico/Antitérmico\', apresentacao:\'500mg/mL — solução injetável\', status:\'padronizado\' },\n  { nome:\'Ceftriaxona sódica\', classe:\'Antimicrobiano\', apresentacao:\'1g — pó p/ solução injetável\', status:\'padronizado\' },\n  { nome:\'Enoxaparina sódica\', classe:\'Anticoagulante\', apresentacao:\'40mg/0,4mL — seringa preenchida\', status:\'padronizado\' },\n  { nome:\'Vancomicina (em desabastecimento)\', classe:\'Antimicrobiano\', apresentacao:\'500mg — pó p/ solução injetável\', status:\'alternativa\' },\n  { nome:\'Omeprazol\', classe:\'Inibidor de bomba de prótons\', apresentacao:\'40mg — pó p/ solução injetável\', status:\'padronizado\' },\n  { nome:\'Midazolam\', classe:\'Sedativo/hipnótico\', apresentacao:\'5mg/mL — solução injetável\', status:\'padronizado\' },\n];\n\nconst ATUALIZACOES_PADRONIZACAO = [\n  { tipo:\'Inclusão\', item:\'Sulfato de magnésio 10% — ampola 10mL\', data:\'24/06/2026\' },\n  { tipo:\'Exclusão\', item:\'Apresentação anterior de Ceftriaxona 250mg (descontinuada pelo fabricante)\', data:\'24/06/2026\' },\n];\n\nconst NOTAS_TECNICAS = [\n  { titulo:\'Nota técnica — manejo de alternativa terapêutica à Vancomicina\', data:\'21/06/2026\' },\n  { titulo:\'Nota técnica — uso de Sulfato de Magnésio em pré-eclâmpsia\', data:\'05/06/2026\' },\n];\n\nconst LASA_PARES = [\n  { a:\'Hidr<span class=\"hl\">ALA</span>zina\', b:\'Hidr<span class=\"hl\">OXI</span>zina\', nota:\'Anti-hipertensivo × anti-histamínico. Confirmar indicação clínica antes da dispensação.\' },\n  { a:\'Clona<span class=\"hl\">ZE</span>pam\', b:\'Clo<span class=\"hl\">BA</span>zam\', nota:\'Ambos anticonvulsivantes/benzodiazepínicos — checar dose e apresentação.\' },\n  { a:\'Insulina <span class=\"hl\">NPH</span>\', b:\'Insulina <span class=\"hl\">Regular</span>\', nota:\'Tempo de ação distinto. Sempre confirmar tipo antes da administração.\' },\n  { a:\'Do<span class=\"hl\">PA</span>mina\', b:\'Do<span class=\"hl\">BU</span>tamina\', nota:\'Aminas vasoativas com mecanismos diferentes — risco elevado em UTI.\' },\n];\n\nconst ALTA_VIGILANCIA = [\'Insulinas (todas as apresentações)\',\'Heparina e demais anticoagulantes\',\'Cloreto de Potássio concentrado\',\'Opioides injetáveis\',\'Quimioterápicos antineoplásicos\',\'Bloqueadores neuromusculares\',\'Soluções concentradas de eletrólitos\',\'Sedativos para sedação profunda\'];\n\nconst CHECAGEM_DUPLA = [\n  { titulo:\'Identificação do paciente\', texto:\'Confirmar nome completo e data de nascimento, conferindo com a pulseira de identificação.\' },\n  { titulo:\'Confirmação do medicamento\', texto:\'Verificar nome, concentração, apresentação e validade do item a ser administrado.\' },\n  { titulo:\'Checagem da prescrição\', texto:\'Confrontar dose, via e horário com a prescrição médica vigente.\' },\n  { titulo:\'Assinatura dos dois profissionais\', texto:\'Ambos os profissionais envolvidos na checagem assinam o registro antes da administração.\' },\n];\n\nconst FLUXOS = [\n  { titulo:\'Solicitação de medicamento não padronizado\', passos:[\n    {t:\'Abertura da solicitação\', d:\'Médico assistente registra a justificativa clínica no formulário eletrônico.\'},\n    {t:\'Triagem farmacêutica\', d:\'Farmácia avalia pertinência clínica e disponibilidade de alternativa padronizada.\'},\n    {t:\'Parecer e aquisição\', d:\'Em caso de aprovação, farmácia inicia processo de aquisição ou empréstimo entre unidades.\'},\n    {t:\'Liberação ao setor\', d:\'Medicamento é liberado e o solicitante é notificado pelo prazo definido em protocolo.\'},\n  ]},\n  { titulo:\'Fluxo de devolução de medicamentos\', passos:[\n    {t:\'Identificação do item\', d:\'Setor separa o medicamento não utilizado, íntegro e dentro da validade.\'},\n    {t:\'Registro da devolução\', d:\'Preenchimento do formulário de devolução com motivo e responsável.\'},\n    {t:\'Conferência farmacêutica\', d:\'Farmácia verifica condições de armazenamento e integridade da embalagem.\'},\n    {t:\'Retorno ao estoque ou descarte\', d:\'Item retorna ao estoque ativo ou é destinado a descarte conforme normas vigentes.\'},\n  ]},\n  { titulo:\'Perdas e ajustes de estoque\', passos:[\n    {t:\'Identificação da divergência\', d:\'Equipe identifica perda, quebra ou divergência no inventário.\'},\n    {t:\'Registro formal\', d:\'Abertura de ocorrência com descrição, quantidade e setor envolvido.\'},\n    {t:\'Análise da farmácia\', d:\'Avaliação da causa raiz e classificação (operacional, técnica ou administrativa).\'},\n    {t:\'Ajuste no sistema\', d:\'Correção do saldo de estoque e arquivamento da documentação de suporte.\'},\n  ]},\n  { titulo:\'Fluxo de emergência\', passos:[\n    {t:\'Acionamento\', d:\'Setor aciona a farmácia pelo ramal de emergência, informando o medicamento necessário.\'},\n    {t:\'Priorização imediata\', d:\'Farmacêutico interrompe atividade de rotina para atendimento prioritário.\'},\n    {t:\'Entrega expressa\', d:\'Medicamento é encaminhado ao setor por mensageiro dedicado ou retirada direta.\'},\n    {t:\'Registro retroativo\', d:\'Documentação formal da dispensação é completada em até 2 horas.\'},\n  ]},\n  { titulo:\'Atendimento a setores críticos\', passos:[\n    {t:\'Padronização específica\', d:\'UTI, centro cirúrgico e emergência possuem kits e padronização própria revisados semestralmente.\'},\n    {t:\'Reposição programada\', d:\'Farmácia realiza checagem e reposição de kits em horários fixos, sem necessidade de solicitação.\'},\n    {t:\'Canal direto\', d:\'Setores críticos possuem ramal direto com farmacêutico de plantão.\'},\n    {t:\'Auditoria periódica\', d:\'Farmácia realiza auditoria mensal de validade e integridade dos kits.\'},\n  ]},\n];\n\nconst KPIS = [\n  { num:\'98,2%\', label:\'Conformidade em auditorias de dispensação\', trend:\'+0,6 p.p. vs mês anterior\', trendType:\'up\' },\n  { num:\'312\', label:\'POPs vigentes na biblioteca\', trend:\'4 revisados este mês\', trendType:\'flat\' },\n  { num:\'47\', label:\'Treinamentos concluídos no mês\', trend:\'+12 vs mês anterior\', trendType:\'up\' },\n  { num:\'1\', label:\'Evento adverso grave notificado no mês\', trend:\'Em análise pela CCIH\', trendType:\'warn\' },\n];\n\n/* =====================================================================\n   ROTEAMENTO E RENDERIZAÇÃO\n   ===================================================================== */\nlet currentView = \'home\';\nlet popFiltro = { cat:\'todas\', q:\'\' };\nlet comFiltro = { cat:\'todas\' };\n\nfunction catTagClass(cat){\n  return {protocolo:\'tag-protocolo\', padronizacao:\'tag-padronizacao\', desabastecimento:\'tag-desabastecimento\', alerta:\'tag-alerta\', orientacao:\'tag-orientacao\'}[cat] || \'tag-orientacao\';\n}\n\nfunction renderNav(){\n  document.getElementById(\'nav\').innerHTML = NAV_ITEMS.map(item => `\n    <button class=\"nav-item ${item.id===currentView?\'active\':\'\'}\" data-view=\"${item.id}\">\n      ${ic(item.icon)}\n      <span>${item.label}</span>\n      ${item.badge ? `<span class=\"badge\">${item.badge()}</span>` : \'\'}\n    </button>\n  `).join(\'\');\n  document.querySelectorAll(\'.nav-item\').forEach(btn=>{\n    btn.addEventListener(\'click\', ()=>{ navigate(btn.dataset.view); closeMobileMenu(); });\n  });\n}\n\nfunction renderHome(){\n  return `\n    <div class=\"page-head\">\n      <div>\n        <span class=\"eyebrow\">Painel principal</span>\n        <h1>Bem-vindo ao portal da Farmácia Hospitalar</h1>\n        <p>Acesso rápido a comunicados, protocolos e indicadores da assistência farmacêutica do Hospital Santa Lúcia Bauru.</p>\n      </div>\n    </div>\n\n    <div class=\"hero-stamp\">\n      <div class=\"selo\"><span class=\"selo-texto\">Farmácia Hospitalar · Uso Seguro de Medicamentos</span></div>\n      <div class=\"hero-stamp-text\">\n        <span class=\"eyebrow\">Compromisso institucional</span>\n        <h1>Uso seguro e racional de medicamentos, em cada etapa da assistência.</h1>\n        <p>Este portal reúne os protocolos, comunicados e materiais de educação continuada da Farmácia Hospitalar para toda a equipe do hospital.</p>\n      </div>\n    </div>\n\n    <div class=\"grid grid-4 kpi-row\">\n      ${KPIS.map(k=>`\n        <div class=\"card kpi\">\n          <div class=\"kpi-num\">${k.num}</div>\n          <div class=\"kpi-label\">${k.label}</div>\n          <span class=\"kpi-trend trend-${k.trendType}\">${k.trend}</span>\n        </div>\n      `).join(\'\')}\n    </div>\n\n    <div class=\"dash-grid\">\n      <div class=\"dash-col\">\n        <div class=\"card\" style=\"padding:18px 18px 8px;\">\n          <div class=\"section-title\">${ic(\'megaphone\')} Comunicados recentes <span class=\"ver-tudo\" data-go=\"comunicados\">Ver todos</span></div>\n          ${COMUNICADOS.slice(0,4).map(c=>`\n            <div class=\"list-item\">\n              <div class=\"list-item-icon\">${ic(\'megaphone\')}</div>\n              <div class=\"list-item-body\">\n                <div class=\"list-item-title\">${c.titulo}</div>\n                <div class=\"list-item-meta\">\n                  <span class=\"tag ${catTagClass(c.cat)}\">${c.catLabel}</span>\n                  <span class=\"mono\">${c.data}</span>\n                </div>\n              </div>\n            </div>\n          `).join(\'\')}\n        </div>\n\n        <div class=\"card\" style=\"padding:18px 18px 8px; margin-top:20px;\">\n          <div class=\"section-title\">${ic(\'book\')} POPs mais acessados <span class=\"ver-tudo\" data-go=\"pops\">Ver biblioteca</span></div>\n          ${POPS.slice(0,4).map(p=>`\n            <div class=\"list-item\">\n              <div class=\"list-item-icon\">${ic(\'book\')}</div>\n              <div class=\"list-item-body\">\n                <div class=\"list-item-title\">${p.titulo}</div>\n                <div class=\"list-item-meta\"><span class=\"mono\">${p.codigo} · ${p.versao}</span><span>${p.catLabel}</span></div>\n              </div>\n            </div>\n          `).join(\'\')}\n        </div>\n      </div>\n\n      <div class=\"dash-col\">\n        <div class=\"card\" style=\"padding:18px;\">\n          <div class=\"section-title\">${ic(\'alert\')} Alertas de segurança medicamentosa</div>\n          <div class=\"alert-row crit\">\n            ${ic(\'alert\')}\n            <div><div class=\"alert-row-title\">Recolhimento de lote — Insulina Regular</div><div class=\"alert-row-text\">Conferir número de lote antes da administração. Ver comunicado completo.</div></div>\n          </div>\n          <div class=\"alert-row\">\n            ${ic(\'alert\')}\n            <div><div class=\"alert-row-title\">Desabastecimento — Vancomicina 500mg</div><div class=\"alert-row-text\">Estoque de segurança garante cobertura de 12 dias.</div></div>\n          </div>\n        </div>\n\n        <div class=\"card\" style=\"padding:18px 18px 8px; margin-top:20px;\">\n          <div class=\"section-title\">${ic(\'cap\')} Treinamentos em destaque <span class=\"ver-tudo\" data-go=\"treinamentos\">Ver todos</span></div>\n          ${TREINAMENTOS.slice(0,2).map(t=>`\n            <div class=\"list-item\">\n              <div class=\"list-item-icon\">${ic(\'cap\')}</div>\n              <div class=\"list-item-body\">\n                <div class=\"list-item-title\">${t.titulo}</div>\n                <div class=\"list-item-meta\"><span class=\"mono\">${t.duracao}</span><span>${t.publico}</span></div>\n              </div>\n            </div>\n          `).join(\'\')}\n        </div>\n\n        <div class=\"card\" style=\"padding:18px 18px 8px; margin-top:20px;\">\n          <div class=\"section-title\">${ic(\'pill\')} Padronização — atualizações</div>\n          ${ATUALIZACOES_PADRONIZACAO.map(a=>`\n            <div class=\"list-item\">\n              <div class=\"list-item-icon\">${ic(\'pill\')}</div>\n              <div class=\"list-item-body\">\n                <div class=\"list-item-title\">${a.tipo}: ${a.item}</div>\n                <div class=\"list-item-meta\"><span class=\"mono\">${a.data}</span></div>\n              </div>\n            </div>\n          `).join(\'\')}\n        </div>\n      </div>\n    </div>\n  `;\n}\n\nfunction renderComunicados(){\n  const cats = [{id:\'todas\',label:\'Todas\'},{id:\'protocolo\',label:\'Protocolo\'},{id:\'padronizacao\',label:\'Padronização\'},{id:\'desabastecimento\',label:\'Desabastecimento\'},{id:\'alerta\',label:\'Alerta sanitário\'},{id:\'orientacao\',label:\'Orientação\'}];\n  const lista = COMUNICADOS.filter(c=> comFiltro.cat===\'todas\' || c.cat===comFiltro.cat);\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Comunicação oficial</span><h1>Comunicados da Farmácia</h1><p>Publicações oficiais sobre protocolos, padronização, desabastecimentos e alertas sanitários.</p></div>\n    </div>\n    <div class=\"filter-row\">\n      ${cats.map(c=>`<button class=\"chip ${comFiltro.cat===c.id?\'active\':\'\'}\" data-comcat=\"${c.id}\">${c.label}</button>`).join(\'\')}\n    </div>\n    <div id=\"comList\">\n      ${lista.length? lista.map(c=>`\n        <div class=\"card com-card\" data-comid=\"${c.id}\">\n          <div class=\"com-card-top\">\n            <span class=\"tag ${catTagClass(c.cat)}\">${c.catLabel}</span>\n            <span class=\"com-card-date mono\">${c.data}</span>\n          </div>\n          <h3>${c.titulo}</h3>\n          <p>${c.resumo}</p>\n          <div class=\"com-card-foot\">\n            <button class=\"btn btn-ghost\" data-comid=\"${c.id}\">Ler comunicado completo →</button>\n            ${c.anexo? `<span class=\"anexo-link\">${ic(\'paperclip\')} ${c.anexo}</span>` : \'\'}\n          </div>\n        </div>\n      `).join(\'\') : `<div class=\"empty\">Nenhum comunicado nesta categoria.</div>`}\n    </div>\n  `;\n}\n\nfunction renderPops(){\n  const lista = POPS.filter(p=>{\n    const matchCat = popFiltro.cat===\'todas\' || p.cat===popFiltro.cat;\n    const q = popFiltro.q.trim().toLowerCase();\n    const matchQ = !q || p.titulo.toLowerCase().includes(q) || p.codigo.toLowerCase().includes(q);\n    return matchCat && matchQ;\n  });\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Documentação técnica</span><h1>Biblioteca de POPs e Protocolos</h1><p>Procedimentos Operacionais Padrão vigentes, organizados por categoria e com controle de versão.</p></div>\n    </div>\n    <div class=\"lib-toolbar\">\n      <div class=\"search\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n        <input id=\"popSearch\" placeholder=\"Buscar por título ou código…\" value=\"${popFiltro.q}\">\n      </div>\n    </div>\n    <div class=\"filter-row\">\n      ${POP_CATEGORIAS.map(c=>`<button class=\"chip ${popFiltro.cat===c.id?\'active\':\'\'}\" data-popcat=\"${c.id}\">${c.label}</button>`).join(\'\')}\n    </div>\n    <div id=\"popList\">\n      ${lista.length? lista.map(p=>`\n        <div class=\"card pop-card\">\n          <div class=\"pop-card-tab\"></div>\n          <div class=\"pop-card-body\">\n            <div class=\"pop-card-code mono\">${p.codigo}<span class=\"ver\">${p.versao}</span></div>\n            <div class=\"pop-card-main\">\n              <h3>${p.titulo}</h3>\n              <div class=\"pop-card-main-meta\">\n                <span class=\"tag tag-orientacao\">${p.catLabel}</span>\n                <span class=\"mono\">Atualizado em ${p.data}</span>\n              </div>\n            </div>\n            <div class=\"pop-card-actions\">\n              <button class=\"btn btn-primary\" onclick=\"alert(\'Download de exemplo — conecte este botão ao arquivo real do POP (PDF).\')\">${ic(\'download\')} PDF</button>\n            </div>\n          </div>\n        </div>\n      `).join(\'\') : `<div class=\"empty\">Nenhum POP encontrado para esta busca.</div>`}\n    </div>\n  `;\n}\n\nfunction renderTreinamentos(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Educação continuada</span><h1>Treinamentos da Farmácia Hospitalar</h1><p>Capacitações sobre uso seguro de medicamentos, com vídeo, material de apoio e avaliação.</p></div>\n    </div>\n    <div class=\"grid grid-2\">\n      ${TREINAMENTOS.map(t=>`\n        <div class=\"card train-card\">\n          <div class=\"train-thumb\">${ic(\'film\')}<span class=\"dur mono\">${t.duracao}</span></div>\n          <div class=\"train-body\">\n            <h3>${t.titulo}</h3>\n            <p>${t.desc}</p>\n            <div class=\"train-audience\">${ic(\'cap\')} Público-alvo: ${t.publico}</div>\n            <div class=\"train-actions\">\n              <button class=\"btn btn-primary\" onclick=\"alert(\'Player de exemplo — incorpore aqui o vídeo do YouTube privado ou Google Drive.\')\">${ic(\'film\')} Assistir</button>\n              <button class=\"btn\" onclick=\"alert(\'Material de apoio em PDF — anexe aqui o arquivo real.\')\">${ic(\'download\')} Material</button>\n              <button class=\"btn\" onclick=\"alert(\'Questionário de avaliação — conecte aqui o Google Forms do treinamento.\')\">${ic(\'check\')} Avaliação</button>\n            </div>\n          </div>\n        </div>\n      `).join(\'\')}\n    </div>\n  `;\n}\n\nfunction renderPadronizacao(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Padronização institucional</span><h1>Padronização de Medicamentos</h1><p>Lista vigente, atualizações recentes e notas técnicas da Comissão de Farmácia e Terapêutica.</p></div>\n    </div>\n    <div class=\"card\" style=\"margin-bottom:20px;\">\n      <div class=\"table-wrap\">\n        <table class=\"std-table\">\n          <thead><tr><th>Medicamento</th><th>Classe</th><th>Apresentação</th><th>Status</th></tr></thead>\n          <tbody>\n            ${MEDICAMENTOS_PADRONIZADOS.map(m=>`\n              <tr>\n                <td><strong>${m.nome}</strong></td>\n                <td>${m.classe}</td>\n                <td>${m.apresentacao}</td>\n                <td><span class=\"status-dot status-${m.status}\">${m.status===\'padronizado\'?\'Padronizado\':\'Alternativa em uso\'}</span></td>\n              </tr>\n            `).join(\'\')}\n          </tbody>\n        </table>\n      </div>\n    </div>\n    <div class=\"grid grid-2\">\n      <div class=\"card\" style=\"padding:18px;\">\n        <div class=\"section-title\">${ic(\'pill\')} Atualizações recentes</div>\n        ${ATUALIZACOES_PADRONIZACAO.map(a=>`\n          <div class=\"list-item\"><div class=\"list-item-icon\">${ic(\'pill\')}</div>\n            <div class=\"list-item-body\"><div class=\"list-item-title\">${a.tipo}</div><div class=\"list-item-meta\">${a.item}<br><span class=\"mono\">${a.data}</span></div></div>\n          </div>\n        `).join(\'\')}\n      </div>\n      <div class=\"card\" style=\"padding:18px;\">\n        <div class=\"section-title\">${ic(\'book\')} Notas técnicas farmacêuticas</div>\n        ${NOTAS_TECNICAS.map(n=>`\n          <div class=\"list-item\"><div class=\"list-item-icon\">${ic(\'book\')}</div>\n            <div class=\"list-item-body\"><div class=\"list-item-title\">${n.titulo}</div><div class=\"list-item-meta\"><span class=\"mono\">${n.data}</span></div></div>\n          </div>\n        `).join(\'\')}\n      </div>\n    </div>\n  `;\n}\n\nfunction renderSeguranca(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Segurança do paciente</span><h1>Segurança do Paciente — Farmácia</h1><p>Conteúdo crítico sobre medicamentos LASA, alta vigilância e prevenção de erros de medicação.</p></div>\n    </div>\n\n    <div class=\"section-title\">${ic(\'alert\')} Medicamentos com nome ou aparência semelhante (LASA)</div>\n    <div style=\"margin-bottom:26px;\">\n      ${LASA_PARES.map(l=>`\n        <div class=\"card lasa-pair\">\n          <span class=\"lasa-word\">${l.a}</span><span class=\"lasa-vs\">vs</span><span class=\"lasa-word\">${l.b}</span>\n          <span class=\"lasa-note\">${l.nota}</span>\n        </div>\n      `).join(\'\')}\n    </div>\n\n    <div class=\"grid grid-2\" style=\"margin-bottom:26px;\">\n      <div>\n        <div class=\"section-title\">${ic(\'shield\')} Medicamentos de alta vigilância</div>\n        <div class=\"vigilancia-grid\">\n          ${ALTA_VIGILANCIA.map(v=>`<div class=\"card vigilancia-item\">${ic(\'alert\')}<span>${v}</span></div>`).join(\'\')}\n        </div>\n      </div>\n      <div>\n        <div class=\"section-title\">${ic(\'check\')} Protocolo de dupla checagem</div>\n        <div class=\"card\" style=\"padding: 6px 20px;\">\n          <div class=\"check-steps\">\n            ${CHECAGEM_DUPLA.map((c,i)=>`\n              <div class=\"check-step\">\n                <div class=\"check-step-num\">${i+1}</div>\n                <div class=\"check-step-text\"><strong>${c.titulo}</strong><span>${c.texto}</span></div>\n              </div>\n            `).join(\'\')}\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\" style=\"padding:20px; display:flex; gap:16px; align-items:center; flex-wrap:wrap;\">\n      <div style=\"flex:1; min-width:220px;\">\n        <div class=\"section-title\" style=\"margin-bottom:6px;\">${ic(\'bell\')} Identificou um erro de medicação ou evento adverso?</div>\n        <p style=\"font-size:12.5px; color:var(--gray);\">A notificação é essencial para a melhoria contínua dos processos. Não é necessário identificar o profissional.</p>\n      </div>\n      <button class=\"btn btn-primary\" data-go=\"contato\">${ic(\'send\')} Notificar evento</button>\n    </div>\n  `;\n}\n\nfunction renderFluxos(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Processos operacionais</span><h1>Fluxos e Processos da Farmácia</h1><p>Etapas padronizadas para solicitações, devoluções, ajustes de estoque e atendimentos especiais.</p></div>\n    </div>\n    <div id=\"flowList\">\n      ${FLUXOS.map((f,i)=>`\n        <div class=\"card flow-acc ${i===0?\'open\':\'\'}\" data-flow=\"${i}\">\n          <button class=\"flow-acc-head\" data-flowtoggle=\"${i}\">\n            <span class=\"num mono\">0${i+1}</span>\n            <h3>${f.titulo}</h3>\n            ${ic(\'chev\')}\n          </button>\n          <div class=\"flow-acc-body\">\n            <div class=\"flow-steps\">\n              ${f.passos.map((p,j)=>`\n                <div class=\"flow-step\">\n                  <div class=\"flow-step-inner\">\n                    <div class=\"flow-step-num mono\">${j+1}</div>\n                    <div class=\"flow-step-title\">${p.t}</div>\n                    <div class=\"flow-step-text\">${p.d}</div>\n                  </div>\n                </div>\n                ${j<f.passos.length-1? `<div class=\"flow-arrow\">${ic(\'chev\')}</div>` : \'\'}\n              `).join(\'\')}\n            </div>\n          </div>\n        </div>\n      `).join(\'\')}\n    </div>\n  `;\n}\n\nfunction renderContato(){\n  return `\n    <div class=\"page-head\">\n      <div><span class=\"eyebrow\">Canal direto</span><h1>Contato e Solicitações</h1><p>Solicite medicamentos, tire dúvidas técnicas ou notifique problemas diretamente à Farmácia Hospitalar.</p></div>\n    </div>\n    <div class=\"contact-grid\">\n      <div class=\"card form-card\">\n        <div class=\"confirm-box\" id=\"confirmBox\">\n          ${ic(\'check\')}\n          <div><strong>Solicitação registrada</strong><span>Este é um formulário de demonstração — conecte-o ao seu sistema real de chamados ou e-mail institucional.</span></div>\n        </div>\n        <form id=\"contactForm\">\n          <div class=\"field-row\">\n            <div class=\"field\"><label>Nome completo</label><input required placeholder=\"Seu nome\"></div>\n            <div class=\"field\"><label>Setor</label><input required placeholder=\"Ex.: UTI Adulto\"></div>\n          </div>\n          <div class=\"field\">\n            <label>Tipo de solicitação</label>\n            <select>\n              <option>Solicitação de medicamento não padronizado</option>\n              <option>Dúvida técnica</option>\n              <option>Sugestão</option>\n              <option>Notificação de problema / evento adverso</option>\n            </select>\n          </div>\n          <div class=\"field\"><label>Mensagem</label><textarea required placeholder=\"Descreva sua solicitação com o máximo de detalhes possível…\"></textarea></div>\n          <button class=\"btn btn-primary btn-block\" type=\"submit\">${ic(\'send\')} Enviar solicitação</button>\n        </form>\n      </div>\n      <div class=\"card\" style=\"padding:22px 24px;\">\n        <div class=\"section-title\" style=\"margin-bottom:16px;\">Canais diretos</div>\n        <div class=\"contact-info-item\">${ic(\'phone\')}<div><strong>Ramal da Farmácia Central</strong><span>Ramal 4521 — dias úteis, 7h às 19h</span></div></div>\n        <div class=\"contact-info-item\">${ic(\'mail\')}<div><strong>E-mail institucional</strong><span>farmacia.hospitalar@hospitalsantalucia.exemplo</span></div></div>\n        <div class=\"contact-info-item\">${ic(\'clock\')}<div><strong>Plantão farmacêutico</strong><span>24 horas, todos os dias, via ramal de urgência 4599</span></div></div>\n        <div class=\"contact-info-item\">${ic(\'pin\')}<div><strong>Localização</strong><span>Farmácia Central — Bloco A, térreo</span></div></div>\n      </div>\n    </div>\n  `;\n}\n\nconst RENDERERS = {\n  home: renderHome, comunicados: renderComunicados, pops: renderPops,\n  treinamentos: renderTreinamentos, padronizacao: renderPadronizacao,\n  seguranca: renderSeguranca, fluxos: renderFluxos, contato: renderContato,\n};\n\nfunction navigate(view){\n  if(!RENDERERS[view]) return;\n  currentView = view;\n  document.getElementById(\'content\').innerHTML = `<div class=\"view active\">${RENDERERS[view]()}</div>`;\n  renderNav();\n  bindViewEvents(view);\n  document.getElementById(\'content\').scrollTop = 0;\n  window.scrollTo(0,0);\n}\n\nfunction bindViewEvents(view){\n  document.querySelectorAll(\'[data-go]\').forEach(el=> el.addEventListener(\'click\', ()=> navigate(el.dataset.go)));\n\n  if(view===\'comunicados\'){\n    document.querySelectorAll(\'[data-comcat]\').forEach(el=> el.addEventListener(\'click\', ()=>{ comFiltro.cat = el.dataset.comcat; navigate(\'comunicados\'); }));\n    document.querySelectorAll(\'[data-comid]\').forEach(el=> el.addEventListener(\'click\', ()=> openComunicado(el.dataset.comid)));\n  }\n  if(view===\'pops\'){\n    document.querySelectorAll(\'[data-popcat]\').forEach(el=> el.addEventListener(\'click\', ()=>{ popFiltro.cat = el.dataset.popcat; navigate(\'pops\'); }));\n    const input = document.getElementById(\'popSearch\');\n    if(input){\n      input.addEventListener(\'input\', ()=>{\n        const pos = input.selectionStart;\n        popFiltro.q = input.value;\n        navigate(\'pops\');\n        const newInput = document.getElementById(\'popSearch\');\n        newInput.focus();\n        newInput.setSelectionRange(pos,pos);\n      });\n    }\n  }\n  if(view===\'fluxos\'){\n    document.querySelectorAll(\'[data-flowtoggle]\').forEach(el=>{\n      el.addEventListener(\'click\', ()=>{\n        const card = el.closest(\'.flow-acc\');\n        card.classList.toggle(\'open\');\n      });\n    });\n  }\n  if(view===\'contato\'){\n    const form = document.getElementById(\'contactForm\');\n    form.addEventListener(\'submit\', (e)=>{\n      e.preventDefault();\n      document.getElementById(\'confirmBox\').classList.add(\'show\');\n      form.reset();\n      document.getElementById(\'confirmBox\').scrollIntoView({behavior:\'smooth\', block:\'center\'});\n    });\n  }\n}\n\nfunction openComunicado(id){\n  const c = COMUNICADOS.find(x=>x.id===id);\n  if(!c) return;\n  document.getElementById(\'modalTitle\').textContent = c.titulo;\n  document.getElementById(\'modalBody\').innerHTML = `\n    <div class=\"com-card-top\" style=\"margin-bottom:14px;\">\n      <span class=\"tag ${catTagClass(c.cat)}\">${c.catLabel}</span>\n      <span class=\"com-card-date mono\">${c.data}</span>\n    </div>\n    <div class=\"com-detail-body\">${c.corpo.split(\'\\n\\n\').map(p=>`<p>${p}</p>`).join(\'\')}</div>\n    ${c.anexo? `<div style=\"margin-top:16px;\"><span class=\"anexo-link\">${ic(\'paperclip\')} ${c.anexo}</span></div>` : \'\'}\n  `;\n  document.getElementById(\'modalScrim\').classList.add(\'show\');\n}\n\n/* =====================================================================\n   INTERAÇÕES GLOBAIS — menu mobile, busca global, modal\n   ===================================================================== */\nfunction openMobileMenu(){ document.getElementById(\'sidebar\').classList.add(\'open\'); document.getElementById(\'sidebarScrim\').classList.add(\'show\'); }\nfunction closeMobileMenu(){ document.getElementById(\'sidebar\').classList.remove(\'open\'); document.getElementById(\'sidebarScrim\').classList.remove(\'show\'); }\ndocument.getElementById(\'menuBtn\').addEventListener(\'click\', openMobileMenu);\ndocument.getElementById(\'sidebarScrim\').addEventListener(\'click\', closeMobileMenu);\n\ndocument.getElementById(\'modalClose\').addEventListener(\'click\', ()=> document.getElementById(\'modalScrim\').classList.remove(\'show\'));\ndocument.getElementById(\'modalScrim\').addEventListener(\'click\', (e)=>{ if(e.target.id===\'modalScrim\') document.getElementById(\'modalScrim\').classList.remove(\'show\'); });\ndocument.addEventListener(\'keydown\', (e)=>{ if(e.key===\'Escape\') document.getElementById(\'modalScrim\').classList.remove(\'show\'); });\n\ndocument.getElementById(\'globalSearch\').addEventListener(\'keydown\', (e)=>{\n  if(e.key===\'Enter\'){\n    const q = e.target.value.trim();\n    if(!q) return;\n    popFiltro = { cat:\'todas\', q:q };\n    navigate(\'pops\');\n  }\n});\n\n/* inicialização */\nrenderNav();\nnavigate(\'home\');\n</script>\n</body>\n</html>\n', '', '', 'inherit', 'closed', 'closed', '', '9-revision-v1', '', '', '2026-09-09 13:12:17', '2026-09-09 16:12:17', '', 9, 'http://localhost/faramcia_SL/wordpress/?p=10', 0, 'revision', '', 0);
